scripts.aura_totem = {}

function scripts.aura_totem.update(this, store)
	local last_hit_ts = 0
	local a = this.aura
	local ring_sid = 1
	local ground_sid = 2
	local totem_sid = 3

	if GR:cell_is(this.pos.x, this.pos.y, TERRAIN_WATER) then
		local fx = E:create_entity("fx")

		fx.pos.x, fx.pos.y = this.pos.x, this.pos.y
		fx.render.sprites[1].name = "totem_water_fx_enter"
		fx.render.sprites[1].anchor.y = 0.09
		fx.render.sprites[1].ts = store.tick_ts

		simulation:queue_insert_entity(fx)
	end

	this.render.sprites[ring_sid].ts = store.tick_ts

	U.animation_start(this, "start", nil, store.tick_ts, false, totem_sid)

	while not U.animation_finished(this, totem_sid) do
		coroutine.yield()
	end

	local total_duration = a.duration + a.duration_inc * a.level

	while store.tick_ts - this.aura.ts < total_duration do
		local enemies = U.find_enemies_in_range_filter_off(this.pos, this.aura.radius, this.aura.vis_flags, this.aura.vis_bans)

		if enemies then
			local mods = this.aura.mods or {this.aura.mod}
			local extra_duration = total_duration - (store.tick_ts - this.aura.ts)
			for _, enemy in ipairs(enemies) do
				for _, mod in ipairs(mods) do
					local new_mod = E:create_entity(mod)

					new_mod.modifier.level = this.aura.level
					new_mod.modifier.target_id = enemy.id
					new_mod.modifier.source_id = this.id
					new_mod.modifier.duration = new_mod.modifier.duration + extra_duration
					simulation:queue_insert_entity(new_mod)
				end
			end
		end

		last_hit_ts = store.tick_ts

		while store.tick_ts - last_hit_ts < this.aura.cycle_time do
			coroutine.yield()
		end
	end

	if GR:cell_is(this.pos.x, this.pos.y, TERRAIN_WATER) then
		local fx = E:create_entity("fx")

		fx.pos.x, fx.pos.y = this.pos.x, this.pos.y
		fx.render.sprites[1].name = "totem_water_fx_exit"
		fx.render.sprites[1].anchor.y = 0.09
		fx.render.sprites[1].ts = store.tick_ts

		simulation:queue_insert_entity(fx)
	end

	this.render.sprites[ground_sid].hidden = true
	this.render.sprites[ring_sid].hidden = true

	S:queue("TotemVanish")
	U.animation_start(this, "end", nil, store.tick_ts, false, totem_sid)

	while not U.animation_finished(this, totem_sid) do
		coroutine.yield()
	end

	simulation:queue_remove_entity(this)
end

scripts.pestilence = {}

function scripts.pestilence.insert(this, store)
	local duration = this.aura.duration + this.aura.level * this.aura.duration_inc

	this.actual_duration = duration

	this.aura.ts = store.tick_ts

	local decal = E:create_entity("decal_tween")

	decal.pos.x, decal.pos.y = this.pos.x, this.pos.y
	decal.tween.props[1].keys = {{0, 0}, {0.1, 255}, {duration, 255}, {duration + 1.2, 0}}
	decal.tween.props[1].name = "alpha"
	decal.render.sprites[1].name = "NecroPestilenceDecal"
	decal.render.sprites[1].animated = false
	decal.render.sprites[1].z = Z_DECALS
	decal.render.sprites[1].ts = store.tick_ts

	simulation:queue_insert_entity(decal)

	local smoke_offsets = {v(-17, 5), v(6, 13), v(3, -5), v(23, 3)}

	for i, off in ipairs(smoke_offsets) do
		local sm = E:create_entity("decal_tween")

		sm.pos.x, sm.pos.y = this.pos.x + off.x, this.pos.y + off.y
		sm.tween.props[1].keys = {{0, 0}, {0.1, 255}, {duration, 255}, {duration + 1.2, 0}}
		sm.tween.props[1].name = "alpha"
		sm.render.sprites[1].name = "pestilence_fx_decal_smoke"
		sm.render.sprites[1].z = Z_OBJECTS
		sm.render.sprites[1].ts = store.tick_ts
		sm.render.sprites[1].time_offset = i * 6 / FPS

		simulation:queue_insert_entity(sm)
	end

	local s = E:create_entity("decal_timed")

	s.pos.x, s.pos.y = this.pos.x, this.pos.y
	s.render.sprites[1].name = "pestilence_fx_start_smoke"
	s.render.sprites[1].ts = store.tick_ts
	s.render.sprites[1].time_offset = math.random(0, 3) / 30

	simulation:queue_insert_entity(s)

	return true
end

scripts.necromancer_aura = {}

function scripts.necromancer_aura.update(this, store)
	local last_ts = store.tick_ts
	local tower_skeletons_count = 0
	local skeletons = {}

	local function filter_fn(v)
		return v.health.dead and band(v.vis.bans, F_SKELETON) == 0 and band(v.health.last_damage_types, DAMAGE_EAT) == 0 and store.tick_ts - v.health.death_ts >= v.health.dead_lifetime - this.aura.cycle_time
	end

	while true do
		local source = store.entities[this.aura.source_id]

		if not source then
			simulation:queue_remove_entity(this)

			return
		end

		if store.tick_ts - last_ts >= this.aura.cycle_time then
			last_ts = store.tick_ts

			for i = #skeletons, 1, -1 do
				local e = skeletons[i]

				if e.health.dead then
					table.remove(skeletons, i)
				end
			end

			tower_skeletons_count = #skeletons

			local max_spawns = this.max_skeletons_tower - tower_skeletons_count

			if max_spawns < 1 then
			-- block empty
			else
				local dead_enemies = U.find_enemies_in_range_filter_override(this.pos, source.attacks.range, filter_fn)

				if #dead_enemies > 0 then
					dead_enemies = table.slice(dead_enemies, 1, max_spawns)

					for _, dead in ipairs(dead_enemies) do
						U.bans_add(dead.vis, F_SKELETON)
						dead.health.delete_after = 0

						local e

						if dead.health.hp_max > this.min_health_for_knight then
							e = E:create_entity("soldier_skeleton_knight")
						else
							e = E:create_entity("soldier_skeleton")
						end

						e.pos = V.vclone(dead.pos)

						if dead.enemy.necromancer_offset then
							e.pos.x = e.pos.x + dead.enemy.necromancer_offset.x * (dead.render.sprites[1].flip_x and -1 or 1)
							e.pos.y = e.pos.y + dead.enemy.necromancer_offset.y
						end

						e.nav_rally.center = V.vclone(e.pos)
						e.nav_rally.pos = V.vclone(e.pos)
						e.soldier.tower_id = source.id
						SU.soldier_inherit_tower_buff_factor(e, source, store.tick_ts)
						skeletons[#skeletons + 1] = e

						simulation:queue_insert_entity(e)
					end
				end
			end
		end

		coroutine.yield()
	end
end

scripts.mod_death_rider = {}

function scripts.mod_death_rider.insert(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]
	local level = m.level

	if not target or not target.health or target.health.dead then
		return false
	end

	m.extra_armor = (1 - target.health.armor) * (this.extra_armor + this.extra_armor_inc * level)

	SU.armor_inc(target, m.extra_armor)

	target.unit.damage_factor = target.unit.damage_factor * (this.inflicted_damage_factor + this.inflicted_damage_factor_inc * level)

	return true
end

function scripts.mod_death_rider.remove(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]
	local level = m.level

	if target then
		SU.armor_dec(target, m.extra_armor)

		target.unit.damage_factor = target.unit.damage_factor / (this.inflicted_damage_factor + this.inflicted_damage_factor_inc * level)
	end

	return true
end

scripts.drill = {}

function scripts.drill.update(this, store)
	local b = this.bullet
	local target = store.entities[b.target_id]

	if not target or target.health.dead then
		simulation:queue_remove_entity(this)

		return
	end

	local no = P:predict_enemy_node_advance(target, b.flight_time)
	local pos = P:node_pos(target.nav_path.pi, target.nav_path.spi, target.nav_path.ni + no)

	if GR:cell_is(pos.x, pos.y, TERRAIN_WATER) then
		U.animation_start_default(this, "water", nil, store.tick_ts, false)
	else
		U.animation_start_default(this, "ground", nil, store.tick_ts, false)
	end

	while store.tick_ts - this.render.sprites[1].ts < this.hit_time do
		coroutine.yield()
	end

	local d = E.assign_damage(DAMAGE_EAT, 0, this.id, target.id)
	d.pop = b.pop
	d.pop_conds = b.pop_conds
	d.pop_chance = b.pop_chance

	queue_damage(store, d)

	while not U.animation_finished_default(this) do
		coroutine.yield()
	end

	simulation:queue_remove_entity(this)
end

