end

scripts.aura_razorboar_rage = {}

function scripts.aura_razorboar_rage.insert(this, store)
	local source = store.entities[this.aura.source_id]

	if not source then
		return false
	end

	local ma = source.melee.attacks[1]

	this._ini_damage_max = ma.damage_max
	this._ini_damage_min = ma.damage_min

	return true
end

function scripts.aura_razorboar_rage.remove(this, store)
	local source = store.entities[this.aura.source_id]

	if source then
		local ma = source.melee.attacks[1]

		ma.damage_max = this._ini_damage_max
		ma.damage_min = this._ini_damage_min
	end

	return true
end

function scripts.aura_razorboar_rage.update(this, store)
	local a = this.aura
	local te = store.entities[a.source_id]

	if not te then
		simulation:queue_remove_entity(this)
	end

	local ma = te.melee.attacks[1]
	local ini_damage_max = ma.damage_max
	local ini_damage_min = ma.damage_min

	this.pos = te.pos

	while true do
		te = store.entities[a.source_id]

		if not te or te.health and te.health.dead and not a.track_dead then
			break
		end

		local h = te.health
		local hp_lost_factor = (h.hp_max - h.hp) / h.hp_max * this.damage_hp_factor

		ma.damage_min = ini_damage_min * (1 + hp_lost_factor)
		ma.damage_max = ini_damage_max * (1 + hp_lost_factor)

		coroutine.yield()
	end

	simulation:queue_remove_entity(this)
end

scripts.editor_aura_spider_sprint = {}

function scripts.editor_aura_spider_sprint.update(this, store)
	while true do
		this.render.sprites[1].scale = V.vv(this.aura.radius / 50)

		coroutine.yield()
	end
end

scripts.aura_mactans_path_web = {}

function scripts.aura_mactans_path_web.update(this, store)
	local a = this.aura

	a.ts = store.tick_ts

	local remaining_time = this.aura.duration
	local used_eggs = {}

	local function insert_webs(off_idx)
		local npos = {P:node_pos(this.pi, 1, this.ni + off_idx * this.step_nodes), P:node_pos(this.pi, 2, this.ni + off_idx * this.step_nodes), P:node_pos(this.pi, 3, this.ni + off_idx * this.step_nodes)}

		for spi = 1, 3 do
			local pos = npos[spi]

			if spi == 1 and off_idx <= this.steps_count_auras then
				local e = E:create_entity("aura_spider_sprint")

				e.aura.duration = remaining_time
				e.aura.radius = a.radius
				e.pos.x, e.pos.y = pos.x, pos.y

				simulation:queue_insert_entity(e)

				local targets = U.find_soldiers_in_range(store.soldiers, pos, 0, a.radius, a.vis_flags, a.vis_bans)

				if targets then
					for _, target in ipairs(targets) do
						local m = E:create_entity("mod_mactans_spider_web")

						m.pos.x, m.pos.y = target.pos.x, target.pos.y
						m.modifier.source_id = this.id
						m.modifier.target_id = target.id

						simulation:queue_insert_entity(m)
					end
				end

				local sel_eggs = table.filter(this.eggs, function(_, e)
					return not table.contains(used_eggs, e) and V.dist(e.pos.x, e.pos.y, pos.x, pos.y) < a.radius
				end)

				for _, egg in pairs(sel_eggs) do
					log.debug("----- EGG:%s", getfulldump(egg))
					table.insert(used_eggs, egg)

					local e = E:create_entity("spider_arachnomancer_egg_spawner")

					e.pos.x, e.pos.y = egg.pos.x, egg.pos.y
					e.spawn_once = true
					e.spawner.spawn_data = {}
					e.spawner.count = this.qty_per_egg
					e.spawner.pi = egg.node_pi
					e.spawner.spi = egg.node_spi
					e.spawner.ni = egg.node_ni

					simulation:queue_insert_entity(e)
				end
			end

			local d = E:create_entity("decal_mactans_path_web_" .. math.random(1, 3))

			d.pos.x, d.pos.y = pos.x + math.random(-15, 15), pos.y + math.random(-15, 15)
			d.tween.ts = store.tick_ts + U.frandom(0, this.step_delay * 0.6)
			d.duration = remaining_time
			d.fade_duration = this.fade_duration + U.frandom(fts(5), fts(15))

			local scale_factor = U.frandom(0.8, 1.3)

			d.render.sprites[1].scale = v(U.random_sign() * scale_factor, U.random_sign() * scale_factor)

			simulation:queue_insert_entity(d)
		end
	end

	for i = 0, this.steps_count do
		remaining_time = this.aura.duration - (store.tick_ts - a.ts)

		insert_webs(i)

		if i > 0 then
			insert_webs(-i)
		end

		U.y_wait_unconditional(store, this.step_delay)

		if this.interrupt then
			break
		end
	end

	U.y_wait_unconditional(store, remaining_time)
	simulation:queue_remove_entity(this)
end

scripts.mod_blood_elves = {}

function scripts.mod_blood_elves.insert(this, store)
	if math.random() >= this.chance or not scripts.mod_dps.insert(this, store) then
		return false
	end

	local target = store.entities[this.modifier.target_id]

	if not target then
		return false
	end

	local _, modifiers = U.has_modifier_types(store, target, this.modifier.type)

	if #modifiers >= this.modifier.max_of_same then
		return false
	end

	local source_damage = this.modifier.source_damage

	if not source_damage then
		return false
	end

	for _, m in ipairs(modifiers) do
		if m.dps then
			m.dps.fx = nil
		end
	end

	local pred_damage = U.predict_damage(target, source_damage)
	local actual_damage = math.max(this.damage_factor * pred_damage, 1)

	this.dps.damage_min = actual_damage
	this.dps.damage_max = actual_damage
	this.modifier.damage_factor = 1

	return true
end

scripts.mod_archer_magic = {}

function scripts.mod_archer_magic.insert(this, store)
	local target = store.entities[this.modifier.target_id]
	if not target then
		return false
	end

	local source_damage = this.modifier.source_damage
	if not source_damage then
		return false
	end

	local dmg = E.assign_damage(DAMAGE_MAGICAL, math.ceil(math.max(source_damage.value * this._mod_archer_magic_factor, 1)), this.modifier.source_id, target.id)
	queue_damage(store, dmg)
	return false
end

scripts.mod_timelapse = {}

function scripts.mod_timelapse.insert(this, store)
	local target = store.entities[this.modifier.target_id]

	if target and not target.health.dead and U.flags_pass(target.vis, this.modifier) then
		SU.stun_inc(target)
		U.cast_silence(target, store.tick_ts)

		return true
	end

	return false
end

function scripts.mod_timelapse.remove(this, store)
	if this._decal_timelapse then
		simulation:queue_remove_entity(this._decal_timelapse)
		this._decal_timelapse = nil
	end

	local target = store.entities[this.modifier.target_id]

	if target and not target.health.dead then
		SU.stun_dec(target)
		U.remove_silence(target, store.tick_ts)

		if target.health_bar then
			target.health_bar.hidden = nil
		end

		U.sprites_show(target, nil, nil, true)
		SU.show_modifiers(store, target, true, this)
		SU.show_auras(store, target, true)
	else
		if this.template_name == "mod_timelapse" then
			local e = E:create_entity("high_elven_sentinel_extra")
			if target then
				e.pos:set(target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y)
			else
				e.pos:copy(this.pos)
			end

			simulation:queue_insert_entity(e)
		end
	end

	return true
end

function scripts.mod_timelapse.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or target.health.dead then
		simulation:queue_remove_entity(this)

		return
	end

	m.ts = store.tick_ts
	this.pos.x, this.pos.y = target.pos.x, target.pos.y
	this.render.sprites[1].offset.y = target.unit.hit_offset.y

	local es = E:create_entity("timelapse_enemy_decal")

	this._decal_timelapse = es
	es.pos.x, es.pos.y = target.pos.x, target.pos.y
	es.render = U.render_clone(target.render)

	local tween_keys = es.tween.props[1].keys

	for i, s in ipairs(es.render.sprites) do
		es.tween.props[i] = E:clone_c("tween_prop")
		es.tween.props[i].keys = tween_keys
		es.tween.props[i].sprite_id = i
	end

	simulation:queue_insert_entity(es)
	U.unblock_all(store, target)

	if target.health_bar then
		target.health_bar.hidden = true
	end

	U.sprites_hide(target, nil, nil, true)
	SU.hide_modifiers(store, target, true, this)
	SU.hide_auras(store, target, true)
	U.animation_start(this, "start", nil, store.tick_ts, false, 1)

	this.tween.ts = store.tick_ts

	U.y_wait_unconditional(store, fts(10))

	es.tween.ts = store.tick_ts
	es.tween.disabled = false

	U.y_animation_wait_default(this)
	U.animation_start(this, "loop", nil, store.tick_ts, true, 1)
	U.y_wait_conditional(store, m.duration - (store.tick_ts - m.ts) - fts(10), function(store, time)
		return this.interrupt or target.health.dead
	end)
	S:queue("TowerHighMageTimeCastEnd")
	U.animation_start(this, "end", nil, store.tick_ts, false, 1)

	local d = E.assign_damage(this.damage_type, this.damage_levels[m.level], this.id, target.id)

	queue_damage(store, d)

	this.tween.ts = store.tick_ts
	this.tween.reverse = true

	U.y_wait_unconditional(store, fts(5))

	es.tween.reverse = true
	es.tween.ts = store.tick_ts

	while not U.animation_finished_default(this) do
		if target.health.dead then
			for i = 1, #es.render.sprites do
				es.render.sprites[i].hidden = true
			end
		end
		coroutine.yield()
	end

	-- U.y_animation_wait_default(this)

	if this.interrupt then
		target.health.hp = 0

		if target.death_spawns then
			target.health.last_damage_types = DAMAGE_NO_SPAWNS
		end
	end

	signal.emit("mod-applied", this, target)
	simulation:queue_remove_entity(this)
end

scripts.mod_arrow_arcane_slumber = {}

function scripts.mod_arrow_arcane_slumber.insert(this, store)
	if scripts.mod_stun.insert(this, store) then
		local e = E:create_entity("mod_arrow_arcane")

		e.modifier.target_id = this.modifier.target_id

		simulation:queue_insert_entity(e)

		this.render.sprites[2].flip_x = false

		return true
	end

	return false
end

scripts.mod_arrow_silver_mark = {}

function scripts.mod_arrow_silver_mark.insert(this, store)
	local target = store.entities[this.modifier.target_id]

	if not target or target.health.dead or not target.unit then
		return false
	end

	local boss_factor = band(target.vis.flags, F_BOSS) ~= 0 and 0.5 or 1

	this.received_damage_factor = (this.received_damage_factor - 1) * boss_factor + 1
	target.health.damage_factor = target.health.damage_factor * this.received_damage_factor

	signal.emit("mod-applied", this, target)

	return true
end

function scripts.mod_arrow_silver_mark.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.pos then
		simulation:queue_remove_entity(this)

		return
	end

	this.pos = target.pos
	m.duration = m.durations[m.level]
	m.ts = store.tick_ts

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or store.tick_ts - m.ts > m.duration then
			this.tween.props[3].disabled = nil
			this.tween.props[4].disabled = nil
			this.tween.props[3].ts = store.tick_ts
			this.tween.props[4].ts = store.tick_ts

			U.y_wait_unconditional(store, this.tween.props[3].keys[2][1])
			simulation:queue_remove_entity(this)

			return
		end

		coroutine.yield()
	end
end

function scripts.mod_arrow_silver_mark.remove(this, store)
	local target = store.entities[this.modifier.target_id]

	if target and target.health and target.unit then
		target.health.damage_factor = target.health.damage_factor / this.received_damage_factor
	end

	return true
end

scripts.mod_eldritch = {}

function scripts.mod_eldritch.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.health or target.health.dead or not U.flags_pass(target.vis, this.modifier) then
		simulation:queue_remove_entity(this)

		return
	end

	local es = E:create_entity("eldritch_enemy_decal")

	es.pos.x, es.pos.y = target.pos.x, target.pos.y
	es.render = U.render_clone(target.render)
	es.render.sprites[1].name = "idle"

	simulation:queue_insert_entity(es)

	local show_blood_pool = target.unit.show_blood_pool
	local d = E.assign_damage(DAMAGE_EAT, 0, this.id, target.id)

	queue_damage(store, d)

	local s = this.render.sprites[1]

	s.ts = store.tick_ts
	this.pos = V.vclone(target.pos)
	s.offset.x = target.unit.mod_offset.x
	s.offset.y = target.unit.mod_offset.y

	S:queue(this.sound_events.loop)

	es.tween.disabled = nil
	es.tween.ts = store.tick_ts

	U.y_wait_unconditional(store, es.tween.props[1].keys[#es.tween.props[1].keys][1])
	S:stop(this.sound_events.loop)

	local fx = E:create_entity("fx_eldritch_explosion")

	fx.pos.x, fx.pos.y = target.pos.x + target.unit.mod_offset.x, target.pos.y + target.unit.mod_offset.y
	fx.render.sprites[1].ts = store.tick_ts

	simulation:queue_insert_entity(fx)

	local terrain_type = band(GR:cell_type(target.pos.x, target.pos.y), TERRAIN_TYPES_MASK)

	if target.unit and target.unit.can_explode and target.unit.explode_fx and band(terrain_type, TERRAIN_WATER) == 0 then
		S:queue(target.sound_events.death_by_explosion)

		local fx = E:create_entity(target.unit.explode_fx)

		fx.pos = V.vclone(target.pos)
		fx.render.sprites[1].ts = store.tick_ts
		fx.render.sprites[1].name = fx.render.sprites[1].size_names[target.unit.size]

		simulation:queue_insert_entity(fx)
	end

	if target.unit and show_blood_pool and target.unit.blood_color ~= BLOOD_NONE and band(terrain_type, TERRAIN_WATER) == 0 then
		local decal = E:create_entity("decal_blood_pool")

		decal.pos = V.vclone(target.pos)
		decal.render.sprites[1].ts = store.tick_ts
		decal.render.sprites[1].name = target.unit.blood_color
		decal.render.sprites[1].z = target.render.sprites[1].z
		decal.render.sprites[1].sort_y_offset = 1

		simulation:queue_insert_entity(decal)
	end

	local targets = U.find_enemies_in_range_filter_off(this.pos, this.damage_radius, this.damage_flags, this.damage_bans)

	if targets then
		for _, t in ipairs(targets) do
			local d = E.assign_damage(this.damage_type, this.damage_levels[m.level] * m.damage_factor, this.id, t.id)

			queue_damage(store, d)
		end
	end

	signal.emit("mod-applied", this, target)
	simulation:queue_remove_entity(this)
end

scripts.mod_pixie_pickpocket = {}

function scripts.mod_pixie_pickpocket.insert(this, store)
	local m, pp = this.modifier, this.pickpocket
	local target = store.entities[m.target_id]

	if not target or not target.enemy then
		return false
	end

	if target.enemy.gold_bag > 0 then
		local q = km.clamp(0, target.enemy.gold_bag, math.random(pp.steal_min[m.level], pp.steal_max[m.level]))

		if q > 0 then
			target.enemy.gold_bag = target.enemy.gold_bag - q
			store.player_gold = store.player_gold + q
		end

		local pop = SU.create_pop(store, target.pos, pp.pop)

		simulation:queue_insert_entity(pop)

		local fx = E:create_entity(pp.fx)

		fx.pos.x, fx.pos.y = target.pos.x, target.pos.y
		fx.render.sprites[1].ts = store.tick_ts

		simulation:queue_insert_entity(fx)
	end

	local damage = E.assign_damage(m.damage_type, math.random(m.damage_min, m.damage_max) * m.damage_factor, m.source_id, target.id)

	queue_damage(store, damage)

	return false
end

scripts.mod_bravebark_branchball = {}

function scripts.mod_bravebark_branchball.insert(this, store)
	local target = store.entities[this.modifier.target_id]

	if not target then
		return false
	end

	U.bans_add(target.vis, F_ALL)

	SU.stun_inc(target)
	return true
end

function scripts.mod_bravebark_branchball.update(this, store)
	local target = store.entities[this.modifier.target_id]
	local source = store.entities[this.modifier.source_id]

	if not target or not source then
		simulation:queue_remove_entity(this)

		return
	end

	local af = source.pos.x > target.pos.x

	this.pos.x, this.pos.y = target.pos.x, target.pos.y

	U.y_wait_unconditional(store, fts(7))
	S:queue("ElvesHeroForestElementalHomerun")
	U.y_wait_unconditional(store, fts(10))

	this.render.sprites[1].hidden = false
	this.render.sprites[1].ts = store.tick_ts

	local decal = E:create_entity("decal_bravebark_rootspikes_hit")

	decal.pos.x, decal.pos.y = this.pos.x, this.pos.y
	decal.tween.ts = store.tick_ts

	simulation:queue_insert_entity(decal)
	U.y_wait_unconditional(store, fts(16))

	local fx = E:create_entity("fx_bravebark_branchball_hit")

	fx.pos.x, fx.pos.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
	fx.render.sprites[1].ts = store.tick_ts

	simulation:queue_insert_entity(fx)

	local d = E.assign_damage(DAMAGE_EAT, 0, this.id, target.id)

	queue_damage(store, d)

	local es = E:create_entity("decal_bravebark_branchball_enemy_clone")

	es.pos.x, es.pos.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
	es.render = U.render_clone(target.render)
	es.render.sprites[1].anchor = this.custom_anchors[target.template_name] or this.custom_anchors.default
	es.tween.disabled = nil
	es.tween.ts = store.tick_ts

	local dx, dy = V.rotate(math.random(20, 45) * math.pi / 180, math.random(240, 300), 0)

	dx = (af and -1 or 1) * dx
	es.tween.props[2].keys[2][2].x, es.tween.props[2].keys[2][2].y = dx, dy
	es.tween.props[3].keys[2][2] = (af and -1 or 1) * math.random(300, 400) * math.pi / 180

	simulation:queue_insert_entity(es)
	U.y_animation_wait_default(this)
	simulation:queue_remove_entity(this)
end

scripts.mod_bravebark_springsap = {}

function scripts.mod_bravebark_springsap.insert(this, store)
	if not scripts.mod_hps.insert(this, store) then
		return false
	end

	local target = store.entities[this.modifier.target_id]

	if target.template_name == "hero_bravebark" then
		this.render.sprites[1].hidden = true
	else
		this.render.sprites[1].ts = store.tick_ts
	end

	return true
end

scripts.mod_catha_curse = {}

function scripts.mod_catha_curse.insert(this, store)
	if math.random() < this.chance and scripts.mod_stun.insert(this, store) then
		return true
	else
		return false
	end
end

scripts.mod_rag_raggified = {}

function scripts.mod_rag_raggified.update(this, store)
	local function add_fx(target, pos)
		local fx = E:create_entity(this.fx)
		local s = fx.render.sprites[1]

		s.ts = store.tick_ts

		if s.size_scales then
			s.scale = s.size_scales[target.unit.size]
		end

		fx.pos = V.vclone(pos)

		if target.unit.hit_offset then
			fx.pos.x, fx.pos.y = fx.pos.x + target.unit.hit_offset.x, fx.pos.y + target.unit.hit_offset.y
		end

		simulation:queue_insert_entity(fx)
	end

	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or target.health.dead or band(target.vis.bans, F_RAGGIFY) ~= 0 then
		simulation:queue_remove_entity(this)

		return
	end

	U.bans_add(target.vis, F_RAGGIFY)

	add_fx(target, target.pos)
	SU.remove_modifiers(store, target, nil, "mod_rag_raggified")
	SU.remove_auras(store, target)
	simulation:queue_remove_entity(target)

	target.health.dead = true
	target.main_script.co = nil
	target.main_script.runs = 0

	U.unblock_all(store, target)

	if target.ui then
		target.ui.can_click = false
	end

	if target.count_group then
		target.count_group.in_limbo = true
	end

	local e = E:create_entity(this.entity_name)

	e.pos = V.vclone(target.pos)

	if target.melee then
		e.melee.attacks[1].damage_max = target.melee.attacks[1].damage_max
		e.melee.attacks[1].damage_min = target.melee.attacks[1].damage_min
	end

	e.health.hp_max = target.health.hp
	e.health.hp = target.health.hp
	e.nav_rally.center = V.vclone(target.pos)
	e.nav_rally.pos = V.vclone(target.pos)
	e.render.sprites[1].flip_x = target.render.sprites[1].flip_x
	e.render.sprites[1].scale = target.unit.size == UNIT_SIZE_SMALL and V.vv(0.75) or V.vv(1)

	simulation:queue_insert_entity(e)

	local start_ts = store.tick_ts

	while (not e.health.dead) and (e.health.hp_max - e.health.hp < e.health.hp_max * this.break_factor or store.tick_ts - start_ts < this.doll_duration) do
		coroutine.yield()
	end

	if not e.health.dead then
		local hp = e.health.hp

		e.health.dead = true

		simulation:queue_remove_entity(e)

		local nodes = P:nearest_nodes(e.pos.x, e.pos.y, {target.nav_path.pi}, nil)

		if #nodes > 0 then
			target.nav_path.ni = nodes[1][3] + 1
		end

		target.pos = V.vclone(e.pos)
		target.main_script.runs = 1
		target.health.dead = false
		target.health.hp = hp

		if target.ui then
			target.ui.can_click = true
		end

		if target.count_group then
			target.count_group.in_limbo = nil
		end

		U.bans_remove(target.vis, F_RAGGIFY)

		simulation:queue_insert_entity(target)
	else
		store.player_gold = store.player_gold + target.enemy.gold

		signal.emit("got-enemy-gold", target, target.enemy.gold)
	end

	add_fx(target, e.pos)
	simulation:queue_remove_entity(this)
end

scripts.mod_lilith_soul_eater_track = {}

function scripts.mod_lilith_soul_eater_track.update(this, store)
	local hero = store.entities[this.modifier.source_id]

	if not hero then
		log.error("hero not found for mod_lilith_soul_eater")
	else
		this.modifier.ts = store.tick_ts

		while true do
			local target = store.entities[this.modifier.target_id]

			if not target or store.tick_ts - this.modifier.ts > this.modifier.duration then
				break
			end

			if target.health.dead and hero.soul_eater.active and target.melee and target.melee.attacks and not U.flag_has(target.health.last_damage_types, DAMAGE_NO_LIFESTEAL) then
				local ma = target.melee.attacks[1]
				local stolen_damage = (ma.damage_min + ma.damage_max) * 0.5
				local s = E:create_entity("decal_lilith_soul_eater_ball")

				s.target_id = hero.id
				s.source_id = target.id
				s.stolen_damage = stolen_damage

				simulation:queue_insert_entity(s)

				hero.soul_eater.last_ts = store.tick_ts

				break
			end

			coroutine.yield()
		end
	end

	simulation:queue_remove_entity(this)
end

scripts.mod_bruce_sharp_claws = {}

function scripts.mod_bruce_sharp_claws.insert(this, store)
	local target = store.entities[this.modifier.target_id]

	if not target then
		return false
	end

	local has_mods = U.has_modifier_types(store, target, this.modifier.type, MOD_TYPE_POISON)

	if has_mods then
		local d = E.assign_damage(this.extra_bleeding_damage_type, this.extra_bleeding_damage, this.id, target.id)
		queue_damage(store, d)

		return false
	else
		if not scripts.mod_dps.insert(this, store) then
			return false
		end

		local ref = store.entities[this.modifier.source_id]

		if ref then
			SU.hero_gain_xp_from_skill(ref, ref.hero.skills[this.xp_from_skill])
		end

		return true
	end
end

scripts.mod_phoenix_flaming_path = {}

function scripts.mod_phoenix_flaming_path.update(this, store)
	local m = this.modifier
	local ca = this.custom_attack
	local target = store.entities[m.target_id]
	local ending, fx_pos

	if not target or not target.tower then
	-- block empty
	else
		m.ts = store.tick_ts
		ca.ts = store.tick_ts
		fx_pos = V.vclone(target.pos)

		if this.custom_offsets and this.custom_offsets[target.template_name] then
			local o = this.custom_offsets[target.template_name]

			for _, s in pairs(this.render.sprites) do
				s.offset.x = s.offset.x + o.x
				s.offset.y = s.offset.y + o.y
			end

			fx_pos.x, fx_pos.y = fx_pos.x + o.x, fx_pos.y + o.y
		end

		SU.insert_sprite(store, ca.fx_start, fx_pos)

		while true do
			target = store.entities[m.target_id]

			if not target or store.tick_ts - m.ts > m.duration then
				break
			end

			if target and not ending and store.tick_ts - m.ts >= m.duration - 0.3 then
				ending = true

				SU.insert_sprite(store, ca.fx_end, fx_pos)
			end

			if store.tick_ts - ca.ts > ca.cooldown then
				ca.ts = store.tick_ts

				SU.insert_sprite(store, ca.fx, fx_pos)
				U.y_wait_unconditional(store, ca.hit_time)

				local targets = U.find_enemies_in_range_filter_off(target.pos, ca.radius, ca.vis_flags, ca.vis_bans)

				if targets then
					for _, t in ipairs(targets) do
						local d = E.assign_damage(ca.damage_type, ca.damage, this.id, t.id)

						queue_damage(store, d)

						local m = E:create_entity(ca.mod)

						m.modifier.source_id = this.id
						m.modifier.target_id = t.id

						simulation:queue_insert_entity(m)
					end
				end
			end

			coroutine.yield()
		end
	end

	simulation:queue_remove_entity(this)
end

scripts.mod_phoenix_purification = {}

function scripts.mod_phoenix_purification.update(this, store)
	local m = this.modifier
	local target

	m.ts = store.tick_ts

	while true do
		target = store.entities[m.target_id]

		if not target or store.tick_ts - m.ts > m.duration then
			break
		end

		if target.health.dead then
			SU.insert_sprite(store, this.fx, target.pos)
			U.y_wait_unconditional(store, fts(2))

			local e = E:create_entity(this.entity)

			e.pos = V.vclone(target.pos)
			e.bullet.from = V.vclone(e.pos)
			e.bullet.to = v(target.pos.x, target.pos.y + 100)

			local aura = store.entities[m.source_id]

			e.bullet.source_id = this.id
			e.bullet.xp_dest_id = aura and aura.aura.source_id or nil
			e.bullet.shot_index = 0

			simulation:queue_insert_entity(e)

			break
		end

		coroutine.yield()
	end

	simulation:queue_remove_entity(this)
end

scripts.mod_gnoll_blighter = {}

function scripts.mod_gnoll_blighter.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.plant then
		simulation:queue_remove_entity(this)

		return
	end

	local p = target.plant

	m.ts = store.tick_ts
	this.render.sprites[1].ts = store.tick_ts
	this.pos.x, this.pos.y = target.pos.x, target.pos.y
	p.block_count = p.block_count + 1

	if p.block_count > 0 then
		p.blocked = true

		if this.ui then
			this.ui.can_click = false
		end
	end

	SU.tower_block_inc(target)
	U.y_wait_unconditional(store, m.duration)

	p.block_count = p.block_count - 1

	if p.block_count < 1 then
		p.blocked = nil
		p.block_count = 0

		if this.ui then
			this.ui.can_click = true
		end
	end

	simulation:queue_remove_entity(this)
end

function scripts.redcap_heal_side_effect(this, store, damage, target)
	local m = E:create_entity("mod_redcap_heal")
	m.modifier.source_id = this.id
	m.modifier.target_id = this.id
	if target then
		m.__redcap__target_id = target.id
	end
	simulation:queue_insert_entity(m)
end

scripts.mod_redcap_heal = {}

function scripts.mod_redcap_heal.insert(this, store)
	local target = store.entities[this.__redcap__target_id]
	local source = store.entities[this.modifier.source_id]

	if target and source then
		local fx = E:create_entity(this.hit_fx)

		fx.pos = V.vclone(target.pos)
		fx.render.sprites[1].ts = store.tick_ts
		fx.render.sprites[1].flip_x = target.pos.x < source.pos.x

		simulation:queue_insert_entity(fx)
	end

	return scripts.mod_hps.insert(this, store)
end

scripts.mod_twilight_avenger_last_service = {}

function scripts.mod_twilight_avenger_last_service.remove(this, store)
	local count_soldiers, count_enemies = 0, 0
	local target = store.entities[this.modifier.target_id]

	if this.modifier.removed_by_ban then
		return true
	end

	if not target then
		return true
	end

	if not target.health.dead then
		U.flags_remove(target.vis, F_DARK_ELF)
	else
		local targets = table.filter(store.entities, function(k, v)
			return not v.pending_removal and v.vis and v.health and not v.health.dead and band(v.vis.flags, this.explode_vis_bans) == 0 and band(v.vis.bans, this.explode_vis_flags) == 0 and U.is_inside_ellipse(v.pos, this.pos, this.explode_range) and not table.contains(this.explode_excluded_templates, v.template_name)
		end)

		if targets and #targets > 0 then
			for _, target in ipairs(targets) do
				local is_enemy = band(target.vis.flags, F_ENEMY) ~= 0
				local d = E.assign_damage(DAMAGE_MAGICAL_EXPLOSION, 0, this.id, target.id)

				if band(target.vis.flags, F_DARK_ELF) ~= 0 then
					d.value = 0
				else
					d.value = this.explode_damage
				end

				queue_damage(store, d)

				if is_enemy then
					count_enemies = count_enemies + 1
				else
					count_soldiers = count_soldiers + 1
				end
			end
		end

		if count_enemies > 0 and count_soldiers == 0 then
		-- AC:inc_check("LAST_SERVICE")
		end

		local p

		if U.flag_has(target.vis.flags, F_FLYING) then
			p = v(target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y)
		else
			p = v(target.pos.x, target.pos.y)
		end

		SU.insert_sprite(store, this.explode_fx, p)
	end

	return true
end

scripts.mod_twilight_scourger_lash = {}

function scripts.mod_twilight_scourger_lash.insert(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.health or target.health.dead then
		return false
	end

	m.ts = store.tick_ts

	U.speed_mul(target, this.speed_factor)

	target.unit.damage_factor = target.unit.damage_factor * this.damage_factor

	local s1, s2 = this.render.sprites[1], this.render.sprites[2]

	s1.ts, s2.ts = store.tick_ts, store.tick_ts
	s1.name = s1.size_names[target.unit.size]
	s2.scale = target.template_name == "enemy_twilight_avenger" and v(1, 1) or v(0.7, 0.7)
	s2.offset = s1.offset

	return true
end

function scripts.mod_twilight_scourger_lash.remove(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if target then
		U.speed_div(target, this.speed_factor)

		target.unit.damage_factor = target.unit.damage_factor / this.damage_factor
	end

	return true
end

scripts.mod_twilight_scourger_banshee = {}

function scripts.mod_twilight_scourger_banshee.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target then
		simulation:queue_remove_entity(this)

		return
	end

	target._is_banshee_target = nil
	m.ts = store.tick_ts

	SU.tower_block_inc(target)

	this.tween.ts = store.tick_ts

	U.y_wait_unconditional(store, m.duration - 0.2)

	local fx = E:create_entity("fx_twilight_scourger_banshee_end")

	fx.pos.x, fx.pos.y = this.pos.x, this.pos.y
	fx.render.sprites[1].ts = store.tick_ts

	simulation:queue_insert_entity(fx)
	SU.tower_block_dec(target)
	simulation:queue_remove_entity(this)
end

scripts.mod_spider_web = {}

function scripts.mod_spider_web.insert(this, store)
	local target = store.entities[this.modifier.target_id]

	if not target or target.health.dead then
		return false
	end

	if target.template_name == "soldier_blade" and target.dodge and target.dodge.chance > 0 and not target.unit.is_stunned and not target.timed_attacks.list[1].in_progress and target.powers[target.dodge.power_name].level > 0 and target.dodge.chance >= math.random() then
		log.debug("(%s)mod_spider_web blocked by (%s)soldier_blade perfect parry", this.id, target.id)

		target.dodge.active = true

		return false
	else
		return scripts.mod_stun.insert(this, store)
	end
end

scripts.mod_twilight_heretic_consume = {}

function scripts.mod_twilight_heretic_consume.insert(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target then
		return false
	end

	m.ts = store.tick_ts
	this._angles_walk = target.render.sprites[1].angles.walk
	this._health_bar_offset_y = target.health_bar.offset.y
	target.render.sprites[1].angles.walk = this.angles_walk

	U.speed_mul(target, this.speed_factor)

	target.ranged.attacks[1].disabled = true

	return true
end

function scripts.mod_twilight_heretic_consume.remove(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if target then
		target.render.sprites[1].angles.walk = this._angles_walk
		U.change_health_bar_offset_run_time(target.health_bar, this._health_bar_offset_y)

		U.speed_div(target, this.speed_factor)

		target.ranged.attacks[1].disabled = false
	end

	return true
end

function scripts.mod_twilight_heretic_consume.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.pos then
		simulation:queue_remove_entity(this)

		return
	end

	local st = target.render.sprites[1]
	local hboy = target.health_bar.offset.y

	this.pos = target.pos

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or m.duration >= 0 and store.tick_ts - m.ts > m.duration or P:nodes_to_goal(target.nav_path.pi, target.nav_path.spi, target.nav_path.ni) < this.nodes_limit then
			simulation:queue_remove_entity(this)

			return
		end

		local oy, hoy = 0, 0

		if string.starts(st.name, "flying") then
			oy = this.mod_offset_y
			hoy = this.health_bar_offset_y
		end

		this.render.sprites[1].offset.y = oy
		U.change_health_bar_offset_run_time(target.health_bar, hboy + hoy)

		coroutine.yield()
	end
end

scripts.mod_twilight_heretic_servant = {}

function scripts.mod_twilight_heretic_servant.update(this, store)
	local m = this.modifier
	local dps = this.dps
	local target = store.entities[m.target_id]
	local looping = false

	if not target then
		simulation:queue_remove_entity(this)

		return
	end

	m.ts = store.tick_ts
	dps.ts = store.tick_ts - dps.damage_every
	U.flags_add(target.vis, F_SERVANT)

	U.animation_start_default(this, "start", nil, store.tick_ts, false)

	while store.tick_ts - m.ts < m.duration do
		target = store.entities[m.target_id]

		if not target or target.health.dead then
			break
		end

		if not looping and U.animation_finished_default(this) then
			looping = true

			U.animation_start_default(this, "loop", nil, store.tick_ts, true)
		end

		if store.tick_ts - dps.ts >= dps.damage_every then
			dps.ts = store.tick_ts

			local d = E.assign_damage(dps.damage_type, math.random(dps.damage_min, dps.damage_max), this.id, target.id)

			queue_damage(store, d)
		end

		coroutine.yield()
	end

	if target then
		U.flags_remove(target.vis, F_SERVANT)
	end

	this.tween.disabled = nil
	this.tween.ts = store.tick_ts
end

scripts.mod_drider_poison = {}

function scripts.mod_drider_poison.update(this, store)
	local m = this.modifier
	local dps = this.dps
	local target
	local source = store.entities[m.source_id]
	local generation = source and source.generation + 1 or 1

	while store.tick_ts - m.ts < m.duration do
		target = store.entities[m.target_id]

		if not target then
			break
		end

		this.pos = target.pos

		if this.render and m.use_mod_offset and target.unit.mod_offset then
			this.render.sprites[1].offset.x, this.render.sprites[1].offset.y = target.unit.mod_offset.x, target.unit.mod_offset.y
		end

		if target.health.dead then
			coroutine.yield()
			coroutine.yield()

			if target.hero or (not target.health.dead) or (target.reinforcement and target.reinforcement.hp_before_timeout) then
				break
			end

			local ec = E:create_entity("decal_drider_clone")

			ec.render = U.render_clone(target.render)
			ec.pos.x, ec.pos.y = target.pos.x, target.pos.y

			simulation:queue_insert_entity(ec)
			coroutine.yield()
			U.sprites_hide(target)

			local e = E:create_entity("decal_drider_cocoon")
			local se = e.render.sprites[1]

			e.pos.x, e.pos.y = target.pos.x, target.pos.y - 1
			se.flip_x = ec.render.sprites[1].flip_x
			se.scale = se.size_scales[target.unit.size]
			e.generation = generation

			simulation:queue_insert_entity(e)

			break
		end

		if store.tick_ts - dps.ts >= dps.damage_every then
			dps.ts = store.tick_ts

			local d = E.assign_damage(dps.damage_type, dps.damage_max, this.id, target.id)

			queue_damage(store, d)
		end

		coroutine.yield()
	end

	simulation:queue_remove_entity(this)
end

scripts.decal_drider_cocoon = {}

function scripts.decal_drider_cocoon.update(this, store)
	U.y_animation_play(this, "start", nil, store.tick_ts)
	U.y_wait_unconditional(store, this.duration)
	U.y_animation_play(this, "end", nil, store.tick_ts)

	local nodes = P:nearest_nodes(this.pos.x, this.pos.y, nil, nil, true, NF_RALLY)

	if #nodes < 1 then
		log.error("(%s) decal_drider_cocoon: could not find valid node to spawn enemy. %s,%s", this.id, this.pos.x, this.pos.y)
		simulation:queue_remove_entity(this)

		return
	end

	local e = E:create_entity("enemy_drider")
	local n = e.nav_path

	e.pos.x, e.pos.y = this.pos.x, this.pos.y
	n.pi, n.spi, n.ni = nodes[1][1], nodes[1][2], nodes[1][3] + 2
	e.render.sprites[1].name = "raise"
	e.generation = this.generation
	e.melee.attacks[2].cooldown = e.melee.attacks[2].cooldown + e.generation * e.melee.attacks[2].cooldown_inc
	e.melee.attacks[2].ts = store.tick_ts

	simulation:queue_insert_entity(e)
	simulation:queue_remove_entity(this)
end

scripts.mod_razorboar_rampage_speed = {}

function scripts.mod_razorboar_rampage_speed.insert(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target then
		return false
	end

	this._initial_max_speed = target.motion.max_speed

	U.speed_mul(target, this.speed_factor)

	return true
end

function scripts.mod_razorboar_rampage_speed.remove(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if target then
		U.speed_div(target, this.speed_factor)
	end

	return true
end

function scripts.mod_razorboar_rampage_speed.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target then
		simulation:queue_remove_entity(this)

		return false
	end

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or not target.enemy.can_do_magic or store.tick_ts - m.ts >= m.duration then
			simulation:queue_remove_entity(this)

			return
		end

		coroutine.yield()
	end
end

scripts.mod_mactans_tower_block = {}

function scripts.mod_mactans_tower_block.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target then
		simulation:queue_remove_entity(this)

		return
	end

	SU.tower_block_inc(target)

	m.ts = store.tick_ts
	this.tween.ts = store.tick_ts

	U.y_wait_unconditional(store, m.duration + 4 * fts(17))
	U.sprites_hide(this, 1, 4)
	U.sprites_show(this, 5, 5)
	U.y_animation_play(this, "end", nil, store.tick_ts, 1, 5)
	SU.tower_block_dec(target)
	simulation:queue_remove_entity(this)
end

scripts.mod_bloodsydian_warlock = {}

function scripts.mod_bloodsydian_warlock.update(this, store)
	local target = store.entities[this.modifier.target_id]

	if not target or target.health.dead or not U.flags_pass(target.vis, this.modifier) then
		simulation:queue_remove_entity(this)

		return
	end

	SU.stun_inc(target)

	U.bans_add(target.vis, bor(F_MOD, F_TELEPORT, F_RANGED))
	target.health.ignore_damage = true
	target.ui.can_select = false

	U.sprites_hide(target, nil, nil, true)

	this.pos.x, this.pos.y = target.pos.x, target.pos.y

	U.animation_start_default(this, "start", target.render.sprites[1].flip_x, store.tick_ts)

	this.incubation_time = this.incubation_time + U.frandom(-this.incubation_time_variance, this.incubation_time_variance)

	U.y_wait_conditional(store, this.incubation_time, function()
		return target.health.dead
	end)
	U.sprites_show(target, nil, nil, true)

	U.bans_remove(target.vis, bor(F_MOD, F_TELEPORT, F_RANGED))
	target.health.ignore_damage = false

	if this.modifier.kill then
		local d = E.assign_damage(DAMAGE_TRUE, target.health.hp, this.id, target.id)

		queue_damage(store, d)
	elseif not target.health.dead and target.health.hp > 0 then
		local d = E.assign_damage(DAMAGE_EAT, 0, this.id, target.id)

		queue_damage(store, d)

		local e = E:create_entity(this.spawn_name)

		e.pos.x, e.pos.y = target.pos.x, target.pos.y
		e.nav_path = table.deepclone(target.nav_path)
		e.render.sprites[1].flip_x = target.render.sprites[1].flip_x
		e.enemy.gold = target.enemy.gold
		e.enemy.gold_bag = target.enemy.gold_bag

		simulation:queue_insert_entity(e)

		target.enemy.gold = 0
		target.enemy.gold_bag = 0
	end

	S:queue("ElvesCrystallizedGnoll")
	U.y_animation_play(this, "end", nil, store.tick_ts)
	simulation:queue_remove_entity(this)
end

scripts.mod_dark_spitters = {}

function scripts.mod_dark_spitters.update(this, store)
	local m = this.modifier
	local dps = this.dps
	local target

	while store.tick_ts - m.ts < m.duration do
		target = store.entities[m.target_id]

		if not target then
			break
		end

		this.pos = target.pos

		if this.render and m.use_mod_offset and target.unit.mod_offset then
			local flip_sign = target.render.sprites[1].flip_x and -1 or 1

			this.render.sprites[1].offset.x = target.unit.mod_offset.x * flip_sign
			this.render.sprites[1].offset.y = target.unit.mod_offset.y
		end

		if target.health.dead then
			coroutine.yield()
			coroutine.yield()

			if target.hero or not target.health.dead or target.reinforcement and target.reinforcement.hp_before_timeout then
				break
			end

			U.sprites_hide(target)
			SU.insert_sprite(store, this.explode_fx, target.pos)

			local nodes = P:nearest_nodes(target.pos.x, target.pos.y, nil, nil, true, NF_RALLY)

			if #nodes < 1 then
				log.error("(%s) mod_dark_spitters: could not find valid node nearby to spawn enemy. %s,%s", this.id, target.pos.x, target.pos.y)

				break
			end

			local pi, spi, ni = nodes[1][1], nodes[1][2], nodes[1][3]

			if P:nodes_to_defend_point(pi, spi, ni) < this.nodes_limit then
				break
			end

			local e = E:create_entity(this.spawn_entity)
			local n = e.nav_path

			e.pos.x, e.pos.y = target.pos.x, target.pos.y
			n.pi, n.spi, n.ni = pi, spi, ni + 2
			e.render.sprites[1].name = "raise"
			e.enemy.gold = 0
			e.enemy.gold_bag = 0

			simulation:queue_insert_entity(e)

			break
		end

		if store.tick_ts - dps.ts >= dps.damage_every then
			dps.ts = store.tick_ts

			local d = E.assign_damage(dps.damage_type, dps.damage_max, this.id, target.id)

			queue_damage(store, d)
		end

		coroutine.yield()
	end

	simulation:queue_remove_entity(this)
end

scripts.mactans_controller = {}

function scripts.mactans_controller.insert(this, store)
	if this.load_file then
		local fn = "data/levels/" .. this.load_file .. ".lua"
		local data, err = LU.eval_file(fn)

		if not data then
			log.error("mactans_controller failed loading file %s: %s", this.load_file, err)

			return false
		end

		this.sequence = data.sequence
		this.sequence_groups = data.sequence_groups
	end

	return true
end

function scripts.mactans_controller.update(this, store)
	local mactans = LU.list_entities(store.entities, "enemy_mactans")[1]
	local sequence = this.sequence and this.sequence[store.level_mode]

	if not this.sequence then
		log.error("mactans_controller not initialized. sequence is missing")
	elseif not sequence then
		log.debug("mactans_controller has no configuration for this game mode")
	elseif not mactans then
		log.error("enemy_mactans could not be found")
	else
		while not store.waves_finished do
			local start_ts = store.tick_ts
			local wave_number = store.wave_group_number
			local groups = sequence[wave_number]

			if not groups then
			-- block empty
			else
				for _, group in pairs(groups) do
					local t_elapsed = store.tick_ts - start_ts
					local t_total = group[1]
					local t_actual = km.clamp(0, t_total, t_total - t_elapsed)

					log.debug("mactans_controller wave_number:%s delay:%s waiting:%s type:%s", wave_number, t_total, t_actual, group[2])

					if U.y_wait_conditional(store, t_actual, function(store, time)
						return store.wave_group_number ~= wave_number or store.waves_finished
					end) then
						goto label_487_0
					end

					if group[2] == "tower_block" then
						local holder_ids = this.sequence_groups.towers[group[3]]

						if holder_ids and #holder_ids > 0 then
							mactans.phase_signal = group[2]
							mactans.phase_params = {
								holder_ids = holder_ids,
								block_duration = group[4],
								touch_duration = group[5]
							}
						else
							log.info("mactans wave:%s tower_block for group:%s has no holder_ids defined", wave_number, group[3])
						end
					elseif group[2] == "path_web" then
						local path_data = table.random(this.sequence_groups.paths[group[3]])

						mactans.phase_signal = group[2]
						mactans.phase_params = {
							path_id = path_data.path_id,
							near_pos = path_data.pos,
							web_duration = group[4],
							touch_duration = group[6],
							qty_per_egg = group[5]
						}
					end

					if store.wave_group_number ~= wave_number then
						goto label_487_0
					end
				end

				coroutine.yield()
			end

			::label_487_0::

			while store.wave_group_number == wave_number and not store.waves_finished do
				coroutine.yield()
			end
		end
	end

	simulation:queue_remove_entity(this)
end

scripts.power_thunder_control = {}

function scripts.power_thunder_control.can_select_point(this, x, y, store)
	return not GR:cell_is(x, y, TERRAIN_CLIFF) and not GR:cell_is(x, y, TERRAIN_FAERIE) and (P:valid_node_nearby(x, y, 1.4285714285714286, NF_POWER_1) or store.level.fn_can_power and store.level:fn_can_power(store, GUI_MODE_POWER_1, v(x, y)) or GR:cell_is(x, y, TERRAIN_WATER))
end

function scripts.power_thunder_control.update(this, store)
	local function create_thunder(thunder, pos)
		local e = E:create_entity("fx_power_thunder_" .. math.random(1, 2))

		e.pos.x, e.pos.y = pos.x, pos.y
		e.render.sprites[1].flip_x = math.random() < 0.5
		e.render.sprites[1].ts = store.tick_ts

		if REF_H - pos.y > e.image_h then
			e.render.sprites[1].scale = v(1, (REF_H - pos.y) / e.image_h)
		end

		simulation:queue_insert_entity(e)

		e = E:create_entity("fx_power_thunder_explosion")
		e.pos.x, e.pos.y = pos.x, pos.y
		e.render.sprites[1].ts = store.tick_ts
		e.render.sprites[2].ts = store.tick_ts

		simulation:queue_insert_entity(e)

		e = E:create_entity("fx_power_thunder_explosion_decal")
		e.pos.x, e.pos.y = pos.x, pos.y
		e.render.sprites[1].ts = store.tick_ts

		simulation:queue_insert_entity(e)

		if thunder.pop and math.random() < thunder.pop_chance then
			local e = SU.create_pop(store, this.pos, thunder.pop)

			simulation:queue_insert_entity(e)
		end

		local targets = U.find_enemies_in_range_filter_off(pos, thunder.damage_radius, this.vis_flags, this.vis_bans)

		if targets then
			for _, target in ipairs(targets) do
				local d = E.assign_damage(thunder.damage_type, math.random(thunder.damage_min, thunder.damage_max), this.id, target.id)

				queue_damage(store, d)
			end
		end
	-- AC:inc_check("LIGHTNING_CAST")
	end

	local function flash_screen(fx)
		if store.tick_ts - fx.ts > fx.cooldown then
			local duration = U.frandom(this.flash_duration_min, this.flash_duration_max)
			U.frandom(this.flash_delay_min, this.flash_delay_max)

			local a1 = math.random(this.flash_l1_max_alphas[1], this.flash_l1_max_alphas[2])
			local delta = this.flash_delta
			local t1, t2, t3 = 0, delta, delta + duration

			fx.tween.props[1].keys = {{t1, 0}, {t2, a1}, {t3, 0}}
			fx.tween.ts = store.tick_ts
			fx.ts = store.tick_ts
			fx.cooldown = duration + U.frandom(0, 0.4)
		end
	end

	local overlay = E:create_entity("overlay_power_thunder_flash")

	overlay.pos.x, overlay.pos.y = REF_W * 0.5, REF_H * 0.5
	overlay.tween.props[2].keys = {{0, 0}, {0.5, this.flash_l2_max_alpha}}
	overlay.tween.props[2].ts = store.tick_ts

	simulation:queue_insert_entity(overlay)
	flash_screen(overlay)

	local visited = {}
	local t1, t2 = this.thunders[1], this.thunders[2]

	t1.created, t2.created = 0, 0

	if t2.count > 0 then
		t2.cooldown = U.frandom(t2.delay_min, t2.delay_max)
		t2.ts = store.tick_ts
	end

	while t1.created < t1.count or t2.created < t2.count do
		for _, thunder in pairs(this.thunders) do
			if thunder.created < thunder.count and store.tick_ts - thunder.ts > thunder.cooldown then
				local pos

				if thunder.targeting == "nearest" then
					if thunder.created == 0 then
						pos = this.pos
					else
						local target = U.find_nearest_enemy(store, this.pos, 0, thunder.range, this.vis_flags, this.vis_bans, function(v)
							return not table.contains(visited, v)
						end)

						if target then
							table.insert(visited, target)

							pos = target.pos
						else
							local nearest = P:nearest_nodes(this.pos.x, this.pos.y, nil, nil, true)

							if #nearest > 0 then
								local pi, _, ni = unpack(nearest[1])
								local no = math.random(-this.nodes_spread, this.nodes_spread)

								if not P:is_node_valid(pi, ni + no) then
									no = 0
								end

								pos = P:node_pos(pi, math.random(1, 3), ni + no)
							end
						end
					end
				else
					local target = U.find_random_enemy(store, this.pos, 0, thunder.range, this.vis_flags, this.vis_bans)

					if target then
						pos = target.pos
					else
						pos = P:get_random_position(10, bor(TERRAIN_LAND, TERRAIN_WATER)) or this.pos
					end
				end

				if pos then
					create_thunder(thunder, pos)
					flash_screen(overlay)
				end

				thunder.ts = store.tick_ts
				thunder.cooldown = U.frandom(thunder.delay_min, thunder.delay_max)
				thunder.created = thunder.created + 1
			end
		end

		if not this.slow.disabled and store.tick_ts - this.slow.ts > this.slow.cooldown then
			this.slow.ts = store.tick_ts

			local targets = U.find_enemies_in_range_filter_off(this.pos, this.slow.range, this.vis_flags, this.vis_bans)

			if targets then
				for _, target in ipairs(targets) do
					local mod = E:create_entity(this.slow.mod)

					mod.modifier.target_id = target.id
					mod.modifier.source_id = this.id

					simulation:queue_insert_entity(mod)
				end
			end
		end

		if not this.rain.disabled and store.tick_ts - this.rain.ts > this.rain.cooldown then
			local r = this.rain

			r.ts = store.tick_ts

			local angle = U.frandom(r.angle_min, r.angle_max)

			for i = 1, r.count do
				angle = angle + U.frandom(-r.angle_between, r.angle_between)

				local dist = math.random(r.distance_min, r.distance_max)
				local ox, oy = V.rotate(angle, dist, 0)
				local delay = U.frandom(0.001, r.delay_max)
				local pos = v(math.random(-REF_OX, REF_W + REF_OX), math.random(0, REF_H))
				local e = E:create_entity("fx_power_thunder_drop")

				e.pos.x, e.pos.y = pos.x, pos.y
				e.render.sprites[1].offset = v(-ox, -oy)
				e.render.sprites[1].r = angle
				e.render.sprites[1].alpha = math.random(r.alpha_min, r.alpha_max)
				e.tween.props[1].keys = {{0, 0}, {0.001, 255}}
				e.tween.props[2] = E:clone_c("tween_prop")
				e.tween.props[2].keys = {{0, v(-ox, -oy)}, {0.001, v(-ox, -oy)}, {r.duration, v(0, 0)}}
				e.tween.props[2].name = "offset"
				e.tween.ts = store.tick_ts + delay

				simulation:queue_insert_entity(e)

				local e = E:create_entity("fx_power_thunder_rain_splash")

				e.pos.x, e.pos.y = pos.x, pos.y
				e.render.sprites[1].ts = store.tick_ts + delay + r.duration

				simulation:queue_insert_entity(e)
			end
		end

		coroutine.yield()
	end

	if this.extra_duration then
		local stop_ts = store.tick_ts + this.extra_duration
		overlay.tween.remove = true
		overlay.tween.props[1].keys = {{0, overlay.render.sprites[1].alpha}, {this.extra_duration, 0}}
		overlay.tween.props[2].keys = {{0, overlay.render.sprites[2].alpha}, {this.extra_duration, 0}}
		overlay.tween.ts = store.tick_ts
		overlay.tween.props[2].ts = nil
		while store.tick_ts < stop_ts do
			if not this.slow.disabled and store.tick_ts - this.slow.ts > this.slow.cooldown then
				this.slow.ts = store.tick_ts
				local factor = (stop_ts - store.tick_ts) / this.extra_duration

				local targets = U.find_enemies_in_range_filter_off(this.pos, this.slow.range, this.vis_flags, this.vis_bans)

				if targets then
					for _, target in ipairs(targets) do
						local mod = E:create_entity(this.slow.mod)

						mod.modifier.target_id = target.id
						mod.modifier.source_id = this.id
						mod.slow.factor = 1 - (1 - this.slow.factor) * factor

						simulation:queue_insert_entity(mod)
					end
				end
			end

			if not this.rain.disabled and store.tick_ts - this.rain.ts > this.rain.cooldown then
				local r = this.rain

				r.ts = store.tick_ts

				local angle = U.frandom(r.angle_min, r.angle_max)
				local factor = (stop_ts - store.tick_ts) / this.extra_duration
				for i = 1, math.ceil(r.count * factor) do
					angle = angle + U.frandom(-r.angle_between, r.angle_between)

					local dist = math.random(r.distance_min, r.distance_max)
					local ox, oy = V.rotate(angle, dist, 0)
					local delay = U.frandom(0.001, r.delay_max)
					local pos = v(math.random(-REF_OX, REF_W + REF_OX), math.random(0, REF_H))
					local e = E:create_entity("fx_power_thunder_drop")

					e.pos.x, e.pos.y = pos.x, pos.y
					e.render.sprites[1].offset = v(-ox, -oy)
					e.render.sprites[1].r = angle
					e.render.sprites[1].alpha = math.random(r.alpha_min, r.alpha_max)
					e.tween.props[1].keys = {{0, 0}, {0.001, 255}}
					e.tween.props[2] = E:clone_c("tween_prop")
					e.tween.props[2].keys = {{0, v(-ox, -oy)}, {0.001, v(-ox, -oy)}, {r.duration, v(0, 0)}}
					e.tween.props[2].name = "offset"
					e.tween.ts = store.tick_ts + delay

					simulation:queue_insert_entity(e)

					local e = E:create_entity("fx_power_thunder_rain_splash")

					e.pos.x, e.pos.y = pos.x, pos.y
					e.render.sprites[1].ts = store.tick_ts + delay + r.duration

					simulation:queue_insert_entity(e)
				end
			end

			coroutine.yield()
		end
	else
		overlay.tween.remove = true
		overlay.tween.props[1].keys = {{0, overlay.render.sprites[1].alpha}, {0.5, 0}}
		overlay.tween.props[2].keys = {{0, overlay.render.sprites[2].alpha}, {0.5, 0}}
		overlay.tween.ts = store.tick_ts
		overlay.tween.props[2].ts = nil
	end

	simulation:queue_remove_entity(this)
end

scripts.tower_ewok_holder = {}

function scripts.tower_ewok_holder.get_info()
	local tpl = E:get_template("tower_ewok")
	local o = scripts.tower_barrack.get_info(tpl)

	o.respawn = nil

	return o
end

scripts.soldier_ewok = {}

function scripts.soldier_ewok.update(this, store)
	local brk, sta

	if this.vis._bans_added then
		U.bans_remove(this.vis, F_ALL)
		this.vis._bans_added = nil
	end

	while true do
		for pn, p in pairs(this.powers) do
			if p.changed then
				p.changed = nil

				SU.soldier_power_upgrade(this, pn)
			end
		end

		if this.health.dead then
			SU.y_soldier_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			if this.dodge and this.dodge.active then
				local start_ts = store.tick_ts

				U.y_animation_play(this, this.dodge.animation_start, nil, store.tick_ts, false)

				this.dodge.last_hit_ts = nil
				this.health.immune_to = F_ALL

				U.heal(this, this.dodge.heal)

				while store.tick_ts - start_ts < this.dodge.duration and not this.health.dead and not this.unit.is_stunned do
					SU.soldier_regen(store, this)

					if this.dodge.last_hit_ts then
						U.y_animation_play(this, this.dodge.animation_hit, nil, store.tick_ts, 1)

						this.dodge.last_hit_ts = nil
					end

					coroutine.yield()
				end

				U.y_animation_play(this, this.dodge.animation_end, nil, store.tick_ts, 1)

				this.dodge.active = false
				this.health.immune_to = 0
				this.dodge.ts = store.tick_ts

				goto label_519_1
			end

			while this.nav_rally.new do
				if SU.y_soldier_new_rally(store, this) then
					goto label_519_1
				end
			end

			brk, sta = SU.y_soldier_ranged_attacks(store, this)

			if brk then
				goto label_519_1
			end

			brk, sta = SU.y_soldier_melee_block_and_attacks(store, this)

			if brk or sta ~= A_NO_TARGET then
				goto label_519_1
			end

			brk, sta = SU.y_soldier_ranged_attacks(store, this)

			if brk or sta == A_DONE then
				goto label_519_1
			elseif sta == A_IN_COOLDOWN then
				goto label_519_0
			end

			if SU.soldier_go_back_step(store, this) then
				goto label_519_1
			end

			::label_519_0::

			SU.soldier_idle(store, this)
			SU.soldier_regen(store, this)
		end

		::label_519_1::

		coroutine.yield()
	end
end

scripts.soldier_gryphon_guard = {}

function scripts.soldier_gryphon_guard.upper_ranged_filter_fn(e, origin)
	return U.is_inside_ellipse_with_aspect(e.pos, v(300, 627), 125, 0.64) or U.is_inside_ellipse_with_aspect(e.pos, v(560, 382), 95, 0.5263157894736842)
end

function scripts.soldier_gryphon_guard.lower_ranged_filter_fn(e, origin)
	return U.is_inside_ellipse_with_aspect(e.pos, v(275, 454), 175, 0.7714285714285715) or U.is_inside_ellipse_with_aspect(e.pos, v(530, 376), 150, 0.36666666666666664)
end

scripts.aura_soldier_gryphon_guard_upper = {}

function scripts.aura_soldier_gryphon_guard_upper.update(this, store)
	while true do
		local target = store.entities[this.aura.source_id]

		if not target then
			simulation:queue_remove_entity(this)

			return
		end

		local attack = target.ranged.attacks[1]
		local cooldown = U.frandom(this.patch_cooldown_min, this.patch_cooldown_max)

		attack.cooldown = cooldown

		U.y_wait_unconditional(store, cooldown + fts(1))
	end
end

scripts.aura_soldier_gryphon_guard_lower = {}

function scripts.aura_soldier_gryphon_guard_lower.update(this, store)
	local target = store.entities[this.aura.source_id]

	if not target then
		simulation:queue_remove_entity(this)

		return
	end

	local attack = target.ranged.attacks[1]
	local hidden = true
	local last_show_ts = 0

	target.pos.x, target.pos.y = this.hide_pos.x, this.hide_pos.y
	target.nav_rally.pos = this.hide_pos
	target.nav_rally.center = this.hide_pos
	target.tween.reverse = true
	target.tween.ts = -1

	while store.wave_group_number < 1 do
		coroutine.yield()
	end

	while true do
		if hidden then
			U.y_wait_unconditional(store, U.frandom(this.hidden_min, this.hidden_max))

			target.tween.reverse = false
			target.tween.ts = store.tick_ts
			target.nav_rally.pos = this.show_pos
			target.nav_rally.center = this.show_pos
			target.nav_rally.new = true

			coroutine.yield()

			while not target.motion.arrived do
				coroutine.yield()
			end

			hidden = false
			last_show_ts = store.tick_ts
			attack.disabled = nil
		elseif store.tick_ts - math.max(attack.ts, last_show_ts) > this.idle_time_to_hide then
			attack.disabled = true
			target.tween.reverse = true
			target.tween.ts = store.tick_ts
			target.nav_rally.pos = this.hide_pos
			target.nav_rally.center = this.hide_pos
			target.nav_rally.new = true

			coroutine.yield()

			while not target.motion.arrived do
				coroutine.yield()
			end

			hidden = true
		end

		coroutine.yield()
	end
end

scripts.bullet_gryphon = {}

function scripts.bullet_gryphon.update(this, store)
	local b = this.bullet
	local speed = b.max_speed

	this.render.sprites[1].ts = store.tick_ts

	while V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) >= 2 * (speed * store.tick_length) do
		coroutine.yield()

		b.speed.x, b.speed.y = V.mul(speed, V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y))
		this.pos.x, this.pos.y = this.pos.x + b.speed.x * store.tick_length, this.pos.y + b.speed.y * store.tick_length
		this.render.sprites[1].r = V.angleTo(b.to.x - this.pos.x, b.to.y - this.pos.y)
	end

	local targets = U.find_enemies_in_range_filter_off(this.pos, b.damage_radius, b.vis_flags, b.vis_bans)

	if targets then
		for _, target in ipairs(targets) do
			local d = SU.create_bullet_damage(b, target.id, this.id)

			queue_damage(store, d)
		end
	end

	this.render.sprites[1].hidden = true

	if b.hit_fx then
		local fx = E:create_entity(b.hit_fx)

		fx.pos.x, fx.pos.y = b.to.x, b.to.y
		fx.render.sprites[1].ts = store.tick_ts
		fx.render.sprites[1].runs = 0

		simulation:queue_insert_entity(fx)
	end

	if b.hit_decal then
		local decal = E:create_entity(b.hit_decal)

		decal.pos = V.vclone(b.to)
		decal.render.sprites[1].ts = store.tick_ts

		simulation:queue_insert_entity(decal)
	end

	simulation:queue_remove_entity(this)
end

scripts.faerie_dragon = {}

function scripts.faerie_dragon.update(this, store)
	local sp = this.render.sprites[1]
	local fm = this.force_motion
	local ca = this.custom_attack
	local dest = V.vclone(this.idle_pos)
	local pred_pos, dist

	local function force_move_step(dest, max_speed, ramp_radius)
		local dx, dy = V.sub(dest.x, dest.y, this.pos.x, this.pos.y)
		local dist = V.len(dx, dy)
		local df = (not ramp_radius or ramp_radius < dist) and 1 or math.max(dist / ramp_radius, 0.1)

		fm.a.x, fm.a.y = V.add(fm.a.x, fm.a.y, V.trim(495, V.mul(10 * df, dx, dy)))
		fm.v.x, fm.v.y = V.add(fm.v.x, fm.v.y, V.mul(store.tick_length, fm.a.x, fm.a.y))
		fm.v.x, fm.v.y = V.trim(max_speed, fm.v.x, fm.v.y)
		this.pos.x, this.pos.y = V.add(this.pos.x, this.pos.y, V.mul(store.tick_length, fm.v.x, fm.v.y))
		fm.a.x, fm.a.y = V.mul(-0.05 / store.tick_length, fm.v.x, fm.v.y)
		sp.flip_x = this.pos.x > dest.x
	end

	ca.ts = store.tick_ts
	sp.offset.y = this.flight_height

	-- 仙女龙有 rise，龙巢没有
	U.y_animation_play(this, "rise", nil, store.tick_ts)

	while true do
		if ca.target_id ~= nil and store.tick_ts - ca.ts > ca.cooldown then
			ca.ts = store.tick_ts

			local an, af, ai, fx
			local target = store.entities[ca.target_id]

			if not target or target.health.dead then
			-- block empty
			else
				an, af, ai = U.animation_name_facing_point(this, "fly", target.pos)

				U.animation_start_default(this, an, af, store.tick_ts, true)

				repeat
					target = store.entities[ca.target_id]

					if not target or target.health.dead then
						goto label_542_0
					end

					dist = V.dist(this.pos.x, this.pos.y, target.pos.x, target.pos.y)
					pred_pos = P:predict_enemy_pos(target, dist / this.flight_speed_busy)
					dest.x, dest.y = pred_pos.x, pred_pos.y

					force_move_step(dest, this.flight_speed_busy)
					coroutine.yield()
				until dist < 30 or ca.target_id == nil

				if not sp.sync_flag then
					coroutine.yield()
				end

				S:queue(ca.sound)

				an, af, ai = U.animation_name_facing_point(this, ca.animation, pred_pos)

				U.animation_start_default(this, an, af, store.tick_ts, false)

				fx = E:create_entity("fx_faerie_dragon_shoot")
				fx.pos.x, fx.pos.y = this.pos.x, this.pos.y
				fx.render.sprites[1].ts = store.tick_ts
				fx.render.sprites[1].flip_x = af
				fx.render.sprites[1].offset.y = sp.offset.y

				simulation:queue_insert_entity(fx)
				U.y_wait_unconditional(store, ca.shoot_time)

				do
					local so = ca.bullet_start_offset[ai]
					local b = E:create_entity(ca.bullet)

					b.pos.x, b.pos.y = this.pos.x + (af and -1 or 1) * so.x, this.pos.y + this.flight_height + so.y
					b.bullet.from = V.vclone(b.pos)
					b.bullet.to = pred_pos
					b.bullet.target_id = target.id
					b.bullet.source_id = this.id

					for i, modname in ipairs(b.bullet.mods) do
						if modname == "mod_faerie_dragon_l0" then
							b.bullet.mods[i] = "mod_faerie_dragon_l" .. this.owner.powers.improve_shot.level

							break
						end
					end

					b.bullet.damage_factor = this.owner.tower.damage_factor

					simulation:queue_insert_entity(b)
				end

				U.y_animation_wait_default(this)
			end

			::label_542_0::

			ca.target_id = nil
			dest.x, dest.y = this.idle_pos.x, this.idle_pos.y
		end

		U.animation_start_default(this, "idle", nil, store.tick_ts, true)

		if V.dist(dest.x, dest.y, this.idle_pos.x, this.idle_pos.y) > 43 or V.dist(dest.x, dest.y, this.pos.x, this.pos.y) < 10 then
			dest = U.point_on_ellipse(this.idle_pos, 30, U.frandom(0, 2 * math.pi))
		end

		force_move_step(dest, this.flight_speed_idle, this.ramp_dist_idle)
		coroutine.yield()
	end
end

scripts.decal_faerie_crystal = {}

function scripts.decal_faerie_crystal.update(this, store)
	local current_color = "yellow"

	while true do
		if this.faerie_color and this.faerie_color ~= current_color then
			current_color = this.faerie_color

			U.y_wait_unconditional(store, this.delay)

			this.tween.disabled = nil
			this.tween.ts = store.tick_ts
			this.tween.reverse = this.faerie_color ~= "red"
			this.render.sprites[3].name = this.faerie_color
			this.render.sprites[3].hidden = nil
			this.render.sprites[3].ts = store.tick_ts
		end

		coroutine.yield()
	end
end

scripts.faerie_trails = {}

function scripts.faerie_trails.insert(this, store)
	this.path_colors = {}
	this.sections = {}

	for pi = 1, #P.paths do
		this.path_colors[pi] = "none"

		local node_in
		local nodes = P.paths[pi][1]

		for ni = 1, #nodes do
			local npos = nodes[ni]

			if not node_in and GR:cell_is(npos.x, npos.y, TERRAIN_FAERIE) then
				node_in = ni
			elseif node_in and not GR:cell_is(npos.x, npos.y, TERRAIN_FAERIE) then
				table.insert(this.sections, {pi, node_in, ni})

				node_in = nil
			end
		end

		if node_in then
			table.insert(this.sections, {pi, node_in, nil})
		end
	end

	return true
end

function scripts.faerie_trails.update(this, store)
	local sections = this.sections

	local function is_inside_section(pi, ni)
		for _, s in pairs(sections) do
			if pi == s[1] and ni >= s[2] and ni < s[3] then
				return true
			end
		end

		return false
	end

	local function get_speed(pi)
		local path_speeds = this.path_speed_per_wave and this.path_speed_per_wave[pi]
		local speed_idx = path_speeds and path_speeds[store.wave_group_number] or 0
		local speed = this.path_speeds[speed_idx]

		return speed, speed_idx == 0 and "yellow" or "red"
	end

	while true do
		for pi = 1, #this.path_colors do
			local _, color = get_speed(pi)

			if this.path_colors[pi] ~= color then
				this.path_colors[pi] = color

				local crystals = table.filter(store.entities, function(_, e)
					return e.template_name == "decal_faerie_crystal" and e.path_id == pi
				end)

				for _, c in pairs(crystals) do
					c.faerie_color = color
					c.faerie_color_ts = store.tick_ts
				end
			end
		end

		local enemies = table.filter(store.enemies, function(_, e)
			return not e.health.dead and e.main_script and e.main_script.co ~= nil and e.nav_path and is_inside_section(e.nav_path.pi, e.nav_path.ni)
		end)

		for _, enemy in ipairs(enemies) do
			local speed, color = get_speed(enemy.nav_path.pi)
			local fx = E:create_entity("fx_faerie_smoke")

			fx.pos.x, fx.pos.y = enemy.pos.x, enemy.pos.y
			fx.render.sprites[1].ts = store.tick_ts
			fx.render.sprites[1].scale = enemy.unit.size == UNIT_SIZE_SMALL and V.vv(0.83) or V.vv(1)
			fx.render.sprites[1].name = color

			simulation:queue_insert_entity(fx)

			local f = E:create_entity("nav_faerie")

			f.pos.x, f.pos.y = enemy.pos.x, enemy.pos.y
			f.nav_path.pi, f.nav_path.spi, f.nav_path.ni = enemy.nav_path.pi, enemy.nav_path.spi, enemy.nav_path.ni

			U.update_max_speed(f, speed)

			f.enemy_size = enemy.unit.size
			f.enemy_offset = V.vclone(enemy.unit.mod_offset)
			f.faerie_color = color
			f.faerie_enemy = enemy

			simulation:queue_insert_entity(f)
			SU.remove_modifiers(store, enemy)
			SU.remove_auras(store, enemy)
			simulation:queue_remove_entity(enemy)
			U.unblock_all(store, enemy)

			if enemy.ui then
				enemy.ui.can_click = false
			end

			enemy.main_script.co = nil
			enemy.main_script.runs = 0

			if enemy.count_group then
				enemy.count_group.in_limbo = true
			end
		end

		local faeries = table.filter(store.entities, function(_, e)
			return e.template_name == "nav_faerie"
		end)

		for _, f in pairs(faeries) do
			local speed, color = get_speed(f.nav_path.pi)

			if is_inside_section(f.nav_path.pi, f.nav_path.ni) then
				if color ~= f.faerie_color then
					U.update_max_speed(f, speed)

					f.faerie_color = color
				end
			else
				simulation:queue_remove_entity(f)

				local enemy = f.faerie_enemy

				enemy.pos.x, enemy.pos.y = f.pos.x, f.pos.y
				enemy.nav_path.pi, enemy.nav_path.spi, enemy.nav_path.ni = f.nav_path.pi, f.nav_path.spi, f.nav_path.ni
				enemy.main_script.runs = 1

				if enemy.ui then
					enemy.ui.can_click = true
				end

				if enemy.health_bar then
					enemy.health_bar.hidden = nil
				end

				enemy.health.ignore_damage = false

				U.sprites_show(enemy)
				SU.stun_dec(enemy, true)
				simulation:queue_insert_entity(enemy)

				local fx = E:create_entity("fx_faerie_smoke")

				fx.pos.x, fx.pos.y = enemy.pos.x, enemy.pos.y
				fx.render.sprites[1].ts = store.tick_ts
				fx.render.sprites[1].scale = enemy.unit.size == UNIT_SIZE_SMALL and V.vv(0.83) or V.vv(1)
				fx.render.sprites[1].name = color

				simulation:queue_insert_entity(fx)
			end
		end

		coroutine.yield()
	end
end

scripts.nav_faerie = {}

function scripts.nav_faerie.update(this, store)
	local enemy_is_small = this.enemy_size == UNIT_SIZE_SMALL
	local next, current_color
	local pss = {}

	pss.red = E:create_entity("ps_nav_faerie_red")
	pss.yellow = E:create_entity("ps_nav_faerie_yellow")
	pss.red.particle_system.emit = false
	pss.red.particle_system.track_id = this.id
	pss.yellow.particle_system.emit = false
	pss.yellow.particle_system.track_id = this.id

	simulation:queue_insert_entity(pss.red)
	simulation:queue_insert_entity(pss.yellow)

	for _, ps in pairs(pss) do
		ps.particle_system.scale_var = enemy_is_small and {0.5, 0.5}
		ps.particle_system.track_offset = this.enemy_offset
	end

	for i = 1, 4 do
		this.render.sprites[i].offset = this.enemy_offset
		this.render.sprites[i].scale = enemy_is_small and V.vv(0.5) or V.vv(1)
	end

	for i = 1, 2 do
		for _, v in pairs(this.tween.props[i].keys) do
			v[2].x = v[2].x * (enemy_is_small and 0.5 or 1)
			v[2].y = v[2].y * (enemy_is_small and 0.5 or 1)
		end
	end

	while true do
		if this.faerie_color ~= current_color then
			current_color = this.faerie_color
			pss.red.particle_system.emit = current_color == "red"
			pss.yellow.particle_system.emit = current_color == "yellow"
			this.render.sprites[1].hidden = current_color ~= "red"
			this.render.sprites[3].hidden = current_color ~= "red"
			this.render.sprites[2].hidden = current_color ~= "yellow"
			this.render.sprites[4].hidden = current_color ~= "yellow"
		end

		next = P:next_entity_node(this, store.tick_length)

		if not next then
			log.error("(%s)nav_faerie reached goal", this.id)

			break
		end

		U.set_destination(this, next)
		U.walk_off__accel__unsnapped(this, store.tick_length)
		coroutine.yield()
	end

	simulation:queue_remove_entity(this)
end

scripts.tower_black_baby_dragon = {}

function scripts.tower_black_baby_dragon.get_info(this)
	return {
		desc = "ELVES_BABY_BERESAD_DESCRIPTION",
		type = STATS_TYPE_TEXT
	}
end

function scripts.tower_black_baby_dragon.update(this, store)
	local e = E:create_entity("decal_black_baby_dragon")

	e.pos.x, e.pos.y = this.pos.x, this.pos.y
	e.sleep_pos = V.vclone(e.pos)

	simulation:queue_insert_entity(e)

	while true do
		this.ui.can_select = not e.attack_requested

		if this.user_selection.arg and not e.attack_requested then
			this.user_selection.arg = nil

			local attack = this.attacks.list[1]

			store.player_gold = store.player_gold - attack.price
			e.attack_requested = true
		end

		coroutine.yield()
	end
end

scripts.decal_black_baby_dragon = {}

function scripts.decal_black_baby_dragon.update(this, store)
	local image_x = 128
	local shadow_ref_height = 150
	local shadow_offset = 0
	local dragon_offset = v(-75, 40)
	local dragon_sort_offset = -80
	local ps_flame_offset = v(-37, 66)
	local s = this.render.sprites[1]
	local zzz = this.render.sprites[2]
	local shadow = this.render.sprites[3]
	local hit_fire = this.render.sprites[4]

	shadow.scale = v(1, 1)

	local wakeup_ts = 0
	local wakeup_cooldown = math.random(this.wakeup_cooldown_min, this.wakeup_cooldown_max)
	local ps_flame = E:create_entity("ps_baby_black_dragon_flame")

	ps_flame.particle_system.track_id = this.id
	ps_flame.particle_system.emit = false
	ps_flame.particle_system.track_offset = V.vclone(ps_flame_offset)
	ps_flame.particle_system.sort_y_offset = -20

	simulation:queue_insert_entity(ps_flame)

	local function update_shadow()
		local dy = this.pos.y - this.sleep_pos.y
		local scale = km.clamp(0, 1, 1 - dy / shadow_ref_height)

		shadow.scale.x, shadow.scale.y = scale, scale
		shadow.offset.y = shadow_offset - dy
	end

	::label_581_0::

	while true do
		if this.attack_requested then
			shadow.hidden = true

			S:queue(this.sound_events.wakeup, {
				delay = fts(13)
			})
			U.y_animation_play(this, "wakeUp", false, store.tick_ts, 1, 1)

			s.z = Z_OBJECTS_SKY

			U.animation_start_specific(this, "fly", true, store.tick_ts, true, 1)

			local takeoff_dest = v(store.visible_coords.right + image_x * 0.5, this.pos.y + 200)
			local takeoff_duration = 2

			U.y_ease_keys(store, {this.pos, this.pos}, {"x", "y"}, {this.pos.x, this.pos.y}, {takeoff_dest.x, takeoff_dest.y}, takeoff_duration, {"quad-out", "linear"})

			s.loop_forced = true

			for _, pass in pairs(this.dragon_passes) do
				this.nav_path.pi = pass.path_id
				this.nav_path.ni = 1
				this.pos = P:node_pos(this.nav_path.pi, this.nav_path.spi, this.nav_path.ni)

				local nex = P:next_entity_node(this, store.tick_length)
				local flip = nex.x < this.pos.x
				local flip_sign = flip and -1 or 1
				local flame_i, flame_range = next(pass.ranges)
				local flame_on = false
				local flame_ni_offset = 0
				local last_decal_ni, decal_ni_dist, decal_ni_offset = 0, 8, 0

				s.offset = v(dragon_offset.x * flip_sign, dragon_offset.y)
				s.sort_y_offset = dragon_sort_offset
				this.render.sprites[1].flip_x = not flip
				ps_flame.particle_system.track_offset.x = ps_flame_offset.x * flip_sign
				ps_flame.particle_system.emit_direction = (flip and -5 or -1) * math.pi / 6
				ps_flame.particle_system.scales_x = {flip_sign, flip_sign}
				hit_fire.flip_x = flip

				while nex do
					local flame_ni = this.nav_path.ni + flame_ni_offset

					if not flame_on and flame_range and flame_ni >= flame_range[1] and flame_ni <= flame_range[2] then
						S:queue(this.sound_events.fire_loop)
						S:queue(this.sound_events.fire_start)

						ps_flame.particle_system.emit = true

						U.animation_start(this, "attack", nil, store.tick_ts, true, 1)

						flame_on = true
						last_decal_ni = this.nav_path.ni - decal_ni_dist * 0.5
					elseif flame_on and flame_range and (flame_ni < flame_range[1] or flame_ni > flame_range[2]) then
						S:stop(this.sound_events.fire_loop)
						S:queue(this.sound_events.fire_stop)

						ps_flame.particle_system.emit = false

						U.animation_start(this, "fly", nil, store.tick_ts, true, 1)

						flame_on = false

						local fx = E:create_entity("fx_baby_black_dragon_flame_hit")

						fx.pos.x, fx.pos.y = this.pos.x, this.pos.y
						fx.tween.ts = store.tick_ts

						simulation:queue_insert_entity(fx)

						hit_fire.hidden = true
						flame_i, flame_range = next(pass.ranges, flame_i)
					end

					if flame_on and decal_ni_dist < this.nav_path.ni - last_decal_ni then
						local aura = E:create_entity(this.attacks.list[1].aura)

						aura.pos = P:node_pos(this.nav_path.pi, 1, this.nav_path.ni + decal_ni_offset)
						aura.aura.duration = U.frandom(0.8, 1.2) * aura.aura.duration
						aura.render.sprites[2].flip_x = math.random() < 0.5

						simulation:queue_insert_entity(aura)

						last_decal_ni = this.nav_path.ni
						hit_fire.hidden = false
					end

					U.set_destination(this, nex)
					U.walk_off__accel__unsnapped(this, store.tick_length)

					nex = P:next_entity_node(this, store.tick_length)

					coroutine.yield()
				end
			end

			s.loop_forced = false
			s.offset = v(0, 0)
			s.sort_y_offset = 0
			shadow.hidden = false

			update_shadow()
			U.animation_start(this, "fly", true, store.tick_ts, true, 1, true)

			this.pos.x, this.pos.y = this.sleep_pos.x, REF_H

			local a_from, a_to = this.pos.y, this.sleep_pos.y
			local approach_duration = math.floor(2.5 / fts(18)) * fts(18) + fts(10)
			local start_ts = store.tick_ts
			local phase

			repeat
				phase = (store.tick_ts - start_ts) / approach_duration
				this.pos.y = U.ease_value(a_from, a_to, phase, "quad-in")

				update_shadow()
				coroutine.yield()
			until phase >= 1

			U.y_animation_play(this, "land", false, store.tick_ts, 1, 1)
			U.animation_start(this, "idle", nil, store.tick_ts, true, 1)

			shadow.hidden = true
			s.sort_y_offset = 0
			s.z = Z_OBJECTS
			this.attack_requested = nil
		elseif wakeup_cooldown < store.tick_ts - wakeup_ts then
			S:queue(this.sound_events.wakeup, {
				delay = fts(13)
			})
			U.y_animation_play(this, "sneeze", nil, store.tick_ts, 1, 1)

			wakeup_cooldown = math.random(this.wakeup_cooldown_min, this.wakeup_cooldown_max)
			wakeup_ts = store.tick_ts
		else
			zzz.hidden = false
			zzz.alpha = 255

			U.animation_start(this, "zzz", nil, store.tick_ts, false, 2)

			while not U.animation_finished(this, 2) do
				if this.attack_requested then
					this.tween.disabled = false
					this.tween.props[1].time_offset = zzz.ts - store.tick_ts

					U.y_wait_unconditional(store, this.tween.props[1].keys[2][1])

					this.tween.disabled = true

					goto label_581_0
				end

				coroutine.yield()
			end

			zzz.hidden = true
		end

		coroutine.yield()
	end
end

scripts.mod_black_baby_dragon = {}

function scripts.mod_black_baby_dragon.insert(this, store)
	if scripts.mod_dps.insert(this, store) then
		local target = store.entities[this.modifier.target_id]
		local d = E.assign_damage(this.dps.damage_type, this.insert_damage, this.id, target.id)

		queue_damage(store, d)

		return true
	else
		return false
	end
end

scripts.soldier_baby_ashbite = {}

function scripts.soldier_baby_ashbite.insert(this, store)
	this.ranged.order = U.attack_order(this.ranged.attacks)

	if this.powers then
		for pn, p in pairs(this.powers) do
			SU.soldier_power_upgrade(this, pn)
		end
	end

	U.bans_add(this.vis, F_ALL)
	this.vis._bans_added = true

	return true
end

function scripts.soldier_baby_ashbite.update(this, store)
	local brk, sta

	if this.vis._bans_added then
		U.bans_remove(this.vis, F_ALL)
		this.vis._bans_added = nil
	end

	this.render.sprites[1].z = Z_BULLETS

	U.y_animation_play(this, "hatch", nil, store.tick_ts)

	this.render.sprites[1].z = Z_OBJECTS
	this.render.sprites[1].ts = store.tick_ts

	while true do
		if this.powers then
			for pn, p in pairs(this.powers) do
				if p.changed then
					p.changed = nil

					SU.soldier_power_upgrade(this, pn)
				end
			end
		end

		if this.health.dead then
			SU.y_hero_death_and_respawn(store, this)
		end

		while this.nav_rally.new do
			if SU.y_soldier_new_rally(store, this) then
				goto label_590_0
			end
		end

		if this.ranged then
			brk, sta = SU.y_soldier_ranged_attacks(store, this)

			if brk then
				goto label_590_0
			elseif sta == A_DONE then
				SU.soldier_idle(store, this, true)
			end
		end

		if SU.soldier_go_back_step(store, this) then
		-- block empty
		else
			SU.soldier_idle(store, this)
			SU.soldier_regen(store, this)
		end

		::label_590_0::

		coroutine.yield()
	end
end

scripts.decal_emit_breath_baby_ashbite = {}

function scripts.decal_emit_breath_baby_ashbite.update(this, store)
	local soldier = store.entities[this.source_id]
	local direction = V.angleTo(this.to.x - this.pos.x, this.to.y - this.pos.y)

	this.render.sprites[1].r = direction

	local emit_ps = E:create_entity(this.emit_ps)
	local mspeed = V.dist(this.to.x, this.to.y, this.pos.x, this.pos.y) / this.flight_time

	emit_ps.particle_system.emit_direction = direction
	emit_ps.particle_system.emit_speed = {mspeed, mspeed}
	emit_ps.particle_system.flip_x = this.to.x < this.pos.x
	emit_ps.particle_system.particle_lifetime = {this.flight_time, this.flight_time}
	emit_ps.particle_system.source_lifetime = this.duration
	emit_ps.pos.x, emit_ps.pos.y = this.pos.x, this.pos.y

	simulation:queue_insert_entity(emit_ps)
	U.y_wait_conditional(store, this.duration, function()
		return soldier.health.dead or soldier.nav_rally.new
	end)

	emit_ps.particle_system.emit = false
	emit_ps.particle_system.source_lifetime = 0

	simulation:queue_remove_entity(this)
end

scripts.aura_fiery_mist_baby_ashbite = {}

function scripts.aura_fiery_mist_baby_ashbite.update(this, store)
	local a = this.aura
	local node, spi

	a.ts = store.tick_ts

	local last_cycle_ts = store.tick_ts - a.cycle_time
	local nodes = P:nearest_nodes(this.pos.x, this.pos.y, nil, nil, true)

	if #nodes < 1 then
		log.error("aura_fiery_mist_baby_ashbite: could not find node for aura")
	else
		node = {
			pi = nodes[1][1],
			spi = nodes[1][2],
			ni = nodes[1][3]
		}
		this.pos = P:node_pos(node.pi, 1, node.ni)
		spi = 1

		for i = 1, 8 do
			local ni = node.ni - 3 + i

			if P:is_node_valid(node.pi, ni) then
				local fx = E:create_entity(this.fx)

				fx.pos = P:node_pos(node.pi, spi, ni)
				fx.pos.x, fx.pos.y = fx.pos.x + math.random(-4, 4), fx.pos.y + math.random(-4, 4)

				local scale = U.frandom(0.9, 1.1)

				fx.render.sprites[1].scale = v(scale, scale)
				fx.render.sprites[1].time_offset = fts(i * 2)
				fx.duration = U.frandom(0.95, 1.05) * a.duration
				fx.tween.ts = store.tick_ts

				simulation:queue_insert_entity(fx)
			end

			spi = km.zmod(spi + 2, 3)
		end

		while true do
			if store.tick_ts - a.ts > a.duration then
				break
			end

			if store.tick_ts - last_cycle_ts > a.cycle_time then
				last_cycle_ts = store.tick_ts

				local targets = U.find_enemies_in_range_filter_off(this.pos, a.radius, a.vis_flags, a.vis_bans)

				if targets then
					for _, target in ipairs(targets) do
						local m = E:create_entity(a.mod)

						m.modifier.target_id = target.id
						m.modifier.source_id = this.id
						m.modifier.level = a.level
						m.slow.factor = m.slow.factor + m.slow.factor_inc * a.level

						simulation:queue_insert_entity(m)

						local d = E.assign_damage(a.damage_type, 0, this.id, target.id)

						local dmin, dmax = a.damage_min, a.damage_max

						if a.damage_inc then
							dmin = dmin + a.damage_inc * a.level
							dmax = dmax + a.damage_inc * a.level
						end

						d.value = math.random(dmin, dmax)

						queue_damage(store, d)
					end
				end
			end

			coroutine.yield()
		end
	end

	simulation:queue_remove_entity(this)
end

scripts.gnoll_bush_spawner = {}

function scripts.gnoll_bush_spawner.update(this, store)
	local sp = this.spawner

	while true do
		if sp.interrupt then
		-- block empty
		elseif sp.spawn_data then
			local gnoll_type = sp.spawn_data.gnollType

			sp.spawn_data = nil
			sp.count = 1

			local brk, spawns = SU.y_spawner_spawn(store, this)

			if brk then
			-- block empty
			elseif spawns and #spawns > 0 then
				spawns[1].spawner.entity = gnoll_type
				spawns[1].spawner.node_offset = this.spawn_node_offset
			end
		end

		sp.interrupt = nil
		sp.spawn_data = nil

		coroutine.yield()
	end

	simulation:queue_remove_entity(this)
end

scripts.gnoll_bush = {}

function scripts.gnoll_bush.update(this, store)
	local sp = this.spawner
	local original_pi = this.nav_path.pi
	local sit_node = math.random(unpack(this.walk_nodes_range))

	if this.spawner.entity ~= "enemy_gnoll_gnawer" then
		this.render.sprites[1].scale = v(0.8, 0.8)
	end

	while true do
		SU.y_enemy_walk_step(store, this, "walk")

		if sp.interrupt then
			sp.count = 0

			break
		elseif original_pi ~= this.nav_path.pi then
			this.spawner.pi = this.nav_path.pi
			this.spawner.ni = this.nav_path.ni

			break
		elseif sit_node <= this.nav_path.ni then
			sit_node = this.nav_path.ni + math.random(unpack(this.walk_nodes_range))

			U.y_animation_play(this, "sitDown", nil, store.tick_ts)
			U.y_wait_unconditional(store, this.walk_wait)
			U.y_animation_play(this, "standUp", nil, store.tick_ts)
		end

		coroutine.yield()
	end

	U.animation_start_default(this, "explode", nil, store.tick_ts)
	U.y_wait_unconditional(store, fts(3))

	if sp.count > 0 then
		SU.y_spawner_spawn(store, this)
	end

	S:queue("ElvesGnollTrailOut")
	U.y_animation_wait_default(this)
	simulation:queue_remove_entity(this)
end

scripts.decal_s19_drizzt_gnoll = {}

function scripts.decal_s19_drizzt_gnoll.update(this, store)
	local out_x = this.pos.x
	local in_x = this.pos.x + 60
	local walk_time = 2
	local run_time = 0.6

	this.phase = "enter"

	U.animation_start_default(this, "walk", nil, store.tick_ts, true)
	U.y_ease_key(store, this.pos, "x", out_x, in_x, walk_time)

	this.phase = "joke"

	U.animation_start_default(this, "joke", nil, store.tick_ts, true)

	if U.y_wait_conditional(store, 2, function()
		return this.set_phase == "scared"
	end) then
		this.phase = "scared"

		U.y_animation_play(this, "scared", nil, store.tick_ts)
		U.animation_start_default(this, "walk", true, store.tick_ts, true)
		U.y_ease_key(store, this.pos, "x", in_x, out_x, run_time)
	else
		this.phase = "exit"

		U.animation_start_default(this, "idle", nil, store.tick_ts, false)
		U.y_wait_unconditional(store, 1)
		U.animation_start_default(this, "walk", true, store.tick_ts, true)
		U.y_ease_key(store, this.pos, "x", in_x, out_x, walk_time)
	end

	simulation:queue_remove_entity(this)
end

scripts.mod_dwarf_beer = {}

function scripts.mod_dwarf_beer.insert(this, store)
	local target = store.entities[this.modifier.target_id]

	if not target or not target.health or target.health.dead then
		return false
	end

	if target.health.hp == target.health.hp_max then
		return false
	end

	if target and target.unit and this.render then
		for i = 1, #this.render.sprites do
			local s = this.render.sprites[i]

			s.ts = store.tick_ts

			if s.size_names then
				s.name = s.size_names[target.unit.size]
			end
		end
	end

	this.hps.ts = store.tick_ts - this.hps.heal_every
	this.modifier.ts = store.tick_ts
	target.health.damage_factor = target.health.damage_factor * this.damage_factor

	signal.emit("mod-applied", this, target)

	return true
end

function scripts.mod_dwarf_beer.remove(this, store)
	local target = store.entities[this.modifier.target_id]

	if not target or not target.health or target.health.dead then
		return true
	end

	target.health.damage_factor = target.health.damage_factor * 1.25

	return true
end

scripts.mod_dragon_reign = {
	remove = function(this, store)
		local target = store.entities[this.modifier.target_id]

		if not target then
			return true
		end

		local spread_targets = U.find_enemies_in_range_filter_on(target.pos, this.spread_radius, F_MOD, 0, function(e)
			return e.id ~= this.modifier.target_id
		end)

		if spread_targets then
			for _, t in pairs(spread_targets) do
				local m = E:create_entity(this.template_name)

				m.modifier.target_id = t.id
				m.modifier.source_id = this.modifier.source_id
				m.modifier.level = this.modifier.level
				m.modifier.damage_factor = this.modifier.damage_factor

				simulation:queue_insert_entity(m)
			end
		end

		return true
	end
}
scripts.ray5_simple = {}

function scripts.ray5_simple.update(this, store)
	local b = this.bullet
	local s = this.render.sprites[1]
	local target = store.entities[b.target_id]
	local dest = V.vclone(b.to)
	local tower = this.tower_ref

	local function update_sprite()
		if this.track_target and target and target.motion then
			local tpx, tpy = target.pos.x, target.pos.y

			if not b.ignore_hit_offset then
				tpx, tpy = tpx + target.unit.hit_offset.x, tpy + target.unit.hit_offset.y
			end

			local d = math.max(math.abs(tpx - b.to.x), math.abs(tpy - b.to.y))

			if d > b.max_track_distance then
				log.paranoid("(%s) ray_simple target (%s) out of max_track_distance", this.id, target.id)

				target = nil
			else
				dest.x, dest.y = target.pos.x, target.pos.y

				if target.unit and target.unit.hit_offset then
					dest.x, dest.y = dest.x + target.unit.hit_offset.x, dest.y + target.unit.hit_offset.y
				end
			end
		end

		local angle = V.angleTo(dest.x - this.pos.x, dest.y - this.pos.y)

		s.r = angle

		local dist_offset = 0

		if this.dist_offset then
			dist_offset = this.dist_offset
		end

		s.scale.x = (V.dist(dest.x, dest.y, this.pos.x, this.pos.y) + dist_offset) / this.image_width
	end

	if not b.ignore_hit_offset and this.track_target and target and target.motion then
		b.to.x, b.to.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
	end

	s.scale = s.scale or v(1, 1)
	s.ts = store.tick_ts

	update_sprite()

	s.hidden = true

	if b.hit_time > fts(1) then
		while store.tick_ts - s.ts < b.hit_time do
			coroutine.yield()

			if target and U.flag_has(target.vis.bans, F_RANGED) then
				target = nil
			end

			if this.track_target then
				update_sprite()
			end
		end
	end

	local mods_added = {}
	local fx
	local hit_counter = 0

	local function do_hit()
		hit_counter = hit_counter + 1

		if target and b.damage_type ~= DAMAGE_NONE then
			local d = SU.create_bullet_damage(b, target.id, this.id)

			queue_damage(store, d)
		end

		if target and (b.mod or b.mods) then
			local mods = b.mods or {b.mod}

			for _, mod_name in ipairs(mods) do
				local m = E:create_entity(mod_name)

				m.modifier.target_id = b.target_id
				m.modifier.source_id = this.id
				U.modifier_inherit_bullet(m.modifier, b)

				if m.damage_from_bullet then
					if m.dps then
						m.dps.damage_min = b.damage_min
						m.dps.damage_max = b.damage_max
					else
						m.modifier.damage_min = b.damage_min
						m.modifier.damage_max = b.damage_max
					end
				else
					local level

					if not tower then
						level = this.bullet.level
					else
						level = tower.level
						level = level or this.bullet.level
					end

					m.modifier.level = level
				end

				table.insert(mods_added, m)
				simulation:queue_insert_entity(m)
			end
		end

		if b.hit_payload then
			local hp

			if type(b.hit_payload) == "string" then
				hp = E:create_entity(b.hit_payload)
			else
				hp = b.hit_payload
			end

			if hp.aura then
				hp.aura.level = this.bullet.level
				hp.aura.source_id = this.id
				hp.aura.damage_factor = b.damage_factor

				if target then
					hp.pos.x, hp.pos.y = target.pos.x, target.pos.y
				else
					hp.pos.x, hp.pos.y = dest.x, dest.y
				end
			else
				hp.pos.x, hp.pos.y = dest.x, dest.y
			end

			simulation:queue_insert_entity(hp)
		end

		local disable_hit = false

		if this.hit_fx_only_no_target then
			disable_hit = target ~= nil and not target.health.dead
		end

		if b.hit_fx and not disable_hit then
			local is_air = target and band(target.vis.flags, F_FLYING) ~= 0

			fx = E:create_entity(b.hit_fx)

			if b.hit_fx_ignore_hit_offset and target and not is_air then
				fx.pos.x, fx.pos.y = target.pos.x, target.pos.y
			else
				fx.pos.x, fx.pos.y = dest.x, dest.y
			end

			fx.render.sprites[1].ts = store.tick_ts

			simulation:queue_insert_entity(fx)
		end
	end

	do_hit()

	if this.ray_duration then
		local last_hit_ts = store.tick_ts

		while store.tick_ts - s.ts < this.ray_duration do
			if this.track_target then
				update_sprite()
			end

			if tower and not store.entities[tower.id] then
				simulation:queue_remove_entity(this)

				if fx then
					simulation:queue_remove_entity(fx)
				end

				for key, value in pairs(mods_added) do
					simulation:queue_remove_entity(value)
				end

				break
			end

			if this.hit_over_duration and store.tick_ts - last_hit_ts > this.hit_cycle_time then
				last_hit_ts = store.tick_ts

				do_hit()
			end

			coroutine.yield()

			s.hidden = false
		end
	else
		while not U.animation_finished_default(this) do
			if tower and not store.entities[tower.id] then
				simulation:queue_remove_entity(this)

				break
			end

			coroutine.yield()
		end
	end

	simulation:queue_remove_entity(this)
end

scripts.ps_hero_mecha_smoke = {}

function scripts.ps_hero_mecha_smoke.update(this, store)
	local source_sprite = store.entities[this.particle_system.track_id].render.sprites[1]

	while true do
		if source_sprite.flip_x then
			this.particle_system.emit_offset.x = math.abs(this.particle_system.emit_offset.x)
			this.particle_system.emit_direction = this.emit_direction_sides[2]
		else
			this.particle_system.emit_offset.x = -math.abs(this.particle_system.emit_offset.x)
			this.particle_system.emit_direction = this.emit_direction_sides[1]
		end

		coroutine.yield()
	end

	return true
end

scripts.decal_soldier_shadow = {}

function scripts.decal_soldier_shadow.update(this, store)
	while true do
		if this.entity.health.dead then
			if not this.entity.health.last_damage_types == 0 then
				U.y_wait_unconditional(store, fts(this.dissapear_time))
			end

			simulation:queue_remove_entity(this)

			return
		end

		local offset_y = this.entity.render.sprites[1].offset.y
		local shadow_scale = 1 - this.shadow_shrink * offset_y / this.max_height

		this.render.sprites[1].scale = v(shadow_scale, shadow_scale)

		coroutine.yield()
	end
end

---龙魂宝壶
scripts.tower_holder_blocked_elemental_holder = {}

function scripts.tower_holder_blocked_elemental_holder.get_info(this)
	return {
		type = STATS_TYPE_TOWER,
		damage_type = DAMAGE_PHYSICAL
	}
end

function scripts.tower_holder_blocked_elemental_holder.insert(this, store)
	this.render.sprites[1].ts = store.tick_ts - math.random() * 3
	this.render.sprites[2].ts = store.tick_ts - math.random() * 3
	this.render.sprites[3].ts = store.tick_ts - math.random() * 3

	if this.should_flip then
		for _, s in pairs(this.render.sprites) do
			s.flip_x = true
		end
	end

	return true
end

function scripts.tower_holder_blocked_elemental_holder.remove(this, store)
	if this.remove_fx then
		local fx = E:create_entity(this.remove_fx)

		fx.pos = V.vclone(this.pos)
		fx.render.sprites[1].ts = store.tick_ts

		simulation:queue_insert_entity(fx)
	end

	S:queue("TerrainWukongElementalHolderUnlock")

	local shake = E:create_entity("aura_screen_shake")

	shake.aura.amplitude = 0.35
	shake.aura.duration = 0.5
	shake.aura.freq_factor = 2

	simulation:queue_insert_entity(shake)

	return true
end

scripts.tower_holder_elemental = {}

function scripts.tower_holder_elemental.remove(this, store)
	local controller = E:create_entity(this.controller_name)

	controller.pos = this.pos
	controller.target_holder_id = this.tower.holder_id
	controller.target_id = this.id

	simulation:queue_insert_entity(controller)

	if this.render.sprites[this.render.sid_dragon].name == "buy" then
		controller.buy_anim_dragon_ts = this.render.sprites[this.render.sid_dragon].ts
	end

	return true
end
--
function scripts.tower_holder_elemental.update(this, store)
	local start_anim_gradiente = false

	U.animation_start(this, "buy", nil, store.tick_ts, false, this.render.sid_gradiente, true)

	local start_anim_dragon = false

	U.animation_start(this, "buy", nil, store.tick_ts, false, this.render.sid_dragon, true)

	while true do
		if not start_anim_gradiente and U.animation_finished(this, this.render.sid_gradiente) then
			start_anim_gradiente = true

			U.animation_start(this, "idle", nil, store.tick_ts, true, this.render.sid_gradiente, true)
		end

		if not start_anim_dragon and U.animation_finished(this, this.render.sid_dragon) then
			start_anim_dragon = true

			U.animation_start(this, "idle", nil, store.tick_ts, true, this.render.sid_dragon, true)
		end

		U.sprites_show(this, this.render.sid_dragon, this.render.sid_dragon, true)
		coroutine.yield()
	end
end

scripts.controller_elemental_generic = {}

function scripts.controller_elemental_generic.remove(this, store)
	if this.target then
		if not store.elemental_holders_cd then
			store.elemental_holders_cd = {}
		end

		store.elemental_holders_cd[this.target.tower.holder_id] = this.ability_cooldown
	end

	return true
end

--- 龙魂找塔的公用辅助函数
---@param this any
---@param store any
local function controller_elemental_generic_find_tower(this, store)
	local found_tower = false

	while true do
		for _, e in pairs(store.towers) do
			if e.tower.type ~= "holder" and e.tower.holder_id == this.target_holder_id then
				found_tower = true

				if e.build_name then
					break
				else
					return e
				end
			end
		end

		if not found_tower then
			goto continue
		end

		if U.animation_finished(this, this.render.sid_dragon, 1) and this.render.sprites[this.render.sid_dragon].name == "buy" then
			U.animation_start(this, "idle", nil, store.tick_ts, true, this.render.sid_dragon, true)
		end

		::continue::

		coroutine.yield()
	end

	return nil
end

local function controller_elemental_generic_insert_buff_to_target(this)
	if this.range_factor and this.target.attacks and this.target.attacks.range then
		this.target.attacks.range = this.target.attacks.range * this.range_factor
		this.max_range = this.target.attacks.range
	end

	if this.rally_range_factor and this.target.barrack and this.target.barrack.rally_range then
		this.target.barrack.rally_range = this.target.barrack.rally_range * this.rally_range_factor
		this.max_range = this.target.barrack.rally_range
	end

	if not this.max_range then
		this.max_range = this.default_max_range
	end

	if this.damage_factor then
		SU.insert_tower_damage_factor_buff(this.target, this.damage_factor - 1)
	end
end

local function controller_elemental_generic_remove_buff_from_target(this)
	if this.range_factor and this.target.attacks and this.target.attacks.range then
		this.target.attacks.range = this.target.attacks.range / this.range_factor
	end

	if this.rally_range_factor and this.target.barrack and this.target.barrack.rally_range then
		this.target.barrack.rally_range = this.target.barrack.rally_range / this.rally_range_factor
	end

	if this.damage_factor then
		SU.remove_tower_damage_factor_buff(this.target, this.damage_factor - 1)
	end
end

scripts.controller_elemental_wood = {}

function scripts.controller_elemental_wood.update(this, store)
	local function find_target()
		return U.find_foremost_enemy_in_range_filter_off(this.pos, this.max_range * this.skill_detection_range_factor, false, this.vis_flags, this.vis_bans)
	end

	local function get_new_fx_points()
		local points = {}
		local inner_fx_radius = this.max_range * 0.4
		local middle_fx_radius = this.max_range * 0.6
		local outer_fx_radius = this.max_range * 0.8
		local roots_count = this.max_range / 6

		for i = 1, roots_count do
			local r = outer_fx_radius

			if i % 3 == 0 then
				r = middle_fx_radius
			elseif i % 2 == 0 then
				r = inner_fx_radius
			end

			local p = {}

			p.pos = U.point_on_ellipse(this.pos, r, 2 * math.pi * i / roots_count)
			p.terrain = GR:cell_type(p.pos.x, p.pos.y)

			if P:valid_node_nearby(p.pos.x, p.pos.y, 1) and not GR:cell_is(p.pos.x, p.pos.y, TERRAIN_CLIFF) and not GR:cell_is(p.pos.x, p.pos.y, TERRAIN_WATER) and band(p.terrain, bor(TERRAIN_LAND, TERRAIN_ICE)) ~= 0 then
				table.insert(points, p)
			end
		end

		return points
	end

	local function update_fx_points()
		this.fx_points = get_new_fx_points()
		this.dragon_fx_points = get_new_fx_points()
	end

	local function add_decals()
		this.fx_points = table.random_order(this.fx_points)

		for i = 1, #this.fx_points do
			local p = this.fx_points[i]
			local fx = E:create_entity(this.root_decal .. "_" .. table.random({1, 2, 3, 4}))

			fx.render.sprites[1].flip_x = math.random() < 0.5
			fx.delay = (i - 1) * 0.15 + U.frandom(0, 0.3)
			fx.pos = p.pos
			fx.duration = this.duration

			simulation:queue_insert_entity(fx)
		end

		this.dragon_fx_points = table.random_order(this.dragon_fx_points)

		local max = #this.dragon_fx_points

		if max > 5 then
			max = 5
		end

		for i = 1, max do
			local p = this.dragon_fx_points[i]
			local fx = E:create_entity(this.root_decal_dragon)

			fx.render.sprites[1].flip_x = math.random() < 0.5
			fx.delay = (i - 1) * 1.8
			fx.pos = p.pos

			simulation:queue_insert_entity(fx)
		end
	end

	U.animation_start(this, "idle", nil, store.tick_ts, true, this.render.sid_gradiente)

	if this.buy_anim_dragon_ts then
		U.animation_start(this, "buy", nil, this.buy_anim_dragon_ts, false, this.render.sid_dragon, true)
	else
		U.animation_start(this, "idle", nil, store.tick_ts, true, this.render.sid_dragon)
	end

	this.target = controller_elemental_generic_find_tower(this, store)

	if not this.target then
		simulation:queue_remove_entity(this)

		return
	end

	S:queue("TerrainWukongElementalHolderEvolve")
	U.animation_start(this, "buy_tower", nil, store.tick_ts, false, this.render.sid_gradiente)

	if this.render.sprites[this.render.sid_dragon].name ~= "buy" or U.animation_finished(this, this.render.sid_dragon, 1) then
		U.sprites_show(this, this.render.sid_dragon, this.render.sid_dragon, true)

		this.render.sprites[this.render.sid_dragon].hide_after_runs = 1

		U.animation_start(this, "buy_tower", nil, store.tick_ts, false, this.render.sid_dragon)
	end

	controller_elemental_generic_insert_buff_to_target(this)
	update_fx_points()

	this.ability_cooldown = this.first_cooldown

	if store.elemental_holders_cd and store.elemental_holders_cd[this.target.tower.holder_id] then
		this.ability_cooldown = store.elemental_holders_cd[this.target.tower.holder_id]
	end

	local show_wings_ts = store.tick_ts + fts(114)
	local hide_wings_ts, cast_ts, end_ts
	local start_ts = store.tick_ts

	while true do
		local tower = store.entities[this.target.id]

		if not tower then
			local new_tower = controller_elemental_generic_find_tower(this, store)

			if not new_tower then
				simulation:queue_remove_entity(this)

				return
			end

			controller_elemental_generic_remove_buff_from_target(this)

			this.target = new_tower
			tower = new_tower
			U.y_wait_unconditional(store, 0.1)
			controller_elemental_generic_insert_buff_to_target(this)
			update_fx_points()
		end

		if this.render.sprites[this.render.sid_dragon].name == "buy" and U.animation_finished(this, this.render.sid_dragon, 1) then
			U.sprites_show(this, this.render.sid_dragon, this.render.sid_dragon, true)

			this.render.sprites[this.render.sid_dragon].hide_after_runs = 1

			U.animation_start(this, "buy_tower", nil, store.tick_ts, false, this.render.sid_dragon)
		end

		for i = #this.update_on_path_active, 1, -1 do
			if P:is_path_active(this.update_on_path_active[i]) then
				update_fx_points()
				table.remove(this.update_on_path_active, i)
			end
		end

		if store.tick_ts - start_ts > this.ability_cooldown then
			local target, _, pred_pos = find_target()

			if not target or not pred_pos then
				start_ts = store.tick_ts - this.ability_cooldown + 0.2 - 1e-06

				goto label_2106_0
			end

			this.ability_cooldown = this.cooldown
			start_ts = store.tick_ts
			cast_ts = start_ts + fts(38)

			S:queue("TerrainWukongElementalHolderWoodActive")
			U.sprites_show(this, this.render.sid_dragon_ability, this.render.sid_dragon_ability, true)

			this.render.sprites[this.render.sid_dragon_ability].hide_after_runs = 1

			U.animation_start(this, "start_hability", nil, store.tick_ts, false, this.render.sid_dragon_ability, true)

			this.render.sprites[this.render.sid_dragon_ability].pos = V.vclone(tower.tower.default_rally_pos)
			hide_wings_ts = store.tick_ts + fts(3)
		end

		if cast_ts and cast_ts < store.tick_ts then
			end_ts = cast_ts + this.duration
			cast_ts = nil
			show_wings_ts = end_ts + fts(101)

			local controller = E:create_entity(this.controller_aura_name)

			controller.pos = this.pos
			controller.aura.radius = this.max_range

			simulation:queue_insert_entity(controller)
			add_decals()
		end

		if end_ts and end_ts < store.tick_ts then
			end_ts = nil

			U.sprites_show(this, this.render.sid_dragon, this.render.sid_dragon, true)

			this.render.sprites[this.render.sid_dragon].hide_after_runs = 1

			U.animation_start(this, "back_to_tower", nil, store.tick_ts, false, this.render.sid_dragon)
		end

		if show_wings_ts and show_wings_ts < store.tick_ts then
			show_wings_ts = nil
			this.tween.reverse = false
			this.tween.disabled = false
			this.tween.ts = store.tick_ts
		end

		if hide_wings_ts and hide_wings_ts < store.tick_ts then
			hide_wings_ts = nil
			this.tween.reverse = true
			this.tween.disabled = false
			this.tween.ts = store.tick_ts
		end

		::label_2106_0::

		coroutine.yield()
	end

	simulation:queue_remove_entity(this)
end

scripts.decal_elemental_wood_holder_root_dragon = {}

function scripts.decal_elemental_wood_holder_root_dragon.update(this, store)
	if this.delay then
		U.sprites_hide(this, nil, nil, true)
		U.y_wait_unconditional(store, this.delay)
		U.sprites_show(this, nil, nil, true)
	end

	U.y_animation_play(this, "in", nil, store.tick_ts)

	if not this.only_in then
		U.y_animation_play(this, "loop", nil, store.tick_ts, this.loop_times)
		U.y_animation_play(this, "out", nil, store.tick_ts, 1)
	end

	simulation:queue_remove_entity(this)
end

scripts.decal_elemental_wood_holder_root_dragon_kill = {}

function scripts.decal_elemental_wood_holder_root_dragon_kill.update(this, store)
	if this.delay then
		U.sprites_hide(this, nil, nil, true)
		U.y_wait_unconditional(store, this.delay)
		U.sprites_show(this, nil, nil, true)
	end

	U.y_animation_play(this, "in", nil, store.tick_ts)
	simulation:queue_remove_entity(this)
end

scripts.controller_elemental_fire = {}

function scripts.controller_elemental_fire.update(this, store)
	local underground_pos, last_underground_pos
	local last_movement_ts = store.tick_ts
	local instakill_target

	local function find_target_strongest()
		return U.find_biggest_enemy_in_range_filter_off(this.pos, this.max_range, this.vis_flags, this.vis_bans)
	end

	local function get_new_fx_points()
		local points = {}
		local inner_fx_radius = this.max_range * 0.4
		local middle_fx_radius = this.max_range * 0.6
		local outer_fx_radius = this.max_range * 0.8
		local roots_count = this.max_range / 6

		for i = 1, roots_count do
			local r = outer_fx_radius

			if i % 3 == 0 then
				r = middle_fx_radius
			elseif i % 2 == 0 then
				r = inner_fx_radius
			end

			local p = {}

			p.pos = U.point_on_ellipse(this.pos, r, 2 * math.pi * i / roots_count)
			p.terrain = GR:cell_type(p.pos.x, p.pos.y)

			if P:valid_node_nearby(p.pos.x, p.pos.y, 1) and not GR:cell_is(p.pos.x, p.pos.y, TERRAIN_CLIFF) and not GR:cell_is(p.pos.x, p.pos.y, TERRAIN_WATER) and band(p.terrain, bor(TERRAIN_LAND, TERRAIN_ICE)) ~= 0 then
				table.insert(points, p)
			end
		end

		return points
	end

	local function update_fx_points()
		this.dragon_fx_points = get_new_fx_points()
	end

	local function spawn_dragon_underground_fx(kill, loops)
		local fx = E:create_entity(kill and this.root_decal_dragon_kill or this.root_decal_dragon)

		if not last_underground_pos then
			fx.render.sprites[1].flip_x = math.random() < 0.5
		else
			fx.render.sprites[1].flip_x = last_underground_pos.x > underground_pos.x
		end

		fx.loop_times = loops and loops or 1
		fx.delay = 0
		fx.pos = V.vclone(underground_pos)

		simulation:queue_insert_entity(fx)
	end

	local function set_underground_pos(new_pos)
		if not new_pos then
			last_underground_pos = nil
			underground_pos = nil
		else
			last_underground_pos = V.vclone(underground_pos)
			underground_pos = V.vclone(new_pos)
		end
	end

	local function move_underground()
		if not underground_pos then
			return false
		end

		local underground_chase_distance = 40
		local underground_chase_distance_kill = underground_chase_distance * 2
		local underground_chase_interval = fts(8)
		local underground_passive_interval = 4

		instakill_target = find_target_strongest()

		local time_since_last_movement = store.tick_ts - last_movement_ts

		if instakill_target then
			if underground_chase_interval < time_since_last_movement then
				local distance = V.dist(underground_pos.x, underground_pos.y, instakill_target.pos.x, instakill_target.pos.y)

				if distance < underground_chase_distance_kill then
					local tpos = V.vclone(instakill_target.pos)

					U.y_wait_unconditional(store, fts(10))
					set_underground_pos(tpos)
					spawn_dragon_underground_fx(true)

					return true
				end

				local normalized_x, normalized_y = V.normalize(instakill_target.pos.x - underground_pos.x, instakill_target.pos.y - underground_pos.y)

				set_underground_pos(V.v(underground_pos.x + normalized_x * underground_chase_distance, underground_pos.y + normalized_y * underground_chase_distance))

				last_movement_ts = store.tick_ts

				spawn_dragon_underground_fx(nil, 5)
			end
		elseif underground_passive_interval < time_since_last_movement then
			local p = table.random(this.dragon_fx_points)

			last_movement_ts = store.tick_ts

			set_underground_pos(p.pos)
			spawn_dragon_underground_fx(nil, 5)
		end

		return false
	end

	U.animation_start(this, "idle", nil, store.tick_ts, true, this.render.sid_gradiente)

	if this.buy_anim_dragon_ts then
		U.animation_start(this, "buy", nil, this.buy_anim_dragon_ts, false, this.render.sid_dragon, true)
	else
		U.animation_start(this, "idle", nil, store.tick_ts, true, this.render.sid_dragon)
	end

	this.target = controller_elemental_generic_find_tower(this, store)

	if not this.target then
		simulation:queue_remove_entity(this)

		return
	end

	S:queue("TerrainWukongElementalHolderEvolve")
	U.animation_start(this, "buy_tower", nil, store.tick_ts, false, this.render.sid_gradiente)

	if this.render.sprites[this.render.sid_dragon].name ~= "buy" or U.animation_finished(this, this.render.sid_dragon, 1) then
		U.sprites_show(this, this.render.sid_dragon, this.render.sid_dragon, true)

		this.render.sprites[this.render.sid_dragon].hide_after_runs = 1

		U.animation_start(this, "buy_tower", nil, store.tick_ts, false, this.render.sid_dragon)
	end

	controller_elemental_generic_insert_buff_to_target(this)
	update_fx_points()

	this.ability_cooldown = this.first_cooldown

	if store.elemental_holders_cd and store.elemental_holders_cd[this.target.tower.holder_id] then
		this.ability_cooldown = store.elemental_holders_cd[this.target.tower.holder_id]
	end

	local show_wings_ts = store.tick_ts + fts(104)
	local hide_wings_ts
	local start_ts = store.tick_ts

	if this.ability_cooldown < 1.5 then
		this.ability_cooldown = 1.5
	end

	while true do
		local tower = store.entities[this.target.id]

		if not tower then
			local new_tower = controller_elemental_generic_find_tower(this, store)

			if not new_tower then
				simulation:queue_remove_entity(this)

				return
			end

			controller_elemental_generic_remove_buff_from_target(this)

			this.target = new_tower
			tower = new_tower
			U.y_wait_unconditional(store, 0.1)
			controller_elemental_generic_insert_buff_to_target(this)
			update_fx_points()
		end

		if this.render.sprites[this.render.sid_dragon].name == "buy" and U.animation_finished(this, this.render.sid_dragon, 1) then
			U.sprites_show(this, this.render.sid_dragon, this.render.sid_dragon, true)

			this.render.sprites[this.render.sid_dragon].hide_after_runs = 1

			U.animation_start(this, "buy_tower", nil, store.tick_ts, false, this.render.sid_dragon)
		end

		if this.update_on_path_active then
			for i = #this.update_on_path_active, 1, -1 do
				if P:is_path_active(this.update_on_path_active[i]) then
					update_fx_points()
					table.remove(this.update_on_path_active, i)
				end
			end
		end

		if move_underground() then
			start_ts = store.tick_ts

			S:queue("TerrainWukongElementalHolderFireActiveKill")

			local d = E.assign_damage(this.damage_type, 1, this.id, instakill_target.id)

			queue_damage(store, d)

			instakill_target = nil

			set_underground_pos(nil)

			this.ability_cooldown = this.cooldown

			U.y_wait_unconditional(store, fts(30))
			U.sprites_show(this, this.render.sid_dragon, this.render.sid_dragon, true)

			this.render.sprites[this.render.sid_dragon].hide_after_runs = 1

			U.animation_start(this, "back_to_tower", nil, store.tick_ts, false, this.render.sid_dragon)

			show_wings_ts = store.tick_ts + fts(101)

			goto label_2112_0
		end

		if show_wings_ts and show_wings_ts < store.tick_ts then
			show_wings_ts = nil
			this.tween.reverse = false
			this.tween.disabled = false
			this.tween.ts = store.tick_ts
		end

		if hide_wings_ts and hide_wings_ts < store.tick_ts then
			hide_wings_ts = nil
			this.tween.reverse = true
			this.tween.disabled = false
			this.tween.ts = store.tick_ts
		end

		if not underground_pos and store.tick_ts - start_ts > this.ability_cooldown then
			instakill_target = find_target_strongest()

			if instakill_target then
				U.sprites_show(this, this.render.sid_dragon_ability, this.render.sid_dragon_ability, true)

				this.render.sprites[this.render.sid_dragon_ability].hide_after_runs = 1

				U.animation_start(this, "start_hability", nil, store.tick_ts, false, this.render.sid_dragon_ability, true)
				S:queue("TerrainWukongElementalHolderFireActiveIn")

				this.render.sprites[this.render.sid_dragon_ability].pos = V.vclone(tower.tower.default_rally_pos)
				hide_wings_ts = store.tick_ts + fts(3)
				last_movement_ts = store.tick_ts + 1.5
				underground_pos = V.vclone(this.target.tower.default_rally_pos)
			end
		end

		::label_2112_0::

		coroutine.yield()
	end

	simulation:queue_remove_entity(this)
end

scripts.controller_elemental_water = {}

function scripts.controller_elemental_water.update(this, store)
	local aura_controller, underground_pos, last_underground_pos
	local last_movement_ts = store.tick_ts
	local next_tp_ts = store.tick_ts
	local tp_target
	local affected_target_ids = {}

	local function find_target_for_tp(tower)
		return U.find_foremost_enemy_in_range_filter_on(tpos(tower), this.max_range, 0, this.vis_flags, this.vis_bans, function(e)
			return e.health and not e.health.dead and not table.contains(affected_target_ids, e.id)
		end)
	end

	local function spawn_dragon_underground_fx(kill, loops)
		local fx = E:create_entity(kill and this.root_decal_dragon_kill or this.root_decal_dragon)

		if not last_underground_pos then
			fx.render.sprites[1].flip_x = math.random() < 0.5
		else
			fx.render.sprites[1].flip_x = last_underground_pos.x > underground_pos.x
		end

		fx.loop_times = loops and loops or 1
		fx.delay = 0
		fx.pos = V.vclone(underground_pos)

		simulation:queue_insert_entity(fx)
	end

	local function set_underground_pos(new_pos)
		if not new_pos then
			last_underground_pos = nil
			underground_pos = nil
		else
			last_underground_pos = V.vclone(underground_pos)
			underground_pos = V.vclone(new_pos)
		end
	end

	local function move_underground(tower)
		if not underground_pos then
			return false
		end

		local underground_chase_distance = this.chase_speed
		local underground_chase_distance_kill = underground_chase_distance * 2
		local underground_chase_interval = fts(8)
		local underground_passive_interval = this.wander_interval

		tp_target = next_tp_ts < store.tick_ts and find_target_for_tp(tower) or nil

		local time_since_last_movement = store.tick_ts - last_movement_ts

		if tp_target then
			if underground_chase_interval < time_since_last_movement then
				local distance = V.dist(underground_pos.x, underground_pos.y, tp_target.pos.x, tp_target.pos.y)

				if distance < underground_chase_distance_kill then
					local tpos = V.vclone(tp_target.pos)

					U.y_wait_unconditional(store, fts(10))
					set_underground_pos(tpos)
					spawn_dragon_underground_fx(true)

					return true
				end

				local normalized_x, normalized_y = V.normalize(tp_target.pos.x - underground_pos.x, tp_target.pos.y - underground_pos.y)

				set_underground_pos(V.v(underground_pos.x + normalized_x * underground_chase_distance, underground_pos.y + normalized_y * underground_chase_distance))

				last_movement_ts = store.tick_ts

				spawn_dragon_underground_fx(nil, 5)
			end
		elseif underground_passive_interval < time_since_last_movement then
			local p = table.random(this.fx_points)

			last_movement_ts = store.tick_ts

			set_underground_pos(p.pos)
			spawn_dragon_underground_fx(nil, 5)
		end

		return false
	end

	local function get_rally_pos(t)
		if t.barrack and t.barrack.rally_pos then
			return V.vclone(t.barrack.rally_pos)
		end

		return V.vclone(t.tower.default_rally_pos)
	end

	local function get_new_fx_points()
		local points = {}
		local inner_fx_radius = this.max_range * 0.4
		local middle_fx_radius = this.max_range * 0.6
		local outer_fx_radius = this.max_range * 0.8
		local roots_count = this.max_range / 6

		for i = 1, roots_count do
			local r = outer_fx_radius

			if i % 3 == 0 then
				r = middle_fx_radius
			elseif i % 2 == 0 then
				r = inner_fx_radius
			end

			local p = {}

			p.pos = U.point_on_ellipse(this.pos, r, 2 * math.pi * i / roots_count)
			p.terrain = GR:cell_type(p.pos.x, p.pos.y)

			if P:valid_node_nearby(p.pos.x, p.pos.y, 1) and not GR:cell_is(p.pos.x, p.pos.y, TERRAIN_CLIFF) and not GR:cell_is(p.pos.x, p.pos.y, TERRAIN_WATER) and band(p.terrain, bor(TERRAIN_LAND, TERRAIN_ICE)) ~= 0 then
				table.insert(points, p)
			end
		end

		return points
	end

	local function update_fx_points()
		this.fx_points = get_new_fx_points()
		aura_controller.fx_points = get_new_fx_points()
	end

	this.mist_decals = {}

	local function remove_mist()
		for _, mist in pairs(this.mist_decals) do
			mist.tween.reverse = true
			mist.tween.ts = store.tick_ts
			mist.tween.remove = true
		end
	end

	local function add_mist()
		this.fx_points = table.random_order(this.fx_points)

		for i = 1, #this.fx_points do
			local p = this.fx_points[i]
			local mist = E:create_entity(this.decal_mist)

			mist.render.sprites[1].ts = store.tick_ts - 2 * math.random()
			mist.render.sprites[1].flip_x = math.random() < 0.5
			mist.pos = p.pos
			mist.tween.ts = store.tick_ts

			simulation:queue_insert_entity(mist)
			table.insert(this.mist_decals, mist)
		end
	end

	U.animation_start(this, "idle", nil, store.tick_ts, true, this.render.sid_gradiente)

	if this.buy_anim_dragon_ts then
		U.animation_start(this, "buy", nil, this.buy_anim_dragon_ts, false, this.render.sid_dragon, true)
	else
		U.animation_start(this, "idle", nil, store.tick_ts, true, this.render.sid_dragon)
	end

	this.target = controller_elemental_generic_find_tower(this, store)

	if not this.target then
		simulation:queue_remove_entity(this)

		return
	end

	S:queue("TerrainWukongElementalHolderEvolve")
	U.animation_start(this, "buy_tower", nil, store.tick_ts, false, this.render.sid_gradiente)

	if this.render.sprites[this.render.sid_dragon].name ~= "buy" or U.animation_finished(this, this.render.sid_dragon, 1) then
		U.sprites_show(this, this.render.sid_dragon, this.render.sid_dragon, true)

		this.render.sprites[this.render.sid_dragon].hide_after_runs = 1

		U.animation_start(this, "buy_tower", nil, store.tick_ts, false, this.render.sid_dragon)
	end

	controller_elemental_generic_insert_buff_to_target(this)

	this.ability_cooldown = this.first_cooldown

	if store.elemental_holders_cd and store.elemental_holders_cd[this.target.tower.holder_id] then
		this.ability_cooldown = store.elemental_holders_cd[this.target.tower.holder_id]
	end

	if this.ability_cooldown < 1.5 then
		this.ability_cooldown = 1.5
	end

	aura_controller = E:create_entity(this.controller_aura_healing)
	aura_controller.pos = this.pos
	aura_controller.aura.radius = this.max_range
	update_fx_points()

	simulation:queue_insert_entity(aura_controller)
	add_mist()

	local show_wings_ts = store.tick_ts + fts(120)
	local hide_wings_ts
	local show_cooldown_ts = show_wings_ts + 1
	local end_ts
	local start_ts = store.tick_ts
	local did_cooldown_fx_ts

	while true do
		local tower = store.entities[this.target.id]

		if not tower then
			local new_tower = controller_elemental_generic_find_tower(this, store)

			if not new_tower then
				remove_mist()
				simulation:queue_remove_entity(aura_controller)
				simulation:queue_remove_entity(this)

				return
			end

			controller_elemental_generic_remove_buff_from_target(this)
			this.target = new_tower
			tower = new_tower
			U.y_wait_unconditional(store, 0.1)
			controller_elemental_generic_insert_buff_to_target(this)
			aura_controller.aura.radius = this.max_range

			update_fx_points()
			remove_mist()
			add_mist()
		end

		if this.render.sprites[this.render.sid_dragon].name == "buy" and U.animation_finished(this, this.render.sid_dragon, 1) then
			U.sprites_show(this, this.render.sid_dragon, this.render.sid_dragon, true)

			this.render.sprites[this.render.sid_dragon].hide_after_runs = 1

			U.animation_start(this, "buy_tower", nil, store.tick_ts, false, this.render.sid_dragon)
		end

		if this.target.change_range then
			this.max_range = this.target.attacks.range
			this.target.change_range = false
			aura_controller.aura.radius = this.max_range
		end

		if this.update_on_path_active then
			for i = #this.update_on_path_active, 1, -1 do
				if P:is_path_active(this.update_on_path_active[i]) then
					update_fx_points()
					table.remove(this.update_on_path_active, i)
				end
			end
		end

		if not did_cooldown_fx_ts and tower and store.tick_ts - start_ts > this.ability_cooldown - 3 and show_cooldown_ts and show_cooldown_ts < store.tick_ts then
			show_cooldown_ts = nil
			did_cooldown_fx_ts = store.tick_ts

			U.y_wait_unconditional(store, fts(6))

			this.tween.props[this.tween.sid_hide_hojas].disabled = false
			this.tween.props[this.tween.sid_hide_hojas].ts = store.tick_ts
			this.tween.props[this.tween.sid_show_hojas].disabled = true
		end

		if move_underground(tower) then
			start_ts = store.tick_ts

			local enemies = U.find_enemies_in_range_filter_on(tp_target.pos, this.teleport_affect_radius, this.vis_flags, this.vis_bans, function(e)
				return e.health and not e.health.dead and not table.contains(affected_target_ids, e.id)
			end)

			enemies = table.random_order(enemies or {})

			for i, e in ipairs(enemies or {}) do
				if i > this.tp_max_targets then
					break
				end

				local mod_teleport = E:create_entity(this.mod_teleport)

				mod_teleport.modifier.target_id = e.id
				mod_teleport.modifier.source_id = this.id
				mod_teleport.nodes_offset = math.random(-this.tp_distance_nodes_max, -this.tp_distance_nodes_min)

				simulation:queue_insert_entity(mod_teleport)
				table.insert(affected_target_ids, e.id)
			end

			tp_target = nil
			next_tp_ts = store.tick_ts + this.delay_between_tps

			if end_ts and end_ts < store.tick_ts then
				end_ts = nil

				set_underground_pos(nil)

				this.ability_cooldown = this.cooldown

				U.y_wait_unconditional(store, fts(30))
				U.sprites_show(this, this.render.sid_dragon, this.render.sid_dragon, true)

				this.render.sprites[this.render.sid_dragon].hide_after_runs = 1

				U.animation_start(this, "back_to_tower", nil, store.tick_ts, false, this.render.sid_dragon)

				show_wings_ts = store.tick_ts + fts(36)
			end

			goto label_2120_0
		end

		if did_cooldown_fx_ts and did_cooldown_fx_ts + 0.5 < store.tick_ts and tower and not underground_pos and store.tick_ts - start_ts > this.ability_cooldown then
			tp_target = find_target_for_tp(tower)

			if tp_target then
				U.sprites_show(this, this.render.sid_dragon_ability, this.render.sid_dragon_ability, true)

				this.render.sprites[this.render.sid_dragon_ability].hide_after_runs = 1

				U.animation_start(this, "start_hability", nil, store.tick_ts, false, this.render.sid_dragon_ability, true)
				S:queue("TerrainWukongElementalHolderFireActiveIn")

				this.render.sprites[this.render.sid_dragon_ability].pos = V.vclone(tower.tower.default_rally_pos)
				hide_wings_ts = store.tick_ts + fts(3)
				last_movement_ts = store.tick_ts + 1.5
				underground_pos = V.vclone(this.target.tower.default_rally_pos)
				affected_target_ids = {}
				end_ts = store.tick_ts + this.duration
			end
		elseif end_ts and end_ts < store.tick_ts and not tp_target then
			end_ts = nil
			tp_target = nil

			set_underground_pos(nil)

			this.ability_cooldown = this.cooldown

			U.y_wait_unconditional(store, fts(30))
			U.sprites_show(this, this.render.sid_dragon, this.render.sid_dragon, true)

			this.render.sprites[this.render.sid_dragon].hide_after_runs = 1

			U.animation_start(this, "back_to_tower", nil, store.tick_ts, false, this.render.sid_dragon)

			show_wings_ts = store.tick_ts + fts(106)
		elseif show_wings_ts and show_wings_ts < store.tick_ts then
			show_cooldown_ts = store.tick_ts + 1
			show_wings_ts = nil
			this.tween.reverse = false
			this.tween.props[this.tween.sid_wings].disabled = false
			this.tween.props[this.tween.sid_wings].ts = store.tick_ts
		elseif hide_wings_ts and hide_wings_ts < store.tick_ts then
			hide_wings_ts = nil
			this.tween.reverse = true
			this.tween.props[this.tween.sid_wings].disabled = false
			this.tween.props[this.tween.sid_wings].ts = store.tick_ts
		end

		::label_2120_0::

		coroutine.yield()
	end

	simulation:queue_remove_entity(aura_controller)
	simulation:queue_remove_entity(this)
end

scripts.aura_elemental_water_healing = {}

function scripts.aura_elemental_water_healing.update(this, store)
	local last_hit_ts = 0
	local victims_count = 0

	last_hit_ts = store.tick_ts - this.aura.cycle_time

	local mods = this.aura.mods or {this.aura.mod}

	while true do
		if this.interrupt then
			last_hit_ts = 1e+99
		end

		if not (store.tick_ts - last_hit_ts >= this.aura.cycle_time) then
		-- block empty
		else
			last_hit_ts = store.tick_ts

			local targets = table.filter(store.soldiers, function(k, v)
				return not v.health.dead and v.health.hp / v.health.hp_max < this.min_health_factor and band(v.vis.flags, this.aura.vis_bans) == 0 and band(v.vis.bans, this.aura.vis_flags) == 0 and U.is_inside_ellipse(v.pos, this.pos, this.aura.radius)
			end)
			local old_victims_count = victims_count

			for i, target in ipairs(targets) do
				for _, mod_name in ipairs(mods) do
					local new_mod = E:create_entity(mod_name)

					new_mod.modifier.level = this.aura.level
					new_mod.modifier.target_id = target.id
					new_mod.modifier.source_id = this.id

					simulation:queue_insert_entity(new_mod)
				end
				victims_count = victims_count + 1
			end

			if old_victims_count < victims_count then
				local heal_fx_times = math.max(math.floor(#this.fx_points / 10), 1)

				for i = 1, heal_fx_times do
					local fx = E:create_entity(this.heal_fx)

					fx.pos = table.random(this.fx_points).pos
					fx.render.sprites[1].ts = store.tick_ts

					simulation:queue_insert_entity(fx)
				end
			end
		end

		::label_2133_0::

		coroutine.yield()
	end

	signal.emit("aura-apply-mod-victims", this, victims_count)
	simulation:queue_remove_entity(this)
end

scripts.controller_elemental_earth = {}

function scripts.controller_elemental_earth.update(this, store)
	this.spawns_ref = {}

	local function find_target()
		return U.find_foremost_enemy_in_range_filter_off(this.pos, this.max_range, false, this.vis_flags, this.vis_bans)
