	::label_271_0::

	while true do
		if this.health.dead then
			this.trail.particle_system.emit = false

			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			this.trail.particle_system.emit = true

			local cont, blocker = SU.y_enemy_walk_until_blocked(store, this, nil, adjust_trail_offset)

			if not cont then
			-- block empty
			else
				if blocker then
					this.trail.particle_system.emit = false

					if not SU.y_wait_for_blocker(store, this, blocker) then
						goto label_271_0
					end

					while SU.can_melee_blocker(store, this, blocker) do
						if not SU.y_enemy_melee_attacks(store, this, blocker) then
							goto label_271_0
						end

						coroutine.yield()
					end
				end

				coroutine.yield()
			end
		end
	end
end

function scripts.enemy_scrap_speedster.remove(this, store)
	if this.trail then
		simulation:queue_remove_entity(this.trail)
	end

	return true
end

scripts.decal_scrap = {}

function scripts.decal_scrap.update(this, store)
