scripts.enemy_darksteel_guardian = {}

function scripts.enemy_darksteel_guardian.update(this, store)
	local is_enraged = false
	local rock

	for k, v in pairs(store.entities) do
		if v.template_name == "decal_stage_23_rock" then
			rock = v

			break
		end
