	this.render.sprites[1].name = this.render.sprites[1].name .. "_000" .. table.random({"1", "2"})
	this.render.sprites[1].scale = V.vv(0.85 + math.random() * 0.15)
	this.render.sprites[1].flip_x = table.random({true, false})

	this._auras = {}

