			taps_count = taps_count + 1

			if taps_count == this.taps_to_explode then
				S:queue(this.sound)
				U.y_animation_play(this, "death", nil, store.tick_ts, 1)

				break
			else
				U.animation_start(this, "tap", nil, store.tick_ts, false)
			end
		end

		if eat_cd < store.tick_ts - eat_ts then
			eat_ts = store.tick_ts

			U.animation_start(this, "eat", nil, store.tick_ts, false)
		end

		if this.render.sprites[1].name == "tap" and U.animation_finished(this) then
			U.animation_start(this, "idle", nil, store.tick_ts, false)
		end

		if this.render.sprites[1].name == "eat" and U.animation_finished(this) then
			U.animation_start(this, "idle", nil, store.tick_ts, true)
		end

		coroutine.yield()
	end

	simulation:queue_remove_entity(this)
end

function scripts.decal_terrain_1_sheep.update_editor(this, store)
	while true do
		this.render.sprites[1].flip_x = this.editor.flip > 0

		coroutine.yield()
	end

	return true
end

-- kr6 关卡 201：老国王投掷物脚本
scripts.bomb_kr6 = {}

function scripts.bomb_kr6.insert(this, store, script)
	local b = this.bullet

	b.speed = SU.initial_parabola_speed(b.from, b.to, b.flight_time, b.g)
	b.ts = store.tick_ts
	b.last_pos = V.vclone(b.from)

	if b.rotation_speed then
		if b.starting_rotation then
			this.render.sprites[1].r = b.starting_rotation
		else
			this.render.sprites[1].r = (math.random() - 0.5) * math.pi
		end

		b.rotation_speed = b.rotation_speed * (b.to.x > b.from.x and -1 or 1)
	end

	if b.hide_radius then
		this.render.sprites[1].hidden = true
	end

	if this.tween then
		for i = 1, #this.tween.props do
			this.tween.props[i].ts = store.tick_ts
		end
	end

	return true
end

function scripts.bomb_kr6.update(this, store, script)
	local b = this.bullet
	local dmin, dmax = b.damage_min, b.damage_max
	local dradius = b.damage_radius

	if b.level and b.level > 0 then
		if b.damage_radius_inc then
			dradius = dradius + b.level * b.damage_radius_inc
		end

		if b.damage_min_inc then
			dmin = dmin + b.level * b.damage_min_inc
		end

		if b.damage_max_inc then
			dmax = dmax + b.level * b.damage_max_inc
		end
	end

	if b.damages_min and b.damages_max and b.level then
		dmin = b.damages_min[b.level]
		dmax = b.damages_max[b.level]
	end

	local ps

	if b.particles_name then
		ps = E:create_entity(b.particles_name)
		ps.particle_system.track_id = this.id

		simulation:queue_insert_entity(ps)
	end

	local shadow, shadow_start_pos

	if this.decal_shadow then
		shadow = E:create_entity(this.decal_shadow)
		shadow.pos = V.vclone(b.from)
		shadow.pos.y = b.from.y - 70

		simulation:queue_insert_entity(shadow)

		shadow_start_pos = V.vclone(shadow.pos)
	end

	while store.tick_ts - b.ts + store.tick_length < b.flight_time do
		coroutine.yield()

		b.last_pos.x, b.last_pos.y = this.pos.x, this.pos.y
		this.pos.x, this.pos.y = SU.position_in_parabola(store.tick_ts - b.ts, b.from, b.speed, b.g)

		if b.align_with_trajectory then
			this.render.sprites[1].r = V.angleTo(this.pos.x - b.last_pos.x, this.pos.y - b.last_pos.y)
		elseif b.rotation_speed then
			this.render.sprites[1].r = this.render.sprites[1].r + b.rotation_speed * store.tick_length
		end

		if b.hide_radius then
			this.render.sprites[1].hidden = V.dist(this.pos.x, this.pos.y, b.from.x, b.from.y) < b.hide_radius or V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) < b.hide_radius
		end

		if b.anim_rising or b.anim_falling then
			if this.pos.y - b.last_pos.y >= 0 then
				if b.anim_rising and this.render.sprites[1].name ~= b.anim_rising then
					U.animation_start(this, b.anim_rising, nil, store.tick_ts, b.anim_rising_loops, 1)
				end
			elseif b.anim_falling and this.render.sprites[1].name ~= b.anim_falling then
				U.animation_start(this, b.anim_falling, nil, store.tick_ts, b.anim_falling_loops, 1)
			end
		end

		if b.switch_z_time and this.render.sprites[1].z ~= Z_BULLETS and store.tick_ts - b.ts > b.switch_z_time then
			this.render.sprites[1].z = Z_BULLETS
		end

		if shadow then
			shadow.pos.x = shadow_start_pos.x + (b.to.x - shadow_start_pos.x) * ((store.tick_ts - b.ts) / b.flight_time)
			shadow.pos.y = shadow_start_pos.y + (b.to.y - shadow_start_pos.y) * ((store.tick_ts - b.ts) / b.flight_time)

			local height = this.pos.y - shadow.pos.y
			local s = km.clamp(0.6, 1, 40 / height)

			shadow.render.sprites[1].scale = V.vv(s)
		end
	end

	local enemies = U.find_enemies_in_range(store.entities, b.to, 0, dradius, b.damage_flags, b.damage_bans)

	if enemies and dmax and dmax > 0 then
		local upg = UP:get_upgrade("engineer_efficiency")
		local source = store.entities[b.source_id]
		local upg_valid = upg and source and source.tower
		local ignore_dist_factor = upg_valid or this.bullet.chance_ignore_dist_factor and math.random() <= this.bullet.chance_ignore_dist_factor

		for _, enemy in pairs(enemies) do
			local d = E:create_entity("damage")

			d.damage_type = b.damage_type
			d.reduce_armor = b.reduce_armor
			d.reduce_magic_armor = b.reduce_magic_armor

			if b.damage_decay_random then
				d.value = U.frandom(dmin, dmax)
			elseif ignore_dist_factor then
				d.value = dmax
			else
				local dist_factor = U.dist_factor_inside_ellipse(enemy.pos, b.to, dradius)

				d.value = math.floor(dmax - (dmax - dmin) * dist_factor)
			end

			if (d.damage_type == DAMAGE_EXPLOSION or d.damage_type == DAMAGE_ELECTRICAL) and this.bullet.explosive_factor then
				d.explosive_factor = this.bullet.explosive_factor
			end

			d.value = math.ceil(b.damage_factor * d.value)
			d.source_id = this.id
			d.target_id = enemy.id

			if b.xp_gain_factor and b.xp_dest_id then
				d.xp_gain_factor = b.xp_gain_factor
				d.xp_dest_id = b.source_id
			end

			queue_damage(store, d)
			log.paranoid("bomb id:%s, radius:%s, enemy id:%s, dist:%s, damage:%s damage_type:%x", this.id, dradius, enemy.id, V.dist(enemy.pos.x, enemy.pos.y, b.to.x, b.to.y), d.value, d.damage_type)

			if b.mod or b.mods then
				local mods = b.mods or {b.mod}

				if b.mod and b.mods then
					mods = table.merge(b.mods, {b.mod})
				end

				for _, mod_name in pairs(mods) do
					local m = E:create_entity(mod_name)

					m.modifier.target_id = enemy.id
					m.modifier.source_id = b.source_id
					m.modifier.level = b.level or 1

					simulation:queue_insert_entity(m)
				end
			end
		end
	end

	local p = SU.create_bullet_pop(store, this)

	simulation:queue_insert_entity(p)

	local cell_type = GR:cell_type(b.to.x, b.to.y)

	if b.hit_fx_water and band(cell_type, TERRAIN_WATER) ~= 0 then
		S:queue(this.sound_events.hit_water)

		local water_fx = E:create_entity(b.hit_fx_water)

		water_fx.pos.x, water_fx.pos.y = b.to.x, b.to.y
		water_fx.render.sprites[1].ts = store.tick_ts
		water_fx.render.sprites[1].sort_y_offset = b.hit_fx_sort_y_offset

		simulation:queue_insert_entity(water_fx)
	elseif b.hit_fx then
		S:queue(this.sound_events.hit)

		local sfx = E:create_entity(b.hit_fx)

		sfx.pos = V.vclone(b.to)

		for i = 1, #sfx.render.sprites do
			sfx.render.sprites[i].ts = store.tick_ts
			sfx.render.sprites[i].sort_y_offset = b.hit_fx_sort_y_offset
		end

		simulation:queue_insert_entity(sfx)
	end

	if b.hit_decal and band(cell_type, TERRAIN_WATER) == 0 then
		local decal = E:create_entity(b.hit_decal)

		decal.pos = V.vclone(b.to)

		for i = 1, #decal.render.sprites do
			decal.render.sprites[i].ts = store.tick_ts
		end

		simulation:queue_insert_entity(decal)
	end

	if b.hit_payload then
		local hp

		if type(b.hit_payload) == "string" then
			hp = E:create_entity(b.hit_payload)
		else
			hp = b.hit_payload
		end

		hp.pos.x, hp.pos.y = b.to.x, b.to.y
		hp.source_id = b.source_id

		if hp.aura then
			hp.aura.level = this.bullet.level
		end

		simulation:queue_insert_entity(hp)
	end

	if this.screenshake_amplitude then
		local shake = E:create_entity("aura_screen_shake")

		shake.aura.amplitude = this.screenshake_amplitude
		shake.aura.duration = this.screenshake_duration
		shake.aura.freq_factor = this.screenshake_freq_factor

		simulation:queue_insert_entity(shake)
	end

	if shadow then
		simulation:queue_remove_entity(shadow)
	end

	simulation:queue_remove_entity(this)
end

-- 通用 decal 工具（关卡 202 的 lamp / merlin / scroll 模板引用；按通用工具保留在 scripts 中）
scripts.decal_utils = {}

function scripts.decal_utils.animation_on_tap_update(this, store, script)
	local tapped = false

	while not tapped do
		if this.ui and this.ui.clicked then
			if this.tap_sound then
				S:queue(this.tap_sound)
			end

			U.y_animation_play(this, this.tap_anim, nil, store.tick_ts, this.tap_anim_play_times)

			if not this.no_loop_anim then
				U.animation_start(this, this.loop_anim, nil, store.tick_ts, true)
			end

			this.ui.clicked = nil

			if this.tap_disables then
				this.ui.can_click = false
			end

			if this.tap_ends then
				tapped = true
			end
		end

		coroutine.yield()
	end
end

function scripts.decal_utils.censor_cn_insert(this, store, script)
	return true
end

function scripts.decal_utils.track_target_update(this, store, script)
	local target = store.entities[this.target_id]
	local s

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	this.pos.x, this.pos.y = target.pos.x, target.pos.y

	local st = target.render.sprites[1]

	if this.render then
		for _, sp in ipairs(this.render.sprites) do
			sp.ts = store.tick_ts
		end

		s = this.render.sprites[1]
	end

	local function contains(str, pattern, exclude)
		local c = string.find(str, pattern) ~= nil

		if exclude then
			local e = type(exclude) == "table" and exclude or {exclude}

			for _, vv in ipairs(e) do
				if string.find(str, vv) ~= nil then
					return false
				end
			end
		end

		return c
	end

	while true do
		target = store.entities[this.target_id]

		if not target or target.health.dead then
			if target and this.animation_out and s then
				U.y_animation_play(this, this.animation_out, target.render.sprites[1].flip_x, store.tick_ts, 1, 1)
			end

			queue_remove(store, this)

			return
		end

		if this.flip and s then
			s.flip_x = st.flip_x
		end

		if this.animation_front and this.string_front and s and s.name ~= this.animation_front and contains(st.name, this.string_front, this.exclude_front) then
			U.animation_start(this, this.animation_front, s.flip_x, store.tick_ts, true, 1)

			if this.sort_y_offset_front then
				s.sort_y_offset = this.sort_y_offset_front
			end
		end

		if this.animation_back and this.string_back and s and s.name ~= this.animation_back and contains(st.name, this.string_back, this.exclude_back) then
			U.animation_start(this, this.animation_back, s.flip_x, store.tick_ts, true, 1)

			if this.sort_y_offset_back then
				s.sort_y_offset = this.sort_y_offset_back
			end
		end

		this.pos.x, this.pos.y = target.pos.x, target.pos.y

		if this.render then
			for _, sp in ipairs(this.render.sprites) do
				sp.ts = store.tick_ts
			end
		end

		coroutine.yield()
	end
end

scripts.decal_utils.animation_in_loop_out = {}

function scripts.decal_utils.animation_in_loop_out.update(this, store, script)
	if not this.start_sprite_idx then
		this.start_sprite_idx = 1
	end

	if not this.idle_sprite_idx then
		this.idle_sprite_idx = 1
	end

	if not this.end_sprite_idx then
		this.end_sprite_idx = 1
	end

	if this.delay_animation_start then
		U.y_wait(store, this.delay_animation_start)
	end

	this.render.sprites[1].animated = true

	for i = 1, #this.render.sprites do
		this.render.sprites[i].hidden = false
	end

	if this.animation_start then
		U.y_animation_play(this, this.animation_start, nil, store.tick_ts, 1, this.start_sprite_idx)
	end

	if this.animation_idle then
		U.animation_start(this, this.animation_idle, nil, store.tick_ts, true, this.idle_sprite_idx, this.idle_force_ts)

		this.ts = store.tick_ts

		while store.tick_ts - this.ts < this.duration do
			coroutine.yield()
		end
	end

	if this.animation_end then
		U.y_animation_play(this, this.animation_end, nil, store.tick_ts, 1, this.end_sprite_idx)
	end

	queue_remove(store, this)
end

scripts.aura_shadow_blades_smoke = {}

function scripts.aura_shadow_blades_smoke.insert(this, store, script)
	this.aura.ts = store.tick_ts

	if this.render then
		for _, s in pairs(this.render.sprites) do
			s.ts = store.tick_ts
		end
	end

	this.aura.duration = SU.get_difficulty_field_value(store, this.aura.duration)
	this.actual_duration = this.aura.duration

	local nearest_nodes = P:nearest_nodes(this.pos.x, this.pos.y)
	local pi, _, ni = unpack(nearest_nodes[1])

	this.pos = P:node_pos(pi, 1, ni)
	this.decals = {}
	this.decals_pos = {P:node_pos(pi, 1, ni - 4), P:node_pos(pi, 1, ni), P:node_pos(pi, 1, ni + 4), P:node_pos(pi, 2, ni - 2), P:node_pos(pi, 2, ni + 2), P:node_pos(pi, 3, ni - 2), P:node_pos(pi, 3, ni + 2)}

	for k, v in pairs(this.decals_pos) do
		local decal = E:create_entity(this.decal_t)

		decal.pos = v
		decal.render.sprites[1].ts = store.tick_ts - fts(math.random(0, 15))
		decal.tween.ts = store.tick_ts

		simulation:queue_insert_entity(decal)
		table.insert(this.decals, decal)
	end

	return true
end

function scripts.aura_shadow_blades_smoke.remove(this, store, script)
	for k, v in pairs(this.decals) do
		v.tween.ts = store.tick_ts
		v.tween.reverse = true
		v.tween.remove = true
	end

	return true
end

scripts.enemy_shadow_blades = {}

function scripts.enemy_shadow_blades.update(this, store, script)
	local function check_smokebomb()
		return not this.health.dead and this.health.hp < this.health.hp_max * this.smokebomb.hp_threshold and this.enemy.can_do_magic and P:nodes_to_goal(this.nav_path.pi, this.nav_path.spi, this.nav_path.ni) >= this.smokebomb.min_nodes_to_exit
	end

	::label_94_0::

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if check_smokebomb() then
				U.animation_start(this, this.smokebomb.animation, nil, store.tick_ts, false)

				if U.y_wait(store, this.smokebomb.delay, function()
					return this.health.dead or this.unit.is_stunned
				end) then
					goto label_94_0
				end

				this.health_bar.alpha = 0
				this.health.hp = this.health.hp_max
				this.health.ignore_damage = true
				U.bans_add(this.vis, F_ALL)
				this.trigger_deselect = true

				S:queue(this.smokebomb.sound)

				local smoke = E:create_entity(this.smokebomb.smoke_t)

				if smoke.aura then
					smoke.aura.source_id = this.id
					smoke.aura.ts = store.tick_ts
				end

				smoke.pos = V.vclone(this.pos)

				simulation:queue_insert_entity(smoke)
				U.y_animation_wait(this)
				simulation:queue_remove_entity(this)

				return
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, check_smokebomb, check_smokebomb, check_smokebomb) then
			-- block empty
			else
				coroutine.yield()
			end
		end
	end
end

scripts.mod_shadow_blades_smoke = {}

function scripts.mod_shadow_blades_smoke.insert(this, store, script)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or target.health.dead then
		return false
	end

	if band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	if target and target.unit and this.render then
		for i = 1, #this.render.sprites do
			local s = this.render.sprites[i]

			s.flip_x = target.render.sprites[1].flip_x
			s.ts = store.tick_ts

			if s.size_names then
				s.name = s.size_names[target.unit.size]
			end
		end
	end

	if target then
		if target.dodge then
			target._old_dodge = target.dodge
		end

		E:add_comps(target, "dodge")

		target.dodge.chance = 1
		target.dodge.show_pop = true
		target.dodge.silent = true
		target.dodge.ranged = true
	end

	return true
end

function scripts.mod_shadow_blades_smoke.remove(this, store, script)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if target then
		if target._old_dodge then
			target.dodge = target._old_dodge
		else
			target.dodge = nil
		end
	end

	return true
end

-- kr6 关卡 203：乌鸦（暗影召唤流小怪）
scripts.enemy_crow = {}

function scripts.enemy_crow.update(this, store)
	local shadow_sprite = this.render.sprites[2]

	U.y_animation_play(this, "in", nil, store.tick_ts, 1)
	U.animation_start(this, "idle", nil, store.tick_ts, true)

	while true do
		if this.health.dead then
			shadow_sprite.hidden = true

			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			SU.y_enemy_walk_until_blocked(store, this)
		end
	end
end

-- ============ KR6 关卡 204：新敌人脚本（crowcaller / goblin / orc） ============

scripts.tween_utils = {}

-- 延迟移除：先播 tween 反向淡出，tween 跑完后由 all/systems/tween.lua 统一移除。
-- 本函数返回 false 表示本帧不移除；返回前清掉 pending_removal，all/simulation.lua
-- 据此识别为「正常延迟跳过」而非异常阻断，不再打印 "remove xxx aborted"。
function scripts.tween_utils.reverse_remove(this, store, script)
	if this.tween.disabled then
		if this.tween_prop_replace then
			this.tween.props[1].keys[2] = this.tween_prop_replace
		end

		this.tween.disabled = false
		this.tween.ts = store.tick_ts
		this.tween.remove = true
		this.tween.reverse = true
		this.tween.run_once = false
		this.pending_removal = false

		if this.timed then
			this.timed.duration = 10
		end

		for i = 2, #this.tween.props do
			this.tween.props[i].disabled = true
		end

		return false
	end

	return true
end

local function get_random_round_robin(mutable_history, n, m)
	if not m then
		m = n
		n = 1
	end

	if m < n then
		log.error("ERROR: Random round robin needs M to be bigger or equal than N")
	end

	if #mutable_history == 0 then
		for i = n, m do
			table.insert(mutable_history, i)
		end
	end

	local pos = math.random(1, #mutable_history)
	local value = mutable_history[pos]

	table.remove(mutable_history, pos)

	return value
end

scripts.enemy_crowcaller = {}

function scripts.enemy_crowcaller.update(this, store, script)
	local as = this.timed_attacks.list[1]

	as.ts = store.tick_ts

	local cg = store.count_groups[as.count_group_type]
	local spawn_count = SU.get_difficulty_field_value(store, as.spawn_count)

	local function ready_to_spawn()
		return store.tick_ts - as.ts > as.cooldown and this.enemy.can_do_magic and (not cg[as.count_group_name] or cg[as.count_group_name] < as.count_group_max)
	end

	local function break_fn()
		return ready_to_spawn() and P:nodes_to_goal(this.nav_path.pi, this.nav_path.spi, this.nav_path.ni) > this.spawn_crow_node_limit
	end

	::label_crowcaller_0::

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if ready_to_spawn() and P:nodes_to_goal(this.nav_path.pi, this.nav_path.spi, this.nav_path.ni) > this.spawn_crow_node_limit then
				S:queue(as.sound)

				as.ts = store.tick_ts

				U.animation_start(this, as.animation, nil, store.tick_ts, false)

				if SU.y_enemy_wait(store, this, as.cast_time) or #this.enemy.blockers > 0 then
					goto label_crowcaller_0
				end

				if spawn_count == 1 then
					local crow = E:create_entity(as.entity)

					crow.nav_path.pi = this.nav_path.pi
					crow.nav_path.spi = this.nav_path.spi
					crow.nav_path.ni = this.nav_path.ni + 6
					crow.pos = P:node_pos(crow.nav_path.pi, crow.nav_path.spi, crow.nav_path.ni)
					crow.pos.y = crow.pos.y + 1
					crow.source_id = this.id
					crow.enemy.gold = 0
					crow.render.sprites[1].flip_x = this.render.sprites[1].flip_x

					queue_insert(store, crow)
				else
					local spi_history = {}
					local ni_history = {}

					for _ = 1, spawn_count do
						local crow = E:create_entity(as.entity)

						crow.nav_path.pi = this.nav_path.pi
						crow.nav_path.spi = get_random_round_robin(spi_history, 3)
						crow.nav_path.ni = this.nav_path.ni + get_random_round_robin(ni_history, 4, 8)
						crow.pos = P:node_pos(crow.nav_path.pi, crow.nav_path.spi, crow.nav_path.ni)
						crow.pos.y = crow.pos.y + 1
						crow.source_id = this.id
						crow.enemy.gold = 0
						crow.render.sprites[1].flip_x = this.render.sprites[1].flip_x

						queue_insert(store, crow)
					end
				end

				U.y_animation_wait(this)
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, break_fn, false) then
			else
				coroutine.yield()
			end
		end
	end
end

scripts.enemy_headhunter = {}

function scripts.enemy_headhunter.can_instakill(this, store, attack, target)
	return target.health and target.health.hp / target.health.hp_max <= SU.get_difficulty_field_value(store, attack.hp_threshold) and band(attack.vis_bans, target.vis.flags) == 0
end

scripts.enemy_goblin = {}

function scripts.enemy_goblin.update(this, store, script)
	if this.spawn_from_bullet then
		this.render.sprites[1].flip_x = this.start_flipped

		U.y_animation_play(this, "fall", nil, store.tick_ts)

		local nearest

		if P:is_path_active(this.path_to_spawn) then
			nearest = P:nearest_nodes(this.pos.x, this.pos.y, {this.path_to_spawn}, {1, 2, 3})
		else
			nearest = P:nearest_nodes(this.pos.x, this.pos.y, nil, {1, 2, 3}, true)
		end

		local path_pi, path_spi, path_ni

		if #nearest > 0 then
			path_pi, path_spi, path_ni = unpack(nearest[1])
		end

		this.nav_path.pi = path_pi
		this.nav_path.spi = path_spi
		this.nav_path.ni = path_ni
	end

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		elseif not SU.y_enemy_mixed_walk_melee_ranged(store, this, false) then
		else
			coroutine.yield()
		end
	end
end

scripts.enemy_orc_warrior = {}

function scripts.enemy_orc_warrior.update(this, store, script)
	local aura = E:create_entity(this.rage.aura)

	aura.aura.source_id = this.id
	aura.aura.ts = store.tick_ts

	queue_insert(store, aura)

	local function can_rage()
		return this.trigger_rage and this.enemy.can_do_magic and not U.has_modifiers(store, this, this.rage.mod)
	end

	::label_orc_warrior_0::

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if this.trigger_rage then
				S:queue(this.rage.sound)

				this.trigger_rage = false

				U.animation_start(this, this.rage.animation, nil, store.tick_ts, false)

				if SU.y_enemy_wait(store, this, this.rage.cast_time) then
					goto label_orc_warrior_0
				end

				local mod = E:create_entity(this.rage.mod)

				mod.modifier.target_id = this.id
				mod.modifier.source_id = this.id

				queue_insert(store, mod)

				if SU.y_enemy_animation_wait(this) then
					goto label_orc_warrior_0
				end
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, can_rage, can_rage) then
			else
				coroutine.yield()
			end
		end
	end
end

scripts.aura_orc_warrior_rage_check = {}

function scripts.aura_orc_warrior_rage_check.update(this, store, script)
	local last_cycle_ts = 0

	if this.aura.track_source and this.aura.source_id then
		local te = store.entities[this.aura.source_id]

		if te and te.pos then
			this.pos = te.pos
		end
	end

	while true do
		local te = store.entities[this.aura.source_id]

		if this.aura.track_source and this.aura.source_id and (not te or te.health and te.health.dead and not this.aura.track_dead) then
			break
		end

		if this.aura.requires_magic then
			if not te or not te.enemy then
				goto label_rage_check_0
			end

			if not te.enemy.can_do_magic then
				goto label_rage_check_0
			end
		end

		if U.has_modifiers(store, te, te.rage.mod) then
		elseif store.tick_ts - last_cycle_ts >= this.aura.cycle_time then
			last_cycle_ts = store.tick_ts

			local targets = table.filter(store.entities, function(_, v)
				return v.enemy and v.health and (v.health.dead or v.health.hp <= 0) and U.is_inside_ellipse(v.pos, this.pos, this.aura.radius) and (not this.aura.allowed_templates or table.contains(this.aura.allowed_templates, v.template_name))
			end)

			if targets and #targets > 0 then
				te.trigger_rage = true
			end
		end

		::label_rage_check_0::

		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.mod_orc_warrior_rage = {}

function scripts.mod_orc_warrior_rage.update(this, store, script)
	local m = this.modifier

	this.modifier.ts = store.tick_ts

	local target = store.entities[m.target_id]

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos
	this.tween.ts = store.tick_ts

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or m.duration >= 0 and store.tick_ts - m.ts > m.duration or m.last_node and target.nav_path.ni > m.last_node then
			this.tween.remove = true
			this.tween.reverse = true
			this.tween.ts = store.tick_ts

			return
		end

		coroutine.yield()
	end
end

scripts.enemy_orc_shaman = {}

function scripts.enemy_orc_shaman.update(this, store, script)
	local ah = this.timed_attacks.list[1]
	local heal_check_ts = store.tick_ts
	local trigger_heal

	local function can_heal()
		if not this.enemy.can_do_magic then
			return false
		end

		if trigger_heal then
			return true
		end

		if store.tick_ts - heal_check_ts < 0.25 then
			return false
		end

		if store.tick_ts - ah.ts < ah.cooldown then
			return false
		end

		heal_check_ts = store.tick_ts

		local targets = U.find_enemies_in_range(store, this.pos, 0, ah.range, this.vis.flags, 0, function(e)
			return e.health and e.health.hp / e.health.hp_max < ah.max_target_hp
		end)

		trigger_heal = targets and #targets >= ah.min_targets

		return trigger_heal
	end

	::label_orc_shaman_0::

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if trigger_heal then
				S:queue(ah.sound)

				trigger_heal = false
				ah.ts = store.tick_ts

				U.animation_start(this, ah.animation, nil, store.tick_ts, false)

				if SU.y_enemy_wait(store, this, ah.cast_time) then
					goto label_orc_shaman_0
				end

				local aura = E:create_entity(ah.aura)

				aura.aura.source_id = this.id
				aura.aura.ts = store.tick_ts

				queue_insert(store, aura)

				while not U.animation_finished(this) do
					if SU.enemy_interrupted(this) then
						goto label_orc_shaman_0
					end

					coroutine.yield()
				end
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, can_heal) then
			else
				coroutine.yield()
			end
		end
	end
end

