-- ==================== kr6 关卡 205：enemy_orc_wildling ====================
scripts.enemy_orc_wildling = {}

function scripts.enemy_orc_wildling.update(this, store, script)
	local worg_mode = false
	local worg_check_ts = store.tick_ts
	local trigger_mode_change = false
	local normal_angles = this.render.sprites[1].angles.walk
	local mod

	E:get_template(this.worg_mode.mod).slow.factor = SU.get_difficulty_field_value(store, this.worg_mode.speed)

	local function check_worg_mode_change()
		if store.tick_ts - worg_check_ts < 0.25 then
			return false
		end

		worg_check_ts = store.tick_ts

		local range = worg_mode and this.worg_mode.range * 1.2 or this.worg_mode.range
		local targets = U.find_enemies_in_range(store, this.pos, 0, range, this.vis.flags, 0, function(e, o)
			return e.template_name == "enemy_worg"
		end)

		trigger_mode_change = worg_mode ~= (targets and #targets >= 1)
		worg_mode = targets and #targets >= 1

		return trigger_mode_change
	end

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if trigger_mode_change then
				trigger_mode_change = false

				if worg_mode then
					S:queue(this.worg_mode.sound_in)

					this.render.sprites[1].angles.walk = this.worg_mode.angles_walk
					mod = E:create_entity(this.worg_mode.mod)
					mod.modifier.target_id = this.id
					mod.modifier.source_id = this.id

					queue_insert(store, mod)
				else
					this.render.sprites[1].angles.walk = normal_angles

					if mod then
						mod.modifier.duration = 0
					end

					mod = nil
				end
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, check_worg_mode_change) then
			else
				coroutine.yield()
			end
		end
	end
end

scripts.tower_spawn_soldier_on_path = {}

function scripts.tower_spawn_soldier_on_path.can_select_point(this, x, y)
	return P:valid_node_nearby(x, y)
end

function scripts.tower_spawn_soldier_on_path.update(this, store)
	this.soldiers_alive = 0

	local function activate()
		this.soldiers_alive = km.clamp(0, this.max_soldiers, this.soldiers_alive + 1)

		S:queue(this.tower_action.sound)

		local soldier = E:create_entity(this.soldier_t)

		soldier.path_id = this.path_id
		soldier.pos = P:node_pos(this.path_id, 1, 1)
		soldier.source_id = this.id

		queue_insert(store, soldier)
		S:queue(this.tower_action.post_sound)
	end

	local function on_soldier_died()
		this.soldiers_alive = km.clamp(0, this.max_soldiers, this.soldiers_alive - 1)
	end

	this.on_soldier_died = on_soldier_died

	while true do
		this.tower_action.active = store.wave_group_number == 0 or this.soldiers_alive >= this.max_soldiers
		this.user_selection.allowed = not this.tower_action.active and store.player_gold >= this.tower_action.cost

		if this.user_selection.in_progress and not this.tower_action.active then
			this.user_selection.in_progress = nil
			this.user_selection.allowed = false
			store.player_gold = store.player_gold - this.tower_action.cost

			activate()
		end

		if this.user_selection.in_progress then
			this.user_selection.in_progress = nil
		end

		coroutine.yield()
	end
end

scripts.soldier_walk_to_objective = {}

function scripts.soldier_walk_to_objective.update(this, store)
	local brk, sta
	local path_ni = 1
	local path_spi = 1
	local target_pos = P:node_pos(this.path_id, path_spi, path_ni)

	if this.vis._bans_added then
		U.bans_remove(this.vis, F_ALL)
		this.vis._bans_added = nil
	end

	local function do_step()
		if V.veq(this.pos, target_pos) then
			this.motion.arrived = true

			return false
		else
			U.set_destination(this, target_pos)

			if U.walk(this, store.tick_length) then
				return false
			else
				local an, af = U.animation_name_facing_point(this, "walk", this.motion.dest, 1)

				U.animation_start(this, an, af, store.tick_ts, true)

				return true
			end
		end
	end

	local function run_to_objective()
		local distSq = V.dist2(target_pos.x, target_pos.y, this.pos.x, this.pos.y)

		if distSq < this.distance_sqd then
			path_ni = path_ni + 2
			target_pos = P:node_pos(this.path_id, path_spi, path_ni)
		end

		do_step()
	end

	while true do
		if P:nodes_to_goal(this.path_id, 1, path_ni) < 3 then
			break
		end

		if this.health.dead then
			local tower = store.entities[this.source_id]

			if tower and tower.on_soldier_died then
				tower.on_soldier_died()
			end

			SU.y_soldier_death(store, this)

			return
		end

		brk, sta = SU.y_soldier_melee_block_and_attacks(store, this)

		if brk or sta ~= A_NO_TARGET then
			if sta == A_DONE then
				local nearest = P:nearest_nodes(this.pos.x, this.pos.y, {this.path_id}, nil)
				local _, _, ni = unpack(nearest[1])

				path_ni = ni + 2
				target_pos = P:node_pos(this.path_id, path_spi, path_ni)
			end
		else
			run_to_objective()
		end

		coroutine.yield()
	end

	this.on_arrived(this, store)
	queue_remove(store, this)
end

-- ==================== kr6 关卡 207：goblin 狼骑 ====================

scripts.enemy_rider_goblin = {}

function scripts.enemy_rider_goblin.update(this, store, script)
	while true do
		if this.health.dead then
			local can_spawn = band(this.health.last_damage_types, this.no_spawn_damage_types) == 0

			if can_spawn and store.level.run_complete and store.waves_finished then
				local enemies_left = table.filter(store.entities, function(_, e)
					return e.main_script and (e.main_script.co or e.main_script.runs > 0) and (e.enemy and e.health and not e.health.dead or e.enemy and e.death_spawns or e.spawner and not e.spawner.eternal or e.picked_enemies and #e.picked_enemies > 0 or e.tunnel and #e.tunnel.picked_enemies > 0) and e.id ~= this.id
				end)

				can_spawn = #enemies_left > 0
			end

			if can_spawn and not this.forced_death then
				local c = E:create_entity(this.spawn_controller)

				c.worg = this

				queue_insert(store, c)

				this.sound_events.death = this.sound_death_and_spawn
			end

			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		elseif not SU.y_enemy_mixed_walk_melee_ranged(store, this, false) then
		-- block empty
		else
			coroutine.yield()
		end
	end
end

scripts.controller_rider_goblin_spawn = {}

function scripts.controller_rider_goblin_spawn.update(this, store, script)
	local np = this.worg.nav_path
	local nodes_ahead = math.random(this.min_nodes_ahead, this.max_nodes_ahead)
	local nodes_to_end = P:nodes_to_goal(np.pi, np.spi, np.ni)

	if nodes_to_end <= this.spawn_max_nodes_to_exit then
		nodes_ahead = 1
	end

	local dest = P:node_pos(np.pi, np.spi, np.ni + nodes_ahead)
	local offset_x = this.start_offset.x

	if this.worg.render.sprites[1].flip_x then
		offset_x = offset_x * -1
	end

	local b = E:create_entity(this.spawn_bullet)

	b.pos.x, b.pos.y = this.worg.pos.x + offset_x, this.worg.pos.y + this.start_offset.y
	b.bullet.from = V.vclone(b.pos)
	b.bullet.to = dest
	b.bullet.source_id = this.worg.id
	b.path_to_spawn = np.pi

	queue_insert(store, b)
	queue_remove(store, this)
end

scripts.bullet_enemy_flying = {}

function scripts.bullet_enemy_flying.update(this, store, script)
	local b = this.bullet
	local shadow, shadow_start_pos

	if this.decal_shadow then
		shadow = E:create_entity(this.decal_shadow)

		shadow.pos = V.vclone(b.from)
		shadow.pos.y = b.from.y - 25

		queue_insert(store, shadow)

		shadow_start_pos = V.vclone(shadow.pos)
	end

	while store.tick_ts - b.ts + store.tick_length < b.flight_time do
		coroutine.yield()

		b.last_pos.x, b.last_pos.y = this.pos.x, this.pos.y
		this.pos.x, this.pos.y = SU.position_in_parabola(store.tick_ts - b.ts, b.from, b.speed, b.g)

		if b.align_with_trajectory then
			this.render.sprites[1].r = V.angleTo(this.pos.x - b.last_pos.x, this.pos.y - b.last_pos.y)
		elseif b.rotation_speed then
			this.render.sprites[1].r = this.render.sprites[1].r + b.rotation_speed * store.tick_length
		end

		if b.hide_radius then
			this.render.sprites[1].hidden = V.dist(this.pos.x, this.pos.y, b.from.x, b.from.y) < b.hide_radius or V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) < b.hide_radius
		end

		if shadow then
			shadow.pos.x = shadow_start_pos.x + (b.to.x - shadow_start_pos.x) * ((store.tick_ts - b.ts) / b.flight_time)
			shadow.pos.y = shadow_start_pos.y + (b.to.y - shadow_start_pos.y) * ((store.tick_ts - b.ts) / b.flight_time)

			local height = this.pos.y - shadow.pos.y
			local s = km.clamp(0.6, 1, 40 / height)

			shadow.render.sprites[1].scale = V.vv(s)
		end
	end

	local goblin = E:create_entity(b.hit_payload)

	goblin.pos = V.vclone(b.to)
	goblin.spawn_from_bullet = true
	goblin.path_to_spawn = this.path_to_spawn
	goblin.start_flipped = b.from.x > b.to.x

	queue_insert(store, goblin)

	if b.hit_fx then
		local hfx = E:create_entity(b.hit_fx)

		hfx.pos = V.vclone(b.to)
		hfx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, hfx)
	end

	if shadow then
		queue_remove(store, shadow)
	end

	queue_remove(store, this)
end

-- ===== KR6 stage 08 =====
scripts.enemy_cloud_of_crows = {}

function scripts.enemy_cloud_of_crows.update(this, store)
	local function break_fn_1(store, this)
		return this.nav_path.ni > this.nodes_to_explode
	end

	local function break_fn_2(store, this)
		return store.tick_ts - this.tween.ts > fts(16)
	end

	local function break_fn_3(store, this)
		return store.tick_ts - this.render.sprites[1].ts > fts(5)
	end

	SU.y_enemy_walk_until_blocked(store, this, true, break_fn_1)

	this.tween.disabled = false
	this.tween.ts = store.tick_ts

	SU.y_enemy_walk_until_blocked(store, this, true, break_fn_2)

	this.tween.reverse = true
	this.tween.ts = store.tick_ts
	this.render.sprites[1].angles.walk = {"attack", "attack", "attack"}

	U.animation_start(this, "attack", nil, store.tick_ts, false)
	SU.y_enemy_walk_until_blocked(store, this, true, break_fn_3)

	local explosion = E:create_entity(this.explosion_fx)

	explosion.pos = V.vclone(this.pos)
	explosion.render.sprites[1].ts = store.tick_ts

	simulation:queue_insert_entity(explosion)

	if this.sound_explosion then
		S:queue(this.sound_explosion)
	end

	for i = 1, this.spawn_count do
		local enemy = E:create_entity(this.enemy_spawn)

		enemy.nav_path.pi = this.nav_path.pi

		if i == 2 or i == 3 then
			enemy.nav_path.ni = this.nav_path.ni
			enemy.nav_path.spi = i
		elseif i == 1 then
			enemy.nav_path.ni = this.nav_path.ni + 3
			enemy.nav_path.spi = 1
		else
			enemy.nav_path.ni = this.nav_path.ni - 6
			enemy.nav_path.spi = 1
		end

		enemy.pos = P:node_pos(enemy.nav_path.pi, 1, enemy.nav_path.ni)
		enemy.source_id = this.id

		simulation:queue_insert_entity(enemy)
	end

	simulation:queue_remove_entity(this)
end

scripts.soldier_stage_208_templar_archer = {}

function scripts.soldier_stage_208_templar_archer.insert(this, store)
	this.nav_rally.new = true
	this.nav_rally.pos = V.vclone(this.pos)
	this.nav_rally.center = V.vclone(this.pos)
	this.motion.arrived = false

	if this.editor.wall_id == 1 then
		this.pos.x, this.pos.y = this.pos.x + 280, this.pos.y - 448
	else
		this.pos.x, this.pos.y = this.pos.x + 140, this.pos.y - 224
	end

	return scripts.soldier_barrack.insert(this, store)
end

function scripts.soldier_stage_208_templar_archer.ranged_attack_filter_fn(entity, origin)
	if not entity or not entity.nav_path then
		return false
	end

	return P:is_node_valid(entity.nav_path.pi, entity.nav_path.ni, NF_RANGE)
end

function scripts.soldier_stage_208_templar_archer.update(this, store)
	while this.nav_rally.new do
		SU.y_soldier_new_rally(store, this)
	end

	U.animation_start(this, "idle", true, store.tick_ts, true)

	return scripts.soldier_barrack.update(this, store)
end

scripts.soldier_stage_208_templar_swordsman = {}

function scripts.soldier_stage_208_templar_swordsman.update(this, store)
	local path_ni = this.starting_ni

	if this.vis._bans_added then
		U.bans_remove(this.vis, F_ALL)
		this.vis._bans_added = nil
	end

	this.nav_rally.pos = P:node_pos(this.path_id, this.subpath_id, path_ni)
	-- dove 的 nav_rally.center 默认是 v(0,0)（KR6 是 nil，会让 `nav_rally.center or this.pos`
	-- 回退到 this.pos）。这里不跟随自身位置的话，索敌中心会停在原点，士兵永不拦截。
	this.nav_rally.center.x, this.nav_rally.center.y = this.pos.x, this.pos.y
	this.melee.order = U.attack_order(this.melee.attacks)

	while true do
		if path_ni < 3 then
			break
		end

		if this.health.dead then
			local tower = store.entities[this.source_id]

			tower.soldiers_alive = tower.soldiers_alive - 1

			SU.y_soldier_death(store, this)

			return
		end

		this.nav_rally.center.x, this.nav_rally.center.y = this.pos.x, this.pos.y
		local brk, sta = SU.y_soldier_melee_block_and_attacks(store, this)

		if brk or sta == A_DONE or sta == A_IN_COOLDOWN and not this.melee.continue_in_cooldown then
		-- block empty
		else
			if V.dist2(this.nav_rally.pos.x, this.nav_rally.pos.y, this.pos.x, this.pos.y) < 25 then
				path_ni = path_ni - 3
				this.nav_rally.pos = P:node_pos(this.path_id, this.subpath_id, path_ni)
			end

			if SU.soldier_go_back_step(store, this) then
			-- block empty
			else
				SU.soldier_regen(store, this)
			end
		end

		coroutine.yield()
	end

	simulation:queue_remove_entity(this)
end

function scripts.soldier_stage_208_templar_swordsman.remove(this, store)
	this.cont_ref.soldiers_alive = this.cont_ref.soldiers_alive - 1

	return true
end

-- ============ KR6 关卡 209：deep trolls 敌人脚本 ============

scripts.enemy_troll_champion_jumper = {}

function scripts.enemy_troll_champion_jumper.update(this, store)
	local walk = true
	local jump_i = 1
	local dest = P:node_pos(this.nav_path.pi, this.nav_path.spi, this.jump_points[jump_i][1])
	local old_speed = this.motion.max_speed
	local old_hb_offset_y = this.health_bar.offset.y
	local old_cr_offset_y = this.ui.click_rect.pos.y
	local old_ho_offset_y = this.unit.hit_offset.y
	local old_mo_offset_y = this.unit.mod_offset.y
	local y_offset = 0
	local y_velocity, y_accel
	local shadow_sprite = this.render.sprites[2]
	local shadow_tween = this.tween

	if this.force_center_path then
		this.nav_path.spi = 1
	end

	local function calc_gravity(d)
		local t = d / this.motion.max_speed

		y_accel = -2 * this.jump_speed.y / t
	end

	local function calc_velocity(t, startx, destx)
		y_velocity = -(this.jump_gravity / 2) * t
		U.update_max_speed(this, math.abs(destx - startx) / t)
	end

	local function is_in_gap(pos, gap)
		local start = P:node_pos(this.nav_path.pi, this.nav_path.spi, gap[1])
		local finish = P:node_pos(this.nav_path.pi, this.nav_path.spi, gap[2])
		local dirx = finish.x - start.x
		local diry = finish.y - start.y
		local tx = (pos.x - start.x) / dirx
		local ty = (pos.y - start.y) / diry

		return math.max(tx, ty) < 1
	end

	local function fall_death(start_y_velocity, start_y_offset, over_void)
		this.render.sprites[1].z = over_void and this.fall_void_z or Z_OBJECTS

		U.animation_start(this, "death_2", not this.render.sprites[1].flip_x, store.tick_ts, true)

		local y_velocity = math.min(this.default_start_y_velocity, start_y_velocity)
		local y_accel = this.fall_gravity
		local dist_acum = 0
		local distance_to_despawn = over_void and math.abs(this.pos.y + this.render.sprites[1].offset.y - this.y_to_die) or start_y_offset

		while distance_to_despawn > math.abs(dist_acum) do
			y_velocity = y_velocity + y_accel * store.tick_length

			if over_void then
				this.pos.y = this.pos.y + y_velocity * store.tick_length
			else
				this.render.sprites[1].offset.y = this.render.sprites[1].offset.y + y_velocity * store.tick_length
			end

			dist_acum = dist_acum + y_velocity * store.tick_length

			coroutine.yield()
		end
	end

	local function should_hide_shadow_in_flight()
		return this.disappearing_shadows and (this.jump_points[jump_i][3] or not this.jump_points[jump_i][4] or is_in_gap(this.pos, this.jump_points[jump_i][4])) or false
	end

	U.flags_add(this.vis, F_FLYING)
	U.update_max_speed(this, old_speed)

	U.set_destination(this, dest)

	while true do
		if this.health.dead then
			local is_void = this.jump_points[jump_i][3] or not this.jump_points[jump_i][4] or is_in_gap(this.pos, this.jump_points[jump_i][4])

			if not walk then
				if is_void then
					shadow_sprite.hidden = true
					this.unit.show_blood_pool = false
				end

				fall_death(y_velocity, y_offset, is_void)
			end

			shadow_sprite.hidden = true

			SU.y_enemy_death(store, this)

			return
		end

		if walk and this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if walk then
				local an, af = U.animation_name_facing_point(this, "walk", this.motion.dest)

				U.animation_start(this, an, af, store.tick_ts, true)

				local reached_dest = U.walk(this, store.tick_length)

				walk = not reached_dest

				if not walk then
					dest = P:node_pos(this.nav_path.pi, this.nav_path.spi, this.jump_points[jump_i][2])

					U.y_animation_play(this, "jump", dest.x < this.pos.x, store.tick_ts)

					U.bans_add(this.vis, F_ALL)

					U.set_destination(this, dest)

					if this.jump_mode == "time" then
						y_accel = this.jump_gravity

						calc_velocity(this.jump_time, this.pos.x, dest.x)
					elseif this.jump_mode == "velocity" then
						U.update_max_speed(this, this.jump_speed.x)
						y_velocity = this.jump_speed.y

						calc_gravity(V.dist(this.pos.x, this.pos.y, dest.x, dest.y))
					end

					shadow_sprite.hidden = false

					if should_hide_shadow_in_flight() then
						shadow_tween.reverse = false
						shadow_tween.disabled = false
						shadow_tween.ts = store.tick_ts
					end
				end
			end

			if not walk then
				local reached_dest = U.walk(this, store.tick_length)

				this.nav_path.ni = P:nearest_nodes(dest.x, dest.y, {this.nav_path.pi}, {this.nav_path.spi})[1][3]
				y_velocity = y_velocity + y_accel * store.tick_length
				y_offset = km.clamp(0, 1e+99, y_offset + y_velocity * store.tick_length)

				if y_velocity > 0 then
					if this.render.sprites[1].name ~= "air_up" then
						U.animation_start(this, "air_up", nil, store.tick_ts, true)
					end
				elseif this.render.sprites[1].name ~= "air_down" then
					U.animation_start(this, "air_down", nil, store.tick_ts, true)
				end

				this.render.sprites[1].offset.x = 0
				this.render.sprites[1].offset.y = y_offset
				U.change_health_bar_offset_run_time(this.health_bar, old_hb_offset_y + y_offset)
				this.ui.click_rect.pos.y = old_cr_offset_y + y_offset
				this.unit.hit_offset.y = old_ho_offset_y + y_offset
				this.unit.mod_offset.y = old_mo_offset_y + y_offset

				if shadow_tween.disabled and shadow_sprite.alpha == 255 and should_hide_shadow_in_flight() then
					shadow_tween.reverse = false
					shadow_tween.disabled = false
					shadow_tween.ts = store.tick_ts
				end

				if shadow_tween.disabled and shadow_sprite.alpha == 0 and not should_hide_shadow_in_flight() then
					shadow_tween.reverse = true
					shadow_tween.disabled = false
					shadow_tween.ts = store.tick_ts
				end

				walk = reached_dest

				if walk then
					shadow_sprite.hidden = true
					y_offset = 0
					y_velocity = 0
					this.render.sprites[1].offset.x = 0
					this.render.sprites[1].offset.y = 0
					U.change_health_bar_offset_run_time(this.health_bar, old_hb_offset_y)
					this.ui.click_rect.pos.y = old_cr_offset_y
					this.unit.hit_offset.y = old_ho_offset_y
					this.unit.mod_offset.y = old_mo_offset_y
					U.bans_remove(this.vis, F_ALL)

					U.y_animation_play(this, "land", nil, store.tick_ts)

					U.update_max_speed(this, old_speed)
					jump_i = jump_i + 1

					if jump_i > #this.jump_points then
						break
					end

					dest = P:node_pos(this.nav_path.pi, this.nav_path.spi, this.jump_points[jump_i][1])

					U.set_destination(this, dest)
				end
			end
		end

		coroutine.yield()
	end

	U.flags_remove(this.vis, F_FLYING)
	this.nav_path.ni = P:nearest_nodes(this.pos.x, this.pos.y, {this.nav_path.pi}, {1})[1][3]

	local next = P:next_entity_node(this, store.tick_length)

	if not next then
		log.debug("(%s) %s has no valid next node", this.id, this.template_name)

		return false
	end

	U.set_destination(this, next)
	U.set_heading(this, next)
	scripts.enemy_mixed.update(this, store)
end

scripts.enemy_troll_glider = {}

function scripts.enemy_troll_glider.update(this, store)
	local shadow_sprite = this.render.sprites[2]

	while true do
		if this.health.dead then
			if band(this.health.last_damage_types, bor(DAMAGE_DISINTEGRATE)) ~= 0 and this.unit.can_disintegrate and this.unit.disintegrate_fx then
				local fx = E:create_entity(this.unit.disintegrate_fx)

				fx.pos.x, fx.pos.y = this.pos.x, this.pos.y
				fx.render.sprites[1].scale = V.vv(1)
				fx.render.sprites[1].ts = store.tick_ts

				if fx.render.sprites[1].size_names then
					fx.render.sprites[1].name = fx.render.sprites[1].size_names[this.unit.size]
				end

				if band(this.vis.flags, F_FLYING) ~= 0 and this.unit.hit_offset then
					fx.render.sprites[1].offset.y = this.unit.hit_offset.y
				end

				queue_insert(store, fx)

				this.unit.hide_during_death = true
				this.unit.show_blood_pool = false
			end

			if band(this.health.last_damage_types, bor(DAMAGE_INSTAKILL, DAMAGE_EAT)) ~= 0 then
				queue_remove(store, this)

				return
			end

			if band(this.health.last_damage_types, bor(DAMAGE_NO_SPAWNS)) ~= 0 then
				queue_remove(store, this)

				return
			end

			if band(this.health.last_damage_types, bor(DAMAGE_DISINTEGRATE)) == 0 then
				local fx = E:create_entity(this.death_fx)

				fx.pos = V.vclone(this.pos)
				fx.pos.x, fx.pos.y = fx.pos.x + this.death_fx_offset.x, fx.pos.y + this.death_fx_offset.y
				fx.render.sprites[1].ts = store.tick_ts
				fx.render.sprites[1].flip_x = this.render.sprites[1].flip_x

				queue_insert(store, fx)
			end

			S:queue(this.sound_events.death, this.sound_events.death_args)

			if GR:cell_is(this.pos.x, this.pos.y, bor(TERRAIN_LAND, TERRAIN_ICE)) and not GR:cell_is(this.pos.x, this.pos.y, bor(TERRAIN_NOWALK)) then
				U.animation_start(this, "fall_loop", nil, store.tick_ts)

				local dt = fts(1)

				while this.render.sprites[1].offset.y > 0 do
					this.render.sprites[1].offset.y = this.render.sprites[1].offset.y - this.fall_speed * dt

					coroutine.yield()
				end

				shadow_sprite.hidden = true

				U.y_animation_play(this, "drop", nil, store.tick_ts, 1, 1)
				SU.y_enemy_death(store, this)
				queue_remove(store, this)

				return
			else
				queue_remove(store, this)

				return
			end
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			SU.y_enemy_walk_until_blocked(store, this)
			coroutine.yield()
		end
	end
end

scripts.enemy_troll_crusher = {}

function scripts.enemy_troll_crusher.update(this, store, script)
	local ap = this.timed_attacks.list[1]

	ap.ts = store.tick_ts

	local pound_check_ts = store.tick_ts
	local trigger_pound = false

	local function should_pound()
		if not this.enemy.can_do_magic then
			return false
		end

		if trigger_pound then
			return true
		end

		if store.tick_ts - pound_check_ts < 0.25 then
			return false
		end

		if store.tick_ts - ap.ts < ap.cooldown then
			return false
		end

		pound_check_ts = store.tick_ts

		local aura_t = E:get_template(ap.aura)
		local towers = U.find_towers_in_range(store.towers, this.pos, {
			max_range = aura_t.aura.radius - ap.stun_radius_offset,
			min_range = 0
		}, function(v, o)
			return v.tower.type ~= "holder" and v.tower.type ~= "build_animation" and (not v.tower_holder or not v.tower_holder.blocked) and (not aura_t.aura.allowed_templates or table.contains(aura_t.aura.allowed_templates, v.template_name)) and (not aura_t.aura.excluded_templates or not table.contains(aura_t.aura.excluded_templates, v.template_name) and not U.has_modifier_types(store, v, MOD_TYPE_PROTECTION))
		end)

		trigger_pound = towers and #towers > 0

		return trigger_pound
	end

	local function deal_area_damage(hit_pos, attack)
		local targets = U.find_soldiers_in_range(store.entities, hit_pos, 0, attack.damage_radius, attack.vis_flags, attack.vis_bans, function(v, o)
			return not attack.fn_filter or attack.fn_filter(this, store, attack, v)
		end)

		if targets then
			for i, e in ipairs(targets) do
				if attack.count and i > attack.count then
					break
				end

				local d = E:create_entity("damage")

				d.source_id = this.id
				d.target_id = e.id
				d.damage_type = attack.damage_type
				d.value = math.ceil(this.unit.damage_factor * math.random(attack.damage_min, attack.damage_max))
				d.pop = attack.pop
				d.pop_chance = attack.pop_chance
				d.pop_conds = attack.pop_conds

				queue_damage(store, d)

				if attack.mod then
					local mod = E:create_entity(attack.mod)

					mod.modifier.target_id = e.id
					mod.modifier.source_id = this.id

					queue_insert(store, mod)
				end
			end
		end
	end

	::label_139_0::

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if trigger_pound then
				this.health.ignore_damage = true

				U.animation_start(this, ap.animation, nil, store.tick_ts, false)

				trigger_pound = false
				ap.ts = store.tick_ts

				S:queue(this.sound_events.skill)

				if SU.y_enemy_wait(store, this, ap.hit_time) then
					this.health.ignore_damage = false

					goto label_139_0
				end

				local af = this.render.sprites[1].flip_x
				local hit_pos = V.vclone(this.pos)

				if ap.hit_offset then
					hit_pos.x = hit_pos.x + (af and -1 or 1) * ap.hit_offset.x
					hit_pos.y = hit_pos.y + ap.hit_offset.y
				end

				local aura = E:create_entity(ap.aura)

				aura.aura.source_id = this.id
				aura.aura.ts = store.tick_ts
				aura.pos = V.vclone(this.pos)

				queue_insert(store, aura)
				deal_area_damage(hit_pos, ap)

				if ap.hit_fx then
					local fx = E:create_entity(ap.hit_fx)

					fx.pos = V.vclone(hit_pos)
					fx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, fx)
				end

				if ap.hit_decal then
					local fx = E:create_entity(ap.hit_decal)

					fx.pos = V.vclone(hit_pos)
					fx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, fx)
				end

				this.health.ignore_damage = false

				while not U.animation_finished(this, 1) and not SU.enemy_interrupted(this) do
					coroutine.yield()
				end
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, should_pound, should_pound) then
			-- block empty
			else
				coroutine.yield()
			end
		end
	end
end

scripts.enemy_frost_icecaller = {}

function scripts.enemy_frost_icecaller.update(this, store, script)
	local ai = this.timed_attacks.list[1]
	local target_pos, trigger_icicles

	local function find_soldiers_and_heroes(center, range)
		local targets = U.find_soldiers_in_range(store.entities, center, ai.min_range, range, ai.vis_flags, ai.vis_bans, function(v, o)
			return not v.pending_removal and (v.soldier or v.hero)
		end)

		if targets then
			table.sort(targets, function(e1, e2)
				return V.dist(e1.pos.x, e1.pos.y, this.pos.x, this.pos.y) < V.dist(e2.pos.x, e2.pos.y, this.pos.x, this.pos.y)
			end)
		end

		return targets
	end

	local function remove_val(t, w)
		for i, value in ipairs(t) do
			if w == value then
				table.remove(t, i)
			end
		end
	end

	local function icicles_attack()
		local distance = ai.icicle_row_spread

		local function spawn_icicle(pi, spi, ni)
			spi = spi or math.random(1, 3)

			local pos = P:node_pos(pi, spi, ni)

			pos.x = pos.x + math.random(-ai.icicle_spread, ai.icicle_spread)
			pos.y = pos.y + ai.icicles_y_offset + math.random(-ai.icicle_spread, ai.icicle_spread)

			local ic = E:create_entity(ai.icicle_t)

			ic.pos = pos

			if ic.pos.x < this.pos.x then
				ic.render.sprites[1].flip_x = true
			end

			ic.render.sprites[1].scale = V.vv(U.frandom(ai.scale_min, ai.scale_max))

			queue_insert(store, ic)
		end

		local function is_valid_path(k, pi)
			return (not store.level.ignore_walk_backwards_paths or not table.contains(store.level.ignore_walk_backwards_paths, pi)) and P:is_path_active(pi)
		end

		local available_paths = {}

		for k, value in pairs(P.paths) do
			table.insert(available_paths, k)
		end

		if store.level.ignore_walk_backwards_paths then
			available_paths = table.filter(available_paths, is_valid_path)
		end

		local pos = target_pos
		local direction = 1

		if pos then
			local ftni = P:nearest_nodes(pos.x, pos.y, {this.nav_path.pi})[1][3]

			if ftni < this.nav_path.ni then
				direction = -1
			end
		end

		local nearest = P:nearest_nodes(pos.x, pos.y, available_paths, nil, true)

		if #nearest > 0 then
			local pi, _, ni = unpack(nearest[1])

			ni = ni - direction * ai.icicles_row_anticipation

			S:queue(ai.sound_fall, {
				delay = ai.stalactite_fall_time
			})

			for nx = ni, ni + (ai.icicle_rows - 1) * distance * direction, distance * direction do
				if P:is_node_valid(pi, nx) then
					local order = {2, 1, 3}

					for i = 1, 3 - ai.icicles_per_row do
						local r = math.random(1, 3)

						remove_val(order, r)
					end

					for i = 1, ai.icicles_per_row do
						spawn_icicle(pi, order[i], nx)
						U.y_wait(store, ai.duration / (ai.icicle_rows * ai.icicles_per_row))
					end
				end
			end
		end
	end

	local function should_icicles()
		if not this.enemy.can_do_magic then
			return false
		end

		local targets = find_soldiers_and_heroes(this.pos, ai.range)

		if targets and targets[1] then
			target_pos = V.vclone(targets[1].pos)
		end

		trigger_icicles = targets and #targets > 0 and store.tick_ts - ai.ts > ai.cooldown and #this.enemy.blockers == 0

		return trigger_icicles
	end

	::label_146_0::

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if trigger_icicles then
				S:queue(ai.sound_channel)
				U.animation_start(this, ai.animation, target_pos.x < this.pos.x, store.tick_ts, false)

				trigger_icicles = false
				ai.ts = store.tick_ts

				if SU.y_enemy_wait(store, this, ai.cast_time) then
					goto label_146_0
				end

				icicles_attack()
				U.y_animation_wait(this)
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, should_icicles) then
			-- block empty
			else
				coroutine.yield()
			end
		end
	end
end

scripts.decal_frost_icecaller_icicle = {}

function scripts.decal_frost_icecaller_icicle.update(this, store)
	U.animation_start(this, this.anim_in, nil, store.tick_ts)
	U.y_wait(store, this.damage_delay)

	local targets = U.find_soldiers_in_range(store.entities, this.pos, 0, this.damage_radius, this.vis_flags, this.vis_bans, function(v, o)
		return not v.pending_removal and (v.soldier or v.hero)
	end)

	if targets then
		for _, enemy in pairs(targets) do
			local d = E:create_entity("damage")

			d.damage_type = this.damage_type
			d.value = U.frandom(this.damage_min, this.damage_max)
			d.source_id = this.id
			d.target_id = enemy.id

			queue_damage(store, d)
		end
	end

	U.animation_start(this, this.anim_loop, nil, store.tick_ts)
	U.y_wait(store, U.frandom(1, 2))
	U.y_animation_play(this, this.anim_out, nil, store.tick_ts)
	queue_remove(store, this)
end

scripts.mod_tower_stun = {}

function scripts.mod_tower_stun.insert(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.vis then
		log.error("ERROR: Tower cant be stunned because it doesnt contain a vis component. Ignoring.")

		return false
	end

	if band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	m.ts = store.tick_ts

	SU.tower_block_inc(target)

	this.pos = target.pos

	return true
end

function scripts.mod_tower_stun.update(this, store)
	local m = this.modifier

	while store.tick_ts - m.ts < m.duration do
		coroutine.yield()
	end

	queue_remove(store, this)
end

function scripts.mod_tower_stun.remove(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	SU.tower_block_dec(target)

	return true
end

scripts.mod_troll_crusher_tower_stun = {}

function scripts.mod_troll_crusher_tower_stun.insert(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	return true
end

function scripts.mod_troll_crusher_tower_stun.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]
	local source = store.entities[m.source_id]

	if not target then
		queue_remove(store, this)

		return
	end

	local t = this.max_delay * (V.dist(target.pos.x, target.pos.y, source.pos.x, source.pos.y) / this.max_range)

	U.y_wait(store, t)
	S:queue(this.sound_events.block)

	this.render.sprites[1].hidden = false

	U.animation_start(this, "start", nil, store.tick_ts)

	m.ts = store.tick_ts

	SU.tower_block_inc(target)

	local start_ts = store.tick_ts

	this.render.sprites[1].ts = store.tick_ts

	U.y_animation_wait(this)
	U.animation_start(this, "loop", nil, store.tick_ts)

	while store.tick_ts - start_ts < m.duration - this.end_anim_duration do
		coroutine.yield()
	end

	U.y_animation_play(this, "end", nil, store.tick_ts)
	queue_remove(store, this)
end

scripts.aura_utils = {}

function scripts.aura_utils.apply_area_damage(this, store, script)
	local enemies = U.find_targets_in_range(store.entities, this.pos, 0, this.aura.radius, this.aura.vis_flags, this.aura.vis_bans)

	if enemies then
		local ignore_dist_factor = this.aura.ignore_dist_factor or this.aura.chance_ignore_dist_factor and math.random() <= this.aura.chance_ignore_dist_factor

		for _, enemy in pairs(enemies) do
			local d = E:create_entity("damage")

			d.damage_type = this.aura.damage_type

			if this.aura.reduce_armor then
				d.reduce_armor = this.aura.reduce_armor
			end

			if ignore_dist_factor then
				d.value = this.aura.damage_max
			else
				local dist_factor = U.dist_factor_inside_ellipse(enemy.pos, this.pos, this.aura.radius)

				d.value = math.floor(this.aura.damage_max - (this.aura.damage_max - this.aura.damage_min) * dist_factor)
			end

			if this.aura.damage_factor then
				d.value = math.ceil(d.value * this.aura.damage_factor)
			end

			if (d.damage_type == DAMAGE_EXPLOSION or d.damage_type == DAMAGE_ELECTRICAL) and this.aura.explosive_factor then
				d.explosive_factor = this.aura.explosive_factor
			end

			d.source_id = this.id
			d.target_id = enemy.id

			queue_damage(store, d)

			if this.aura.mod or this.aura.mods then
				local mods = this.aura.mods or {this.aura.mod}

				if this.aura.mod and this.aura.mods then
					mods = table.merge(this.aura.mods, {this.aura.mod})
				end

				for _, mod_name in pairs(mods) do
					local m = E:create_entity(mod_name)

					m.modifier.target_id = enemy.id
					m.modifier.level = this.aura.level

					queue_insert(store, m)
				end
			end
		end
	end

	queue_remove(store, this)
end

scripts.aura_apply_mod_towers = {}

function scripts.aura_apply_mod_towers.update(this, store, script)
	local first_hit_ts
	local last_hit_ts = 0
	local cycles_count = 0
	local victims_count = 0
	local interrupted = false

	if this.aura.track_source and this.aura.source_id then
		local te = store.entities[this.aura.source_id]

		if te and te.pos then
			this.pos = te.pos
		end
	end

	last_hit_ts = store.tick_ts - this.aura.cycle_time

	if this.aura.apply_delay then
		last_hit_ts = last_hit_ts + this.aura.apply_delay
	end

	while true do
		if this.interrupt then
			last_hit_ts = 1e+99
			interrupted = true
		elseif interrupted then
			last_hit_ts = store.tick_ts
			interrupted = false
		end

		if this.aura.cycles and cycles_count >= this.aura.cycles or this.aura.duration >= 0 and store.tick_ts - this.aura.ts > this.actual_duration then
			break
		end

		if this.aura.stop_on_max_count and this.aura.max_count and victims_count >= this.aura.max_count then
			break
		end

		if this.aura.track_source and this.aura.source_id then
			local te = store.entities[this.aura.source_id]

			if not te or te.health and te.health.dead and not this.aura.track_dead then
				break
			end
		end

		if this.aura.requires_magic and this.aura.source_id then
			local te = store.entities[this.aura.source_id]

			if not te or not te.enemy then
				goto label_67_0
			end

			if this.render then
				this.render.sprites[1].hidden = not te.enemy.can_do_magic
			end

			if not te.enemy.can_do_magic then
				goto label_67_0
			end
		end

		if this.aura.source_vis_flags and this.aura.source_id then
			local te = store.entities[this.aura.source_id]

			if te and te.vis and band(te.vis.bans, this.aura.source_vis_flags) ~= 0 then
				goto label_67_0
			end
		end

		if this.aura.requires_alive_source and this.aura.source_id then
			local te = store.entities[this.aura.source_id]

			if te and te.health and te.health.dead then
				goto label_67_0
			end
		end

		if not (store.tick_ts - last_hit_ts >= this.aura.cycle_time) or this.aura.apply_duration and first_hit_ts and store.tick_ts - first_hit_ts > this.aura.apply_duration then
		-- block empty
		else
			if this.render and this.aura.cast_resets_sprite_id then
				this.render.sprites[this.aura.cast_resets_sprite_id].ts = store.tick_ts
			end

			first_hit_ts = first_hit_ts or store.tick_ts
			last_hit_ts = store.tick_ts
			cycles_count = cycles_count + 1

			local towers = U.find_towers_in_range(store.towers, this.pos, {
				max_range = this.aura.radius,
				min_range = 0
			}, function(v, o)
				return v.tower.type ~= "holder" and v.tower.type ~= "build_animation" and (not v.tower_holder or not v.tower_holder.blocked) and (not this.aura.allowed_templates or table.contains(this.aura.allowed_templates, v.template_name)) and (not this.aura.excluded_templates or not table.contains(this.aura.excluded_templates, v.template_name)) and (not this.aura.filter_source or this.aura.source_id ~= v.id)
			end)

			if towers then
				for i, target in ipairs(towers) do
					if this.aura.targets_per_cycle and i > this.aura.targets_per_cycle then
						break
					end

					if this.aura.max_count and victims_count >= this.aura.max_count then
						break
					end

					local mods = this.aura.mods or {this.aura.mod}

					for _, mod_name in pairs(mods) do
						local new_mod = E:create_entity(mod_name)

						new_mod.modifier.level = this.aura.level
						new_mod.modifier.target_id = target.id
						new_mod.modifier.source_id = this.id

						if this.aura.hide_source_fx and target.id == this.aura.source_id then
							new_mod.render = nil
						end

						queue_insert(store, new_mod)
					end

					victims_count = victims_count + 1
				end
			end
		end

		::label_67_0::

		coroutine.yield()
	end

	signal.emit("aura-apply-mod-towers-victims", this, victims_count)
	queue_remove(store, this)
end

function scripts.tween_utils.wait_update(this, store, script)
	if this.wait_time then
		U.y_wait(store, this.wait_time)
	else
		this.render.sprites[1].ts = store.tick_ts

		U.y_animation_wait(this, 1, 1)
	end

	queue_remove(store, this)
end

-- ==================== KR6 stage 10-13：共享敌人 / 战斗子实体脚本 ====================
-- 移植自 kr6/scripts_game.lua（deep_trolls / spiders 及其投射物、aura、mod、decal）。
-- 换算约定：queue_insert/queue_remove -> simulation:queue_*_entity；
--   vis.flags/bans 直写 -> U.flags_add/bans_add 引用计数接口；
--   health_bar.z 直写 -> U.change_health_bar_z_run_time。

local function kr6_find_all_t(store, template_name, contains, fn)
	if not store or not store.entities then
		return {}
	end

	return table.filter(store.entities, function(k, val)
		return (contains and string.find(val.template_name, template_name) or val.template_name == template_name) and (not fn or fn(k, val))
	end)
end

local function kr6_any(list, fn)
	for i = 1, #list do
		if fn(list[i]) then
			return true
		end
	end

	return false
end

scripts.mod_movement_terrain = {}

function scripts.mod_movement_terrain.remove(this, store)
	if not this._mods then
		return true
	end

	for _, m in ipairs(this._mods) do
		if store.entities[m.id] then
			simulation:queue_remove_entity(m)
		end
	end

	this._mods = nil

	return true
end

function scripts.mod_movement_terrain.update(this, store)
	if not this.terrain then
		log.error("Mod movement terrain for target" .. tostring(this.modifier.target_id) .. " has no terrain setup. Removing.")
		simulation:queue_remove_entity(this)

		return
	end

	local target = store.entities[this.modifier.target_id]
	local on_auras = false
	local last_terrain = GR:cell_type(target.pos.x, target.pos.y)
	local last_aura_check_ts = store.tick_ts

	this.on_terrain = GR:cell_is(target.pos.x, target.pos.y, this.terrain)

	local function check_walking_on_auras()
		if this.auras_to_consider_terrain and store.tick_ts - last_aura_check_ts > 0.25 then
			last_aura_check_ts = store.tick_ts

			for i, aura_t in ipairs(this.auras_to_consider_terrain) do
				local existing_auras = kr6_find_all_t(store, aura_t)

				for i, aura in ipairs(existing_auras) do
					if U.is_inside_ellipse(target.pos, aura.pos, aura.aura.radius) then
						on_auras = true

						return true
					end
				end
			end

			on_auras = false
		end

		return false
	end

	local function check_on_terrain()
		return GR:cell_is(target.pos.x, target.pos.y, this.terrain) or on_auras
	end

	local function get_terrain()
		if on_auras then
			return this.terrain
		end

		return GR:cell_type(target.pos.x, target.pos.y)
	end

	local function changed_terrain()
		local t = get_terrain()
		local last_terrain_is_target = band(last_terrain, this.terrain) ~= 0

		return not last_terrain_is_target and band(t, this.terrain) ~= 0 or last_terrain_is_target and band(t, this.terrain) == 0
	end

	local function instance_mods()
		if not this.mods then
			log.error("ERROR: Mod %s:%s has no mods to instantiate.", this.id, this.template_name)

			return
		end

		local mods = {}

		for _, mt in ipairs(this.mods) do
			local m = E:create_entity(mt)

			m.modifier.target_id = this.modifier.target_id
			m.modifier.source_id = this.modifier.target_id
			m.modifier.duration = 1e+99

			simulation:queue_insert_entity(m)
			table.insert(mods, m)
		end

		this._mods = mods
	end

	while true do
		if not store.entities[this.modifier.target_id] or store.entities[this.modifier.target_id].health and store.entities[this.modifier.target_id].health.dead then
			simulation:queue_remove_entity(this)

			return
		end

		check_walking_on_auras()

		this.on_terrain = check_on_terrain()

		if this.on_terrain and changed_terrain() then
			if this.add_vis_bans and not this._bans_added then
				U.bans_add(target.vis, this.add_vis_bans)
				this._bans_added = true
			end

			if this.add_vis_flags then
				U.flags_add(target.vis, this.add_vis_flags)
			end

			instance_mods()

			if this.on_entered_terrain_fn then
				this.on_entered_terrain_fn()
			end
		end

		if not this.on_terrain and changed_terrain() then
			if this._bans_added then
				U.bans_remove(target.vis, this.add_vis_bans)
				this._bans_added = nil
			end

			if this.add_vis_flags then
				U.flags_remove(target.vis, this.add_vis_flags)
			end

			scripts.mod_movement_terrain.remove(this, store)

			if this.on_left_terrain_fn then
				this.on_left_terrain_fn()
			end
		end

		last_terrain = get_terrain()

		coroutine.yield()
	end
end

scripts.enemy_troll_warrior_landing = {}

function scripts.enemy_troll_warrior_landing.update(this, store)
	U.y_animation_wait(this, 1)
	scripts.enemy_mixed_cliff.update(this, store)
end

scripts.enemy_troll_warrior_stage_213_suicide_glider = {}

function scripts.enemy_troll_warrior_stage_213_suicide_glider.insert(this, store)
	local np = this.nav_path
	local banned_paths = {np.pi, 7, 8, 9, 10, 11, 12}
	local paths = {}

	for i = 1, #P.paths do
		if not table.contains(banned_paths, i) then
			table.insert(paths, i)
		end
	end

	local subpaths = {1, 2, 3}
	local nn = P:nearest_nodes(this.pos.x, this.pos.y, paths, subpaths)

	np.pi = nn[1][1]
	np.spi = nn[1][2]
	np.ni = nn[1][3]

	return scripts.enemy_basic.insert(this, store)
end

scripts.enemy_troll_glider_stage_213_suicide = {}

function scripts.enemy_troll_glider_stage_213_suicide.update(this, store)
	local sunray = kr6_find_all_t(store, this.sunray_t)[1]
	local shadow_sprite = this.render.sprites[2]
	local is_suicide = true
	local old_death_spawn = this.death_spawns.name
	local old_z = this.render.sprites[1].z
	local np = this.nav_path
	local is_left = this.nav_path.pi == this.left_path

	while true do
		if this.health.dead then
			if band(this.health.last_damage_types, bor(DAMAGE_INSTAKILL)) ~= 0 then
				simulation:queue_remove_entity(this)

				return
			end

			S:queue(this.sound_events.death, this.sound_events.death_args)

			if band(this.health.last_damage_types, bor(DAMAGE_DISINTEGRATE)) == 0 and this.unit.can_disintegrate then
				local fx = E:create_entity(this.death_fx)

				fx.pos = V.vclone(this.pos)
				fx.pos.x, fx.pos.y = fx.pos.x + this.death_fx_offset.x, fx.pos.y + this.death_fx_offset.y
				fx.render.sprites[1].ts = store.tick_ts
				fx.render.sprites[1].flip_x = this.render.sprites[1].flip_x

				simulation:queue_insert_entity(fx)
			end

			if GR:cell_is(this.pos.x, this.pos.y, bor(TERRAIN_LAND, TERRAIN_ICE)) and not GR:cell_is(this.pos.x, this.pos.y, bor(TERRAIN_NOWALK)) then
				U.animation_start(this, "fall_loop", nil, store.tick_ts)

				local dt = fts(1)

				while this.render.sprites[1].offset.y > 0 do
					this.render.sprites[1].offset.y = this.render.sprites[1].offset.y - this.fall_speed * dt

					coroutine.yield()
				end

				if shadow_sprite then
					shadow_sprite.hidden = true
				end

				U.y_animation_play(this, "drop", nil, store.tick_ts, 1, 1)
				SU.y_enemy_death(store, this)
				simulation:queue_remove_entity(this)

				return
			else
				simulation:queue_remove_entity(this)

				return
			end
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			SU.y_enemy_walk_until_blocked(store, this, true, function()
				if np.ni > this.node_to_consider_too_far and this.render.sprites[1].z == old_z then
					this.render.sprites[1].z = Z_OBJECTS
					U.change_health_bar_z_run_time(this.health_bar, Z_OBJECTS)

					if this.render.sprites[2] then
						this.render.sprites[2].z = Z_OBJECTS
					end
				end

				if np.ni < this.node_to_consider_too_far and this.render.sprites[1].z == Z_OBJECTS then
					this.render.sprites[1].z = old_z
					U.change_health_bar_z_run_time(this.health_bar, old_z)

					if this.render.sprites[2] then
						this.render.sprites[2].z = old_z
					end
				end

				if is_suicide and not sunray.has_sorcerers(is_left) then
					is_suicide = false

					local banned_paths = {np.pi, 9, 10, 11, 12}
					local paths = {}

					for i = 1, #P.paths do
						if not table.contains(banned_paths, i) then
							table.insert(paths, i)
						end
					end

					local subpaths = {1, 2, 3}
					local nn = P:nearest_nodes(this.pos.x, this.pos.y, paths, subpaths)

					np.pi = nn[1][1]
					np.spi = nn[1][2]
					np.ni = nn[1][3]
					this.death_spawns.name = this.fallback_death_spawn_name
				end

				if not is_suicide and sunray.has_sorcerers(is_left) and np.ni < this.node_to_consider_too_far then
					is_suicide = true

					local paths = {7, 8}
					local subpaths = {1, 2, 3}
					local nn = P:nearest_nodes(this.pos.x, this.pos.y, paths, subpaths)

					np.pi = nn[1][1]
					np.spi = nn[1][2]
					np.ni = nn[1][3]
					this.death_spawns.name = old_death_spawn
				end

				if is_suicide and sunray.has_sorcerers(is_left) then
					local sorc_id, sorc_position = sunray.get_sorcerer_position(is_left)

					if sorc_id and sorc_position and V.dist2(this.pos.x, this.pos.y, sorc_position.x, sorc_position.y) <= math.pow(this.trigger_distance, 2) then
						U.bans_add(this.vis, F_ALL)
						this.health_bar.hidden = true

						if shadow_sprite then
							shadow_sprite.hidden = true
						end

						S:queue(this.sound_events.suicide)
						U.y_animation_play(this, this.anim_suicide, nil, store.tick_ts, 1, 1)

						local sorc = sunray.get_sorcerer(sorc_id)
						local n_sorc_id, n_sorc_position = sorc_id, sorc_position

						if not sorc then
							n_sorc_id, n_sorc_position = sunray.get_sorcerer_position(is_left)

							if n_sorc_id and n_sorc_position then
								sorc = sunray.get_sorcerer(n_sorc_id)
							end
						end

						n_sorc_position = n_sorc_position or sorc_position

						local suicide_bomb = E:create_entity(this.bullet)

						suicide_bomb.pos = V.v(this.pos.x + this.bullet_spawn_offset.x * (this.render.sprites[1].flip_x and -1 or 1), this.pos.y + this.bullet_spawn_offset.y)
						suicide_bomb.bullet.from = V.vclone(suicide_bomb.pos)
						suicide_bomb.bullet.to = n_sorc_position
						suicide_bomb.bullet.target_id = sorc and sorc.id or nil
						suicide_bomb.render.sprites[1].flip_x = this.render.sprites[1].flip_x
						suicide_bomb.render.sprites[1].r = V.angleTo(suicide_bomb.bullet.to.x - suicide_bomb.bullet.from.x, suicide_bomb.bullet.to.y - suicide_bomb.bullet.from.y)

						simulation:queue_insert_entity(suicide_bomb)
						coroutine.yield()

						this.render.sprites[1].hidden = true

						simulation:queue_remove_entity(this)

						return
					end
				end
			end)
			coroutine.yield()
		end
	end
end

scripts.bullet_troll_glider_stage_213_suicide = {}

function scripts.bullet_troll_glider_stage_213_suicide.update(this, store, script)
	local b = this.bullet
	local ease_tables = {this.pos, this.pos}
	local ease_keys = {"x", "y"}
	local froms = {b.from.x, b.from.y}
	local tos = {b.to.x, b.to.y}
	local last_pos = V.vclone(this.pos)

	this.render.sprites[1].r = V.angleTo(b.to.x - b.from.x, b.to.y - b.from.y)

	U.y_ease_keys(store, ease_tables, ease_keys, froms, tos, b.flight_time, "quad-in", function(dt, p)
		if b.align_with_trajectory then
			if this.render.sprites[1].flip_x then
				this.render.sprites[1].r = V.angleTo(last_pos.x - this.pos.x, last_pos.y - this.pos.y)
			else
				this.render.sprites[1].r = V.angleTo(this.pos.x - last_pos.x, this.pos.y - last_pos.y)
			end

			last_pos.x, last_pos.y = this.pos.x, this.pos.y
		end
	end)

	local hfx = E:create_entity(b.hit_fx)

	hfx.pos.x, hfx.pos.y = this.pos.x, this.pos.y
	hfx.render.sprites[1].ts = store.tick_ts
	hfx.render.sprites[1].flip_x = this.render.sprites[1].flip_x

	simulation:queue_insert_entity(hfx)
	S:queue(this.sound_events.hit)

	local target = store.entities[b.target_id]

	if target then
		local d = E:create_entity("damage")

		d.source_id = this.id
		d.target_id = b.target_id
		d.value = math.random(b.damage_min, b.damage_max)
		d.damage_type = b.damage_type
		d.pop = b.pop
		d.pop_conds = b.pop_conds

		queue_damage(store, d)
	end

	simulation:queue_remove_entity(this)
end

scripts.enemy_troll_pathfinder = {}

function scripts.enemy_troll_pathfinder.insert(this, store, script)
	if type(this.on_ice_mod) ~= "string" then
		this.on_ice_mod = E:get_template(this.template_name).on_ice_mod
	end

	this.on_ice_mod = E:create_entity(this.on_ice_mod)
	this.on_ice_mod.modifier.target_id = this.id

	simulation:queue_insert_entity(this.on_ice_mod)

	return scripts.enemy_basic.insert(this, store, script)
end

function scripts.enemy_troll_pathfinder.update(this, store, script)
	local old_angles = this.render.sprites[1].angles.walk

	local function got_on_ice()
		this.render.sprites[1].angles.walk = this.render.sprites[1].angles.slide

		if this.enemy.blockers and #this.enemy.blockers > 0 then
			U.unblock_all(store, this)
		end
	end

	local function left_ice()
		this.render.sprites[1].angles.walk = old_angles

		if this.enemy.blockers and #this.enemy.blockers > 0 then
			U.unblock_all(store, this)
		end
	end

	this.on_ice_mod.on_entered_terrain_fn = got_on_ice
	this.on_ice_mod.on_left_terrain_fn = left_ice

	while true do
		if this.health.dead then
			if this.on_ice_mod.on_terrain then
				this.unit.hide_during_death = true
				this.unit.death_animation = nil
				this.death_spawns.concurrent_with_death = true
				this.death_spawns.quantity = 1

				signal.emit("trolls-on-ice")
			end

			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			SU.y_enemy_mixed_walk_melee_ranged(store, this)
		end

		coroutine.yield()
	end
end

scripts.decal_troll_pathfinder_dead_sliding = {}

function scripts.decal_troll_pathfinder_dead_sliding.update(this, store, script)
	local arrived = false
	local s = P:node_pos(this.nav_path.pi, this.nav_path.spi, this.nav_path.ni)
	local f = P:node_pos(this.nav_path.pi, this.nav_path.spi, this.nav_path.ni + 2)
	local dir = V.v(f.x - s.x, f.y - s.y)
	local ndirx, ndiry = V.normalize(dir.x, dir.y)
	local t = -this.motion.max_speed / this.motion.accel
	local fposx = this.pos.x + ndirx * this.motion.max_speed * t + ndirx * this.motion.accel / 2 * t * t
	local fposy = this.pos.y + ndiry * this.motion.max_speed * t + ndiry * this.motion.accel / 2 * t * t
	local dt = store.tick_length

	this.render.sprites[1].ts = store.tick_ts
	this.motion.dest = V.v(fposx, fposy)
	this.motion.arrived = false

	if this.sound_in then
		S:queue(this.sound_in)
	end

	while not arrived do
		-- KR6 的 U.walk 在 motion.speed_limit 存在时会自动按 motion.accel 递减 max_speed；
		-- dove 的 U.walk 需显式传 accel 才会走 U.speed_inc_self（同样是改 max_speed）。
		-- 这里传入 motion.accel 复刻减速，并以 max_speed 归零作为终止条件，避免负数溢出后卡住。
		U.walk(this, dt, this.motion.accel)

		arrived = this.motion.max_speed <= 0

		coroutine.yield()
	end

	U.y_wait(store, this.wait_time_after_stop)
	simulation:queue_remove_entity(this)
end

scripts.enemy_troll_chieftain_kr6 = {}

function scripts.enemy_troll_chieftain_kr6.update(this, store, script)
	local ad = this.timed_attacks.list[1]
	local drum_check_ts = store.tick_ts
	local trigger_drums

	local function can_drums()
		if not this.enemy.can_do_magic then
			return false
		end

		if trigger_drums then
			return true
		end

		if store.tick_ts - drum_check_ts < 0.25 then
			return false
		end

		if store.tick_ts - ad.ts < ad.cooldown then
			return false
		end

		drum_check_ts = store.tick_ts

		local targets = U.find_enemies_in_range(store, this.pos, 0, ad.range, ad.vis_flags, 0)

		trigger_drums = targets and #targets >= ad.min_targets

		return trigger_drums
	end

	::label_185_0::

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if trigger_drums then
				S:queue(ad.sound, {
					delay = fts(10)
				})
				U.animation_start(this, ad.animation, nil, store.tick_ts, false)

				trigger_drums = false
				ad.ts = store.tick_ts

				if SU.y_enemy_wait(store, this, ad.aura_time) then
					goto label_185_0
				end

				local aura_d = E:create_entity(ad.aura_decal)

				aura_d.pos.x, aura_d.pos.y = this.pos.x, this.pos.y
				aura_d.render.sprites[1].ts = store.tick_ts

				queue_insert(store, aura_d)

				local aura = E:create_entity(ad.aura)

				aura.pos.x, aura.pos.y = this.pos.x, this.pos.y
				aura.aura.source_id = this.id
				aura.aura.ts = store.tick_ts

				queue_insert(store, aura)
				U.y_animation_wait(this)
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, can_drums, can_drums) then
			-- block empty
			else
				coroutine.yield()
			end
		end
	end
end

scripts.mod_troll_chieftain_drums_buff = {}

function scripts.mod_troll_chieftain_drums_buff.insert(this, store, script)
	local i_damage = scripts.mod_damage_factors.insert(this, store, script)
	local i_speed = scripts.mod_slow.insert(this, store, script)

	if not i_damage or not i_speed then
		if not i_damage then
			scripts.mod_damage_factors.remove(this, store, script)
		end

		if not i_speed then
			scripts.mod_slow.remove(this, store, script)
		end

		return false
	end

	return true
end

function scripts.mod_troll_chieftain_drums_buff.update(this, store, script)
	local m = this.modifier

	this.modifier.ts = store.tick_ts

	local target = store.entities[m.target_id]

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos
	this.tween.ts = store.tick_ts

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or m.duration >= 0 and store.tick_ts - m.ts > m.duration or m.last_node and target.nav_path.ni > m.last_node then
			this.tween.ts = store.tick_ts

			queue_remove(store, this)

			return
		end

		if this.render and target.unit then
			local s = this.render.sprites[1]
			local flip_sign = 1

			if target.render then
				flip_sign = target.render.sprites[1].flip_x and -1 or 1
			end

			if m.health_bar_offset and target.health_bar then
				local hb = target.health_bar.offset
				local hbo = m.health_bar_offset

				s.offset.x, s.offset.y = hb.x + hbo.x * flip_sign, hb.y + hbo.y
			elseif m.use_mod_offset and target.unit.mod_offset then
				s.offset.x, s.offset.y = target.unit.mod_offset.x * flip_sign, target.unit.mod_offset.y
			end
		end

		coroutine.yield()
	end
end

function scripts.mod_troll_chieftain_drums_buff.remove(this, store, script)
	if not this.tween.disabled then
		scripts.mod_damage_factors.remove(this, store, script)
		scripts.mod_slow.remove(this, store, script)
	end

	return scripts.tween_utils.reverse_remove(this, store, script)
end

scripts.enemy_frost_baiter = {}

function scripts.enemy_frost_baiter.insert(this, store, script)
	if type(this.on_ice_mod) ~= "string" then
		this.on_ice_mod = E:get_template(this.template_name).on_ice_mod
	end

	this.on_ice_mod = E:create_entity(this.on_ice_mod)
	this.on_ice_mod.modifier.target_id = this.id

	simulation:queue_insert_entity(this.on_ice_mod)

	return scripts.enemy_basic.insert(this, store, script)
end

function scripts.enemy_frost_baiter.y_jump(this, store, dest, break_fn)
	this._flying = true

	local b = this.bullet

	b.from = V.vclone(this.pos)
	b.to = dest
	b.ts = store.tick_ts
	b.last_pos = V.vclone(this.pos)
	this.bullet.speed = SU.initial_parabola_speed(b.from, b.to, b.flight_time, b.g)

	local max_height = 90

	while store.tick_ts - b.ts + store.tick_length < b.flight_time do
		coroutine.yield()

		b.last_pos.x, b.last_pos.y = this.pos.x, this.pos.y
		this.pos.x, this.pos.y = SU.position_in_parabola(store.tick_ts - b.ts, b.from, b.speed, b.g)

		local t = (store.tick_ts - b.ts) / b.flight_time
		local coly = b.from.y + (b.to.y - b.from.y) * t

		this.render.sprites[2].offset.y = coly - this.pos.y

		local height = this.pos.y - coly
		local scale = km.clamp(0.5, 1, (max_height - height) / max_height)

		this.render.sprites[2].scale = V.vv(scale)

		if b.align_with_trajectory then
			this.render.sprites[1].r = V.angleTo(this.pos.x - b.last_pos.x, this.pos.y - b.last_pos.y)
		elseif b.rotation_speed then
			this.render.sprites[1].r = this.render.sprites[1].r + b.rotation_speed * store.tick_length
		end

		if b.hide_radius then
			this.render.sprites[1].hidden = V.dist(this.pos.x, this.pos.y, b.from.x, b.from.y) < b.hide_radius or V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) < b.hide_radius
		end

		if break_fn and break_fn() then
			break
		end
	end

	this._flying = false
end

function scripts.enemy_frost_baiter.update(this, store, script)
	local cont, blocker
	local bait_ts = store.tick_ts - this.bait_cooldown

	this.render.sprites[2].hidden = true

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			cont, blocker = SU.y_enemy_walk_until_blocked(store, this, false)

			if not cont then
			-- block empty
			elseif not blocker or not SU.y_wait_for_blocker(store, this, blocker) then
			-- block empty
			else
				while SU.can_melee_blocker(store, this, blocker) do
					local np = this.nav_path
					local nodes_to_end = P:nodes_to_goal(np.pi, np.spi, np.ni)

					if this.enemy.can_do_magic and store.tick_ts - bait_ts > this.bait_cooldown and nodes_to_end > this.bait_max_nodes_to_exit then
						bait_ts = store.tick_ts

						local bait = E:create_entity(this.decoy_t)

						bait.pos = V.vclone(this.pos)
						bait.render.sprites[1].flip_x = this.render.sprites[1].flip_x
						bait.heading.angle = this.render.sprites[1].flip_x and math.pi / 2 or 0

						simulation:queue_insert_entity(bait)

						for i, v in ipairs(this.enemy.blockers) do
							local blocker = store.entities[v]

							U.unblock_target(store, blocker)
							U.block_enemy(store, blocker, bait)
						end

						local np = this.nav_path
						local nodes_ahead = math.random(this.min_jump_distance, this.max_jump_distance)
						local water_check_distance = (nodes_ahead + this.node_water_tolerance) * P.average_node_dist
						local fwd_entrances = table.filter(store.entities, function(k, v)
							local is_and_near = v.template_name == "decal_stage_210_well" and U.is_inside_ellipse(v.pos, this.pos, water_check_distance)

							if not is_and_near then
								return false
							end

							if v.paths and not table.contains(v.paths, np.pi) then
								return false
							end

							local nearest_node = P:nearest_nodes(v.pos.x, v.pos.y, {np.pi}, {np.spi}, true)[1]

							return nearest_node[3] > np.ni
						end)
						local going_to_puddle = fwd_entrances and #fwd_entrances > 0
						local dest = going_to_puddle and V.vclone(fwd_entrances[1].pos) or P:node_pos(np.pi, np.spi, np.ni + nodes_ahead)

						S:queue(this.sound_events.jump)
						U.animation_start(this, "jumpball", nil, store.tick_ts, true)

						this.render.sprites[2].hidden = false
						U.bans_add(this.vis, F_BLOCK)
						this.render.sprites[1].z = Z_BULLETS

						scripts.enemy_frost_baiter.y_jump(this, store, dest)

						this.render.sprites[1].z = Z_OBJECTS

						if not this._passed_entrance then
							U.bans_remove(this.vis, F_BLOCK)
						end

						this.render.sprites[2].hidden = true
						np.ni = np.ni + nodes_ahead

						break
					end

					if not SU.y_enemy_melee_attacks(store, this, blocker) then
						break
					end

					coroutine.yield()
				end
			end
		end

		coroutine.yield()
	end
end

scripts.enemy_frost_baiter_decoy = {}

function scripts.enemy_frost_baiter_decoy.insert(this, store, script)
	local spr = math.random(1, 8)

	this.render.sprites[1].name = this.render.sprites[1].prefix .. "_" .. string.format("%04i", spr)

	local fx = E:create_entity(this.death_spawns.fx)

	fx.pos = this.pos
	fx.render.sprites[1].ts = store.tick_ts

	simulation:queue_insert_entity(fx)

	return true
end

function scripts.enemy_frost_baiter_decoy.update(this, store, script)
	local ts = store.tick_ts

	while true do
		if this.health.dead or store.tick_ts - ts > this.duration then
			S:queue(this.sound_events.death, this.sound_events.death_args)
			SU.y_enemy_death(store, this)
			simulation:queue_remove_entity(this)

			return
		end

		coroutine.yield()
	end
end

scripts.enemy_frost_baiter_jumper = {}

function scripts.enemy_frost_baiter_jumper.update(this, store, script)
	local walk = true
	local jump_i = 1
	local dest = P:node_pos(this.nav_path.pi, this.nav_path.spi, this.jump_points[jump_i][1])
	local shadow_sprite = this.render.sprites[2]
	local shadow_tween = this.tween

	local function is_in_gap(pos, gap)
		local start = P:node_pos(this.nav_path.pi, this.nav_path.spi, gap[1])
		local finish = P:node_pos(this.nav_path.pi, this.nav_path.spi, gap[2])
		local dirx = finish.x - start.x
		local diry = finish.y - start.y
		local tx = (pos.x - start.x) / dirx
		local ty = (pos.y - start.y) / diry

		return math.max(tx, ty) < 1
	end

	local function should_hide_shadow_in_flight()
		return this.disappearing_shadows and (this.jump_points[jump_i][3] or not this.jump_points[jump_i][4] or is_in_gap(this.pos, this.jump_points[jump_i][4])) or false
	end

	U.flags_add(this.vis, F_BLOCK)

	U.set_destination(this, dest)

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if walk and this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		elseif walk then
			local an, af = U.animation_name_facing_point(this, "walk", this.motion.dest)

			U.animation_start(this, an, af, store.tick_ts, true)

			local reached_dest = U.walk(this, store.tick_length)

			walk = not reached_dest

			if not walk then
				dest = P:node_pos(this.nav_path.pi, this.nav_path.spi, this.jump_points[jump_i][2])

				S:queue(this.sound_events.jump)
				U.animation_start(this, "jumpball", nil, store.tick_ts, true)

				shadow_sprite.hidden = false
				U.bans_add(this.vis, bor(F_FLYING, F_STUN))
				this.render.sprites[1].z = Z_BULLETS

				scripts.enemy_frost_baiter.y_jump(this, store, dest, function()
					if shadow_tween.disabled and shadow_sprite.alpha == 255 and should_hide_shadow_in_flight() then
						shadow_tween.reverse = false
						shadow_tween.disabled = false
						shadow_tween.ts = store.tick_ts
					end

					if shadow_tween.disabled and shadow_sprite.alpha == 0 and not should_hide_shadow_in_flight() then
						shadow_tween.reverse = true
						shadow_tween.disabled = false
						shadow_tween.ts = store.tick_ts
					end

					return false
				end)

				this.render.sprites[1].z = Z_OBJECTS
				U.bans_remove(this.vis, bor(F_FLYING, F_STUN))
				shadow_sprite.hidden = true
				shadow_tween.reverse = true
				shadow_tween.disabled = false
				shadow_tween.ts = store.tick_ts
				jump_i = jump_i + 1

				if jump_i > #this.jump_points then
					break
				end

				dest = P:node_pos(this.nav_path.pi, this.nav_path.spi, this.jump_points[jump_i][1])

				U.set_destination(this, dest)

				walk = true
			end
		end

		coroutine.yield()
	end

	U.flags_remove(this.vis, F_BLOCK)
	this.nav_path.ni = P:nearest_nodes(this.pos.x, this.pos.y, {this.nav_path.pi})[1][3]

	local next = P:next_entity_node(this, store.tick_length)

	if not next then
		log.debug("(%s) %s has no valid next node", this.id, this.template_name)

		return false
	end

	U.set_destination(this, next)
	U.set_heading(this, next)
	scripts.enemy_frost_baiter.update(this, store, script)
end

scripts.enemy_frost_brute = {}

function scripts.enemy_frost_brute.insert(this, store, script)
	if type(this.on_ice_mod) ~= "string" then
		this.on_ice_mod = E:get_template(this.template_name).on_ice_mod
	end

	this.on_ice_mod = E:create_entity(this.on_ice_mod)
	this.on_ice_mod.modifier.target_id = this.id

	simulation:queue_insert_entity(this.on_ice_mod)

	return scripts.enemy_basic.insert(this, store, script)
end

function scripts.enemy_frost_brute.update(this, store, script)
	local acb = this.timed_attacks.list[1]

	acb.ts = store.tick_ts

	local breath_check_ts = store.tick_ts
	local trigger_breath, cont, blocker
	local armored = true
	local saved_armor, breath_target_pos, aux_target_pos

	local function is_behind(target)
		local af = this.render.sprites[1].flip_x
		local dir_x = af and -1 or 1
		local dir_y = 0
		local t_dir_x, t_dir_y = V.normalize(target.pos.x - this.pos.x, target.pos.y - this.pos.y)

		return V.dot(dir_x, dir_y, t_dir_x, t_dir_y) < 0
	end

	local function get_closest_soldiers()
		local aura_t = E:get_template(acb.aura)
		local soldiers = U.find_soldiers_in_range(store.entities, this.pos, 0, acb.trigger_radius, acb.vis_flags, acb.vis_bans, function(v, o)
			return v.pos.y < this.pos.y + acb.ignore_offset_y and not is_behind(v) and not v.unit.ignore_stun and not v.unit.is_stunned and (not aura_t.aura.allowed_templates or table.contains(aura_t.aura.allowed_templates, v.template_name)) and (not aura_t.aura.excluded_templates or not table.contains(aura_t.aura.excluded_templates, v.template_name))
		end)

		if not soldiers then
			return nil
		end

		table.sort(soldiers, function(s1, s2)
			return V.dist2(s1.pos.x, s1.pos.y, this.pos.x, this.pos.y) < V.dist2(s2.pos.x, s2.pos.y, this.pos.x, this.pos.y)
		end)

		return soldiers
	end

	local function should_breath(aura_t)
		if trigger_breath then
			return true
		end

		if store.tick_ts - breath_check_ts < 0.25 then
			return false
		end

		if store.tick_ts - acb.ts < acb.cooldown then
			return false
		end

		breath_check_ts = store.tick_ts

		local soldiers = get_closest_soldiers()

		trigger_breath = soldiers and #soldiers > acb.min_targets

		if trigger_breath then
			breath_target_pos = soldiers[1].pos
			aux_target_pos = V.vclone(breath_target_pos)
		end

		return trigger_breath
	end

	local function y_disarm_armor()
		if not armored then
			return
		end

		armored = false

		U.y_animation_play(this, this.animation_start_combat, nil, store.tick_ts, 1)

		saved_armor = this.health.armor

		SU.armor_dec(this, saved_armor)
	end

	local function y_rearm_armor()
		if armored then
			return
		end

		this.render.sprites[1].prefix = "frost_brute_creep"
		armored = true

		U.y_animation_play(this, this.animation_end_combat, nil, store.tick_ts, 1)
		SU.armor_inc(this, saved_armor)
	end

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if trigger_breath then
				y_rearm_armor()
				U.animation_start(this, acb.animation, nil, store.tick_ts, false)

				trigger_breath = false
				acb.ts = store.tick_ts

				if SU.y_enemy_wait(store, this, acb.aura_time) then
					goto label_176_1
				end

				if not breath_target_pos then
					local soldiers = get_closest_soldiers()

					if #soldiers > 0 then
						breath_target_pos = soldiers[1].pos
					else
						breath_target_pos = aux_target_pos
					end
				end

				local af = this.render.sprites[1].flip_x
				local dirx, diry = V.normalize(breath_target_pos.x - this.pos.x, breath_target_pos.y - this.pos.y)
				local aura = E:create_entity(acb.aura)

				aura.aura.source_id = this.id
				aura.aura.ts = store.tick_ts

				local a_offset_x, a_offset_y = V.mul(aura.aura.radius / 2, dirx, diry)

				aura.pos.x, aura.pos.y = this.pos.x + a_offset_x, this.pos.y + a_offset_y

				simulation:queue_insert_entity(aura)
				S:queue(acb.sound)

				local fx = E:create_entity(acb.fx)

				fx.render.sprites[1].flip_x = af
				fx.render.sprites[1].ts = store.tick_ts
				fx.pos = V.v(this.pos.x + (af and -1 or 1) * acb.offset.x, this.pos.y + acb.offset.y)

				local angle = V.angleTo(breath_target_pos.x - this.pos.x, breath_target_pos.y - this.pos.y)

				if af then
					fx.render.sprites[1].r = angle + math.pi
				else
					fx.render.sprites[1].r = angle
				end

				simulation:queue_insert_entity(fx)
				U.y_animation_wait(this)
			end

			if not trigger_breath then
				y_rearm_armor()
			end

			::label_176_0::

			cont, blocker = SU.y_enemy_walk_until_blocked(store, this, false, should_breath)

			if not cont then
			-- block empty
			else
				if blocker then
					if not SU.y_wait_for_blocker(store, this, blocker) then
						goto label_176_1
					end

					local had_several = #this.enemy.blockers > 1

					while SU.can_melee_blocker(store, this, blocker) do
						if should_breath() then
							goto label_176_1
						end

						y_disarm_armor()

						this.render.sprites[1].prefix = "frost_brute_creep_combat"

						if not SU.y_enemy_melee_attacks(store, this, blocker) then
							goto label_176_1
						end

						coroutine.yield()
					end

					if #this.enemy.blockers > 0 and had_several and kr6_any(this.enemy.blockers, function(id)
						local e = store.entities[id]

						return e and not e.pending_removal and not e.health.dead
					end) then
						coroutine.yield()

						goto label_176_0
					end

					y_rearm_armor()
				else
					this.render.sprites[1].prefix = "frost_brute_creep"
				end

				coroutine.yield()
			end
		end

		::label_176_1::

		this.render.sprites[1].prefix = "frost_brute_creep"
	end
end

scripts.enemy_stage_11_spider = {}

