scripts.enemy_leaper_spider = {}

function scripts.enemy_leaper_spider.update(this, store, script)
	local al = this.timed_attacks.list[1]
	local leap_check_ts = store.tick_ts

	al.ts = store.tick_ts

	local trigger_leap, leap_target

	local function soldier_is_within_path(v, p)
		local nodes = P:nearest_nodes(v.pos.x, v.pos.y, {p})

		for _, n in pairs(nodes) do
			local pi, spi, ni, dist = unpack(n)

			if dist < P:path_width(pi, spi, ni) and P:is_node_valid(pi, ni) and ni > this.nav_path.ni and not v.soldier.target_id then
				return true
			end
		end

		return false
	end

	local function within_nodes(v, p, max_node_distance, min_node_distance)
		if not soldier_is_within_path(v, p) then
			return false
		end

		min_node_distance = min_node_distance or 0

		local node = P:nearest_nodes(v.pos.x, v.pos.y, {p})[1][3]
		local dist = node - this.nav_path.ni

		return dist <= max_node_distance and min_node_distance <= dist
	end

	local function can_leap()
		if trigger_leap then
			return true
		end

		if this.enemy.blockers and #this.enemy.blockers > 0 then
			return false
		end

		if store.tick_ts - leap_check_ts < 0.25 then
			return false
		end

		if not enemy_ready_to_magic_attack(this, store, al) then
			return false
		end

		local np = this.nav_path
		local nodes_to_end = P:nodes_to_goal(np.pi, np.spi, np.ni)

		if nodes_to_end <= al.max_nodes_to_exit then
			return false
		end

		local targets = table.filter(store.soldiers, function(k, v)
			return not v.pending_removal and v.soldier and v.vis and v.health and not v.health.dead and band(v.vis.flags, al.vis_bans) == 0 and band(v.vis.bans, al.vis_flags) == 0 and soldier_is_within_path(v, this.nav_path.pi) and within_nodes(v, this.nav_path.pi, al.max_nodes, al.min_nodes)
		end)

		if #targets == 0 then
			return false
		end

		table.sort(targets, function(e1, e2)
			return V.dist2(e1.pos.x, e1.pos.y, this.pos.x, this.pos.y) < V.dist2(e2.pos.x, e2.pos.y, this.pos.x, this.pos.y)
		end)

		leap_target = targets[1]
		leap_check_ts = store.tick_ts
		trigger_leap = true

		return trigger_leap
	end

	local function y_bullet_fly(dest)
		this._flying = true

		local b = this.bullet

		b.from = V.vclone(this.pos)
		b.to = dest
		b.ts = store.tick_ts
		b.last_pos = V.vclone(this.pos)
		this.bullet.speed = SU.initial_parabola_speed(b.from, b.to, b.flight_time, b.g)

		local max_height = 70

		while store.tick_ts - b.ts + store.tick_length < b.flight_time do
			coroutine.yield()

			b.last_pos.x, b.last_pos.y = this.pos.x, this.pos.y
			this.pos.x, this.pos.y = SU.position_in_parabola(store.tick_ts - b.ts, b.from, b.speed, b.g)

			if this.pos.y > b.last_pos.y then
				U.animation_start(this, al.animations[2], nil, store.tick_ts, false, 1)
			else
				U.animation_start(this, al.animations[3], nil, store.tick_ts, false, 1)
			end

			local t = (store.tick_ts - b.ts) / b.flight_time
			local coly = b.from.y + (b.to.y - b.from.y) * t

			this.render.sprites[2].offset.y = coly - this.pos.y

			local height = this.pos.y - coly
			local scale = km.clamp(0.5, 1, (max_height - height) / max_height)

			this.render.sprites[2].scale = V.vv(scale)

			if b.hide_radius then
				this.render.sprites[1].hidden = V.dist(this.pos.x, this.pos.y, b.from.x, b.from.y) < b.hide_radius or V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) < b.hide_radius
			end
		end

		this.render.sprites[2].offset.y = 0
		this._flying = false
	end

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if trigger_leap then
				local dir = this.pos.x > leap_target.pos.x and 1 or -1
				local target_pos = V.v(leap_target.pos.x + this.enemy.melee_slot.x * dir, leap_target.pos.y + this.enemy.melee_slot.y)

				if not P:point_within_distance(target_pos.x, target_pos.y, P:path_width(this.nav_path.pi)) then
					target_pos = V.v(leap_target.pos.x + this.enemy.melee_slot.x * dir * -1, leap_target.pos.y + this.enemy.melee_slot.y)
				end

				local af = this.pos.x > target_pos.x

				U.set_heading(this, target_pos)
				U.y_animation_play(this, al.animations[1], af, store.tick_ts, 1, 1)
				U.animation_start(this, al.animations[2], nil, store.tick_ts, false, 1)

				if not this._leap_bans_added then
					U.bans_add(this.vis, F_ALL)
					this._leap_bans_added = true
				end

				this.render.sprites[1].z = Z_BULLETS

				y_bullet_fly(target_pos)

				this.render.sprites[1].z = Z_OBJECTS

				if this._leap_bans_added then
					U.bans_remove(this.vis, F_ALL)
					this._leap_bans_added = nil
				end

				local np = this.nav_path
				local nn = P:nearest_nodes(this.pos.x, this.pos.y, {np.pi}, {1, 2, 3}, true)[1]

				np.spi = nn[2]
				np.ni = nn[3]

				if leap_target then
					U.set_heading(this, leap_target.pos)
				end

				U.y_animation_play(this, al.animations[4], nil, store.tick_ts, 1, 1)

				trigger_leap = false
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, can_leap) then
			-- block empty
			else
				coroutine.yield()
			end
		end
	end
end

scripts.enemy_son_of_sarelgaz = {}

function scripts.enemy_son_of_sarelgaz.update(this, store, script)
	local ac = this.timed_attacks.list[1]
	local trap_check_ts = store.tick_ts

	ac.ts = store.tick_ts

	local trigger_trap

	local function can_trap()
		if trigger_trap then
			return true
		end

		if store.tick_ts - trap_check_ts < 0.25 then
			return false
		end

		if store.tick_ts - ac.ts < ac.cooldown then
			return false
		end

		local bl = this.enemy.blockers

		if not bl or #bl == 0 then
			return false
		end

		trigger_trap = false
		this.blocker_to_cocoon = nil

		for i, bi in ipairs(bl) do
			local b = store.entities[bi]

			if b.unit and not b.unit.ignore_stun and not b.unit.is_stunned and band(ac.vis_flags, b.vis.bans) == 0 and band(ac.vis_bans, b.vis.flags) == 0 then
				this.blocker_to_cocoon = b
				trigger_trap = true

				break
			end
		end

		if not trigger_trap then
			return false
		end

		trap_check_ts = store.tick_ts

		return trigger_trap
	end

	if this.spawned_from_egg then
		U.y_animation_play(this, "out", nil, store.tick_ts, 1, 1)
	end

	::label_202_0::

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if trigger_trap then
				S:queue(ac.sound, ac.sound_args)

				if this.blocker_to_cocoon and not SU.y_wait_for_blocker(store, this, this.blocker_to_cocoon) then
					this.blocker_to_cocoon = nil

					goto label_202_0
				end

				trigger_trap = false
				ac.ts = store.tick_ts

				U.animation_start(this, ac.animation, nil, store.tick_ts, false)

				if SU.y_enemy_wait(store, this, ac.trap_time) then
					goto label_202_0
				end

				if not this.health.dead and not this.unit.is_stunned and this.blocker_to_cocoon and table.contains(this.enemy.blockers, this.blocker_to_cocoon.id) and not this.blocker_to_cocoon.health.dead and store.entities[this.blocker_to_cocoon.id] then
					local cocoon = E:create_entity(ac.mod)

					cocoon.pos.x, cocoon.pos.y = this.blocker_to_cocoon.pos.x, this.blocker_to_cocoon.pos.y
					cocoon.modifier.target_id = this.blocker_to_cocoon.id

					simulation:queue_insert_entity(cocoon)
					U.unblock_target(store, this.blocker_to_cocoon)
				end

				U.y_animation_wait(this)
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, can_trap, can_trap) then
			-- block empty
			else
				coroutine.yield()
			end
		end
	end
end

scripts.decal_spider_egg = {}

function scripts.decal_spider_egg.update(this, store, script)
	local nest = store.entities[this.source_id]

	U.y_animation_wait(this, 1, 1)
	U.animation_start(this, this.anim_idle, nil, store.tick_ts, true)

	local o = {}
	local ts = store.tick_ts

	while store.tick_ts - ts < this.time_to_spawn do
		if this.burn then
			nest.has_eggs = false

			S:queue(this.sound_events.death)
			U.animation_start(this, this.anim_dead, nil, store.tick_ts)

			goto label_204_0
		end

		coroutine.yield()
	end

	if nest then
		nest.has_eggs = false
	end

	U.animation_start(this, this.anim_hatch, nil, store.tick_ts)
	U.y_wait(store, this.hatch_spawn_delay)
	S:queue(this.sound_events.hatch)

	for i = 1, SU.get_difficulty_field_value(store, this.hatch_amount) do
		local e = E:create_entity(this.spawn_e)

		e.spawned_from_egg = true
		e.pos.x, e.pos.y = this.pos.x + km.rand_sign() * U.frandom(this.spawn_offset_min, this.spawn_offset_max), this.pos.y + km.rand_sign() * U.frandom(this.spawn_offset_min, this.spawn_offset_max)
		e.nav_path.pi = this.path_id

		local subpath = get_random_round_robin(o, 3)

		e.nav_path.spi = subpath
		e.nav_path.ni = P:nearest_nodes(e.pos.x, e.pos.y, {this.path_id}, {subpath}, true)[1][3]
		e.enemy.gold = 0

		simulation:queue_insert_entity(e)

		if not U.is_seen(store, this.spawn_e) then
			signal.emit("wave-notification", "icon", this.spawn_e)
			U.mark_seen(store, this.spawn_e)
		end

		U.y_wait(store, this.delay_between_spawns)
	end

	::label_204_0::

	U.y_animation_wait(this, 1, 1)
	simulation:queue_remove_entity(this)
end

scripts.mod_shake_sprite = {}

function scripts.mod_shake_sprite.update(this, store, script)
	local m = this.modifier
	local target = store.entities[m.target_id]
	local time_left = m.duration
	local base_offset = V.vclone(target.render.sprites[1].offset)

	while time_left > 0 do
		time_left = time_left - store.tick_length

		local decay = time_left / m.duration

		target.render.sprites[1].offset.x = base_offset.x + (math.random() * 2 - 1) * m.intensity * decay
		target.render.sprites[1].offset.y = base_offset.y + (math.random() * 2 - 1) * m.intensity * decay

		coroutine.yield()
	end

	target.render.sprites[1].offset.x = base_offset.x
	target.render.sprites[1].offset.y = base_offset.y

	simulation:queue_remove_entity(this)
end

-- ==================== KR6 rappel / 远程平衡 通用脚本（关卡 211 等使用） ====================
scripts.decal_rappel_utils = {}

function scripts.decal_rappel_utils.set_y(this, store)
	local min_y = (store.visible_coords and store.visible_coords.top or REF_H) + 100
	local ideal_distance = 500
	local dist = math.abs(this.target_pos.y - min_y)
	local start_y = min_y

	if dist < ideal_distance then
		start_y = start_y + ideal_distance
	end

	return start_y
end

function scripts.decal_rappel_utils.y_descend(this, store)
	S:queue(this.sound_events.rappel_down)

	local string = E:create_entity(this.string_t)

	string.target_id = this.id

	queue_insert(store, string)

	local shadow = E:create_entity(this.shadow_t)

	shadow.pos.x, shadow.pos.y = this.target_pos.x, this.target_pos.y
	shadow.render.sprites[1].ts = store.tick_ts

	queue_insert(store, shadow)

	local start_y = this.pos.y
	local max_height = start_y - shadow.pos.y
	local a = 1

	U.y_ease_key(store, this.pos, "y", start_y, this.target_pos.y + this.offset_drop, this.descend_rappel_duration, this.descend_rappel_ease, function(dt, p)
		local height = this.pos.y - shadow.pos.y
		local scale = km.clamp(0.2, 1, (max_height - height) / max_height)

		shadow.render.sprites[1].scale = V.vv(scale)

		local dy = this.pos.y - this.target_pos.y
		local s = this.render.sprites[1]
		local flight_height = this.rappel_flight_height and this.rappel_flight_height or 180

		if flight_height <= dy then
			s.z = Z_FLYING_HEROES
		else
			s.z = Z_OBJECTS
		end

		s.sort_y_offset = -dy + this.offset_extra

		for i, v in ipairs(string.render.sprites) do
			local syo = v.offset.y

			v.sort_y_offset = -syo

			local dy = string.pos.y + v.offset.y - this.target_pos.y

			if flight_height <= dy then
				v.z = Z_FLYING_HEROES
			else
				v.z = Z_OBJECTS
			end
		end

		if this.animation_rappel_descent_sequence and a <= #this.animation_rappel_descent_sequence and dt > this.animation_rappel_descent_sequence[a][2] then
			U.animation_start(this, this.animation_rappel_descent_sequence[a][1], nil, store.tick_ts, nil, 1)

			a = a + 1
		end
	end)

	return shadow, string, max_height
end

function scripts.decal_rappel_utils.y_ascend(this, store, start_y, max_height, shadow, string)
	S:queue(this.sound_events.rappel_up)
	U.y_ease_key(store, this.pos, "y", this.pos.y, start_y, this.ascend_rappel_duration, this.ascend_rappel_ease, function(dt, p)
		if shadow then
			local height = this.pos.y - shadow.pos.y
			local scale = km.clamp(0.1, 1, (max_height - height) / max_height)

			shadow.render.sprites[1].scale = V.vv(scale)
		end

		local dy = this.pos.y - this.target_pos.y
		local s = this.render.sprites[1]
		local flight_height = 180

		if flight_height <= dy then
			s.z = Z_FLYING_HEROES
		else
			s.z = Z_OBJECTS
		end

		s.sort_y_offset = -dy + this.offset_extra

		if string then
			for i, v in ipairs(string.render.sprites) do
				local dy = this.pos.y - v.offset.y - this.target_pos.y

				v.sort_y_offset = -dy
			end
		end
	end)
end

scripts.decal_rappel_string = {}

function scripts.decal_rappel_string.insert(this, store, script)
	local rhp = math.ceil(REF_H / this.string_parts)

	for i = 1, rhp do
		local s = E:clone_c("sprite")

		s.animated = this.is_animated

		if s.animated then
			s.prefix = this.string_prefix
			s.name = this.string_start_anim
		elseif this.string_start_anim then
			s.name = this.string_prefix .. "_" .. this.string_start_anim
		else
			s.name = this.string_prefix
		end

		s.loop = false
		s.anchor.y = 0
		s.offset.y = this.string_offset + (i - 1) * this.string_parts
		s.scale = v(1, 1)
		this.render.sprites[i] = s
	end

	return true
end

function scripts.decal_rappel_string.update(this, store, script)
	local target = store.entities[this.target_id]

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	local eases = {
		linear = function(x)
			return x
		end,
		e_o_quad = function(x)
			return 1 - (1 - x) * (1 - x)
		end,
		e_i_quad = function(x)
			return x * x
		end,
		e_o_cubic = function(x)
			return 1 - (1 - x) * (1 - x) * (1 - x)
		end,
		e_i_cubic = function(x)
			return x * x * x
		end,
		e_i_quint = function(x)
			return x * x * x * x * x
		end,
		e_i_circ = function(x)
			return 1 - math.sqrt(1 - x * x)
		end
	}

	local function map_range_01(start, finish, value)
		return (value - start) / (finish - start)
	end

	local next_to_dissolve = 0
	local last_dissolved = 0
	local dissolving = false
	local moving = false
	local easing = false
	local t, tm = 0, 0
	local top_y = store.visible_coords and store.visible_coords.top or REF_H

	this.pos = target.pos

	while true do
		target = store.entities[this.target_id]

		if not target or this.dissolve then
			this.pos = V.vclone(this.pos)
			this.render.sprites[1].hidden = true
			dissolving = true
			moving = true
			easing = true

			local dist = top_y - this.pos.y
			local start_y = this.pos.y

			while easing do
				local x = map_range_01(0, this.dissolution_duration, t)
				local xm = map_range_01(0, this.dissolution_movement_duration, tm)
				local p = eases[this.dissolution_ease](x)
				local pm = eases[this.dissolution_movement_ease](xm)

				next_to_dissolve = math.floor(#this.render.sprites * p)

				if moving then
					this.pos.y = start_y + dist * pm
				end

				if dissolving and last_dissolved < next_to_dissolve then
					for i = last_dissolved + 1, next_to_dissolve do
						local s = this.render.sprites[i]

						if s.prefix then
							s.name = "end"
						else
							-- 静态绳索没有独立的 "end" 帧，直接隐藏该段避免查表报错
							s.hidden = true
						end

						s.ts = store.tick_ts
						last_dissolved = i
					end
				end

				if x >= 1 then
					dissolving = false
				end

				if xm >= 1 then
					moving = false
				end

				if x >= 1 and xm >= 1 then
					easing = false
				end

				coroutine.yield()

				t = t + store.tick_length
				tm = tm + store.tick_length
			end

			U.y_wait(store, fts(10))
			queue_remove(store, this)

			return
		end

		coroutine.yield()
	end
end

scripts.controller_remote_balance_rappel_spawning = {}

function scripts.controller_remote_balance_rappel_spawning.update(this, store, script)
	local spawners = kr6_find_all_t(store, this.spawner_t)

	table.sort(spawners, function(v1, v2)
		return v1.spawner_id < v2.spawner_id
	end)

	while true do
		if this.cache_invalidated then
			this.cache_invalidated = false
			spawners = kr6_find_all_t(store, this.spawner_t)

			table.sort(spawners, function(v1, v2)
				return v1.spawner_id < v2.spawner_id
			end)
		end

		if this.spawn_rappel then
			this.spawn_rappel = false

			local mid = this.marker_id == -1 and math.random(1, #spawners) or this.marker_id
			local sp = spawners[mid]

			sp.amount = this.amount
			sp.path_id = this.path_id
			sp.trigger_spawn = true
		end

		coroutine.yield()
	end
end

function scripts.controller_remote_balance_rappel_spawning.on_event(this, store, action, marker_id, path_id, amount)
	this.spawn_rappel = true
	this.marker_id = tonumber(marker_id)
	this.path_id = tonumber(path_id)
	this.amount = tonumber(amount)
end

scripts.controller_remote_balance_rappel_spawner = {}

function scripts.controller_remote_balance_rappel_spawner.update(this, store, script)
	local start_y = store.visible_coords and store.visible_coords.top or REF_H

	while true do
		if this.trigger_spawn then
			this.trigger_spawn = false

			local o = {}
			local path = this.path_id
			local current_node = P:nearest_nodes(this.pos.x, this.pos.y, {path}, nil, true)[1][3]

			for i = 1, this.amount do
				local subpath = get_random_round_robin(o, 3)
				local r = math.random(-this.node_random, this.node_random)
				local node = km.clamp(P:get_start_node(path), P:get_end_node(path), current_node + r)
				local fpos = P:node_pos(path, subpath, node)
				local decal = E:create_entity(this.spawn_decal)

				decal.pos = V.v(fpos.x, start_y)
				decal.target_pos = V.vclone(fpos)
				decal.render.sprites[1].flip_x = this.flip_spawns and this.flip_spawns or false
				decal.pi = path
				decal.spi = subpath
				decal.ni = node

				queue_insert(store, decal)
				U.y_wait(store, U.frandom(0, this.wait_random))
			end
		end

		coroutine.yield()
	end
end

-- ==================== kr6 stage14：dark_army 敌人脚本 ====================

scripts.enemy_skeleton_kr6 = {}

function scripts.enemy_skeleton_kr6.insert(this, store, script)
	if not scripts.enemy_basic.insert(this, store, script) then
		return false
	end

	if this.render.sprites[1].name == "raise" then
		this._raise_ignore_damage = this.health.ignore_damage

		if not this._raise_bans_added then
			this._raise_bans_added = true
			U.bans_add(this.vis, F_ALL)
		end

		this.health.ignore_damage = true
		this.health_bar.hidden = true
	end

	return true
end

function scripts.enemy_skeleton_kr6.update(this, store, script)
	if this.render.sprites[1].name == "raise" then
		if this.sound_events and this.sound_events.raise then
			S:queue(this.sound_events.raise, this.sound_events.raise_args)
		end

		local an, af = U.animation_name_facing_point(this, "raise", this.motion.dest)

		U.y_animation_play(this, an, af, store.tick_ts, 1)

		if not this.health.dead then
			this.health_bar.hidden = nil
		end

		if this._raise_bans_added then
			U.bans_remove(this.vis, F_ALL)
			this._raise_bans_added = nil
			this.health.ignore_damage = this._raise_ignore_damage
		end

		U.animation_start(this, "idle", af, store.tick_ts, true)
	end

	return scripts.enemy_mixed.update(this, store, script)
end

scripts.enemy_gargoyle_kr6 = {}

function scripts.enemy_gargoyle_kr6.update(this, store)
	local heal_uses = 0
	local in_stone_form = false
	local old_prefix = this.render.sprites[1].prefix
	local sf = this.stone_form
	local sf_duration = SU.get_difficulty_field_value(store, sf.duration)

	local function check_enter_stone_form()
		return heal_uses < sf.max_heal_uses and this.health.hp < sf.trigger_hp
	end

	local function exit_stone_form()
		U.flags_add(this.vis, F_FLYING)
		U.bans_add(this.vis, F_BLOCK)
		U.bans_remove(this.vis, bor(F_SCARE, F_MOCKING))

		U.animation_start(this, sf.heal_out_anim, nil, store.tick_ts, false, 1)
		U.y_wait(store, fts(12))

		this._current_height = 0

		U.y_ease_key(store, this, "_current_height", 0, this.flight_height, sf.rise_duration, sf.ease_up, function(dt, p)
			this.render.sprites[1].offset.y = this._current_height
			U.change_health_bar_offset_run_time(this.health_bar, this._current_height + 25 + 15)
			this.ui.click_rect.pos.y = this._current_height - 15 + 20
			this.unit.hit_offset.y = this._current_height + 5 + 10
			this.unit.mod_offset.y = this._current_height + 2 + 10
		end)
		U.y_animation_wait(this, 1)

		in_stone_form = false
		sf.used = true
		this.render.sprites[1].prefix = old_prefix
		SU.armor_dec(this, sf.armor_inc)
		SU.magic_armor_dec(this, sf.magic_armor_inc)

		U.animation_start(this, "walk", nil, store.tick_ts, true, 1)

		return true
	end

	while true do
		if this.health.dead or (heal_uses < sf.max_heal_uses and this.health.hp < sf.trigger_hp) then
			if band(this.health.last_damage_types, bor(DAMAGE_INSTAKILL, DAMAGE_EAT)) ~= 0 then
				simulation:queue_remove_entity(this)

				return
			end

			if heal_uses < sf.max_heal_uses then
				in_stone_form = true
				heal_uses = heal_uses + 1
				this.health.hp = sf.trigger_hp
				this.health.dead = false
				this.health_bar.hidden = false

				S:queue(this.sound_events.death)

				this.health.ignore_damage = true

				U.y_animation_play(this, sf.fall_in_anim, nil, store.tick_ts, 1, 1)

				SU.armor_inc(this, sf.armor_inc)
				SU.magic_armor_inc(this, sf.magic_armor_inc)

				U.animation_start(this, sf.fall_loop_anim, nil, store.tick_ts, true, 1)

				this._current_height = this.flight_height

				U.y_ease_key(store, this, "_current_height", this.flight_height, sf.floor_height, sf.lower_duration, sf.ease_down, function(dt, p)
					this.render.sprites[1].offset.y = this._current_height
					U.change_health_bar_offset_run_time(this.health_bar, this._current_height + 25 + 15)
					this.ui.click_rect.pos.y = this._current_height - 15 + 20
					this.unit.hit_offset.y = this._current_height + 5 + 10
					this.unit.mod_offset.y = this._current_height + 2 + 10
				end)

				this.health.ignore_damage = false

				S:queue(sf.sound)

				U.flags_remove(this.vis, F_FLYING)
				U.bans_remove(this.vis, F_BLOCK)
				U.bans_add(this.vis, bor(F_SCARE, F_MOCKING))

				U.y_animation_play(this, sf.fall_out_anim, nil, store.tick_ts, 1, 1)
				U.animation_start(this, sf.heal_anim, nil, store.tick_ts, true, 1)

				local mod = E:create_entity(sf.mod)

				mod.modifier.target_id = this.id
				mod.modifier.source_id = this.id

				simulation:queue_insert_entity(mod)

				this.render.sprites[1].prefix = this.stone_form.anim_prefix

				local ts = store.tick_ts

				repeat
					if this.health.dead then
						if band(this.health.last_damage_types, bor(DAMAGE_INSTAKILL)) ~= 0 then
							simulation:queue_remove_entity(this)

							return
						end

						goto label_212_0
					end

					coroutine.yield()
				until sf_duration < store.tick_ts - ts

				exit_stone_form()

				goto label_212_1
			end

			::label_212_0::

			if in_stone_form then
				this.render.sprites[1].prefix = old_prefix
				this.unit.death_animation = sf.death_anim
			end

			SU.y_enemy_death(store, this)

			return
		end

		::label_212_1::

		SU.y_enemy_walk_until_blocked(store, this, false, check_enter_stone_form)
		coroutine.yield()
	end
end

function scripts.enemy_gargoyle_kr6.remove(this, store)
	if not this.stone_form.used then
		signal.emit("stone-cold-dead")
	end

	return true
end

-- ==================== kr6 stage14：特殊塔 / 墓地控制器 ====================

local function find_all_t(store, template_name, contains, fn)
	if not store or not store.entities then
		return {}
	end

	return table.filter(store.entities, function(k, val)
		return (contains and string.find(val.template_name, template_name) or val.template_name == template_name) and (not fn or fn(k, val))
	end)
end

-- controller_graveyard_kr6（KR6 版墓地控制器，带 associated_decal 动画）
scripts.controller_graveyard_kr6 = {}

function scripts.controller_graveyard_kr6.update(this, store)
	local animation_decal = find_all_t(store, this.associated_decal)[1]
	local anim_ts = store.tick_ts
	local g = this.graveyard

	while not this.interrupt do
		local targets = table.filter(store.entities, function(k, v)
			return not v._in_graveyard and v.health and v.health.dead and band(v.vis.flags, g.vis_has) ~= 0 and band(v.vis.flags, g.vis_bans) == 0 and band(v.vis.bans, g.vis_flags) == 0 and store.tick_ts - v.health.death_ts >= g.dead_time and (not v.reinforcement or not v.reinforcement.hp_before_timeout) and (not g.excluded_templates or not table.contains(g.excluded_templates, v.template_name))
		end)

		if #targets == 0 then
			U.y_wait_unconditional(store, g.check_interval)
		else
			if animation_decal and store.tick_ts - anim_ts > this.animation_cooldown then
				U.animation_start(animation_decal, this.animation, nil, store.tick_ts, false, 1)
				anim_ts = store.tick_ts
			end

			for _, t in ipairs(targets) do
				if this.interrupt then
					return
				end

				t._in_graveyard = true

				for _, s in ipairs(g.spawns_by_health) do
					local e, s_pos, pi, spi, ni

					if t.health.hp_max > s[2] then
					-- block empty
					else
						s_pos = table.random(g.spawn_pos)

						local nearest_nodes = P:nearest_nodes(s_pos.x, s_pos.y, g.pi and {g.pi} or nil, {1, 2, 3})

						if #nearest_nodes < 1 then
							log.error("graveyard controller %s could not spawn enemy. node not found near %s,%s", this.id, s_pos.x, s_pos.y)
						else
							pi, spi, ni = unpack(nearest_nodes[1])
							e = E:create_entity(s[1])
							e.nav_path.pi, e.nav_path.spi, e.nav_path.ni = pi, spi, ni
							e.pos = V.vclone(s_pos)
							e.render.sprites[1].name = "raise"
							e.motion.forced_waypoint = P:node_pos(e.nav_path.pi, e.nav_path.spi, e.nav_path.ni)

							if not g.keep_gold and e.enemy then
								e.enemy.gold = 0
							end

							simulation:queue_insert_entity(e)

							break
						end
					end
				end

				U.y_wait_unconditional(store, g.spawn_interval)
			end
		end
	end

	simulation:queue_remove_entity(this)
end

-- ==================== kr6 stage15：新敌人脚本 ====================

scripts.enemy_dark_disciple = {}

function scripts.enemy_dark_disciple.update(this, store, script)
	local ab = this.timed_attacks.list[1]
	local trigger_tower_block
	local book_in_hand = true
	local tower_to_block
	local block_ts = store.tick_ts - ab.block_cooldown
	local block_max_range = SU.get_difficulty_field_value(store, ab.max_range)
	local block_tether_range = SU.get_difficulty_field_value(store, ab.tether_range)

	this.recall_book = false
	this.mark_mod = nil

	local function find_first_tower()
		local towers = U.find_towers_in_range(store.towers, this.pos, {
			min_range = ab.min_range,
			max_range = block_max_range
		}, function(v, o)
			return v.tower.type ~= "holder" and v.tower.type ~= "build_animation" and v.vis and band(v.vis.flags, ab.vis_bans) == 0 and band(v.vis.bans, ab.vis_flags) == 0 and (not v.tower_holder or not v.tower_holder.blocked) and v.tower.can_be_mod and not SU.has_modifiers(store, v, ab.mark_mod) and not U.has_modifier_types(store, v, MOD_TYPE_PROTECTION)
		end)

		if not towers or #towers == 0 then
			return nil
		end

		table.sort(towers, function(v1, v2)
			local dist2_v1 = V.dist2(this.pos.x, this.pos.y, v1.pos.x, v1.pos.y)
			local dist2_v2 = V.dist2(this.pos.x, this.pos.y, v2.pos.x, v2.pos.y)

			return dist2_v1 < dist2_v2
		end)

		return towers[1]
	end

	local function should_block_tower()
		if not this.enemy.can_do_magic then
			return false
		end

		tower_to_block = find_first_tower()
		trigger_tower_block = tower_to_block and book_in_hand and store.tick_ts - ab.ts > ab.cooldown and #this.enemy.blockers == 0 and store.tick_ts - block_ts > ab.block_cooldown

		return trigger_tower_block
	end

	local function remove_mark()
		if this.mark_mod then
			queue_remove(store, this.mark_mod)

			this.mark_mod = nil
		end
	end

	local function book_call(from_walk)
		this.recall_book = true

		U.y_animation_play(this, "attack_in", nil, store.tick_ts, 1)

		book_in_hand = true

		if not from_walk then
			this.render.sprites[1].prefix = "dark_disciple_creep_book"
		end

		ab.ts = store.tick_ts

		remove_mark()

		if from_walk then
			U.y_animation_play(this, "attack_out", nil, store.tick_ts, 1)
		end
	end

	local function walk_break()
		if this.recall_book then
			this.recall_book = false
		end

		if this.mark_mod then
			local target = store.entities[this.mark_mod.modifier.target_id]

			if not target then
				book_call(true)
			end

			if target and not U.is_inside_ellipse(target.pos, this.pos, block_tether_range) then
				book_call(true)
			end
		end

		return should_block_tower()
	end

	local function melee_break()
		if not book_in_hand then
			book_call(false)
		end

		return false
	end

	local function range_break()
		if not book_in_hand then
			book_call(false)
		end

		return false
	end

	::label_218_0::

	while true do
		if this.health.dead then
			this.recall_book = true

			remove_mark()
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			this.recall_book = true

			remove_mark()
			SU.y_enemy_stun(store, this)
		else
			if trigger_tower_block then
				S:queue(ab.sound_channel)

				this.mark_mod = E:create_entity(ab.mark_mod)
				this.mark_mod.modifier.target_id = tower_to_block.id
				this.mark_mod.modifier.source_id = this.id

				queue_insert(store, this.mark_mod)

				local af = tower_to_block.pos.x < this.pos.x

				U.animation_start(this, ab.animation, af, store.tick_ts, false)
				S:queue(ab.sound)

				trigger_tower_block = false

				if SU.y_enemy_wait(store, this, ab.cast_time) then
					goto label_218_0
				end

				local final_tower_to_block = tower_to_block

				if not final_tower_to_block or not store.entities[final_tower_to_block.id] or final_tower_to_block.pending_removal then
					queue_remove(store, this.mark_mod)

					this.mark_mod = nil
					final_tower_to_block = find_first_tower()
				end

				if not final_tower_to_block then
					SU.delay_attack(store, ab, fts(10))
				else
					local af = final_tower_to_block.pos.x < this.pos.x

					this.render.sprites[1].flip_x = af

					if not this.mark_mod then
						this.mark_mod = E:create_entity(ab.mark_mod)
						this.mark_mod.modifier.target_id = final_tower_to_block.id
						this.mark_mod.modifier.source_id = this.id

						queue_insert(store, this.mark_mod)
					end

					local af = this.render.sprites[1].flip_x
					local bullet = E:create_entity(ab.bullet)
					local offset = ab.bullet_start_offset

					bullet.pos = V.v(this.pos.x + offset.x * (af and -1 or 1), this.pos.y + offset.y)
					bullet.bullet.from = V.vclone(bullet.pos)

					local tower_name = string.sub(final_tower_to_block.template_name, string.len(this.tower_prefix) + 1, string.len(final_tower_to_block.template_name))
					local offset_height = ab.custom_heights[tower_name] or ab.default_height

					bullet.bullet.to = V.v(final_tower_to_block.pos.x, final_tower_to_block.pos.y + offset_height)
					bullet.bullet.target_id = final_tower_to_block.id
					bullet.bullet.source_id = this.id

					queue_insert(store, bullet)

					ab.ts = store.tick_ts
					book_in_hand = false

					U.y_animation_wait(this)
				end
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, walk_break, melee_break, range_break) then
				goto label_218_0
			else
				block_ts = store.tick_ts
			end

			coroutine.yield()
		end
	end
end

